window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0127", [{"word":"empire","ipa_uk":"/ˈempaɪə/","ipa_us":"/ˈempaɪər/","definition_zh":"帝国；由一位最高统治者统辖的大片疆域；帝国的最高治权；庞大的企业集团；某一帝王统治的时代","definition_en":"a group of territories ruled by a single supreme authority, or the authority itself; also a large commercial group and the period of an emperor's rule","core_image":"一张铺满地图的长桌，中央一枚权杖压着整片疆域，四周的道路都通向同一枚印章","scene":"历史课的沙盘上，旗帜插满整块大陆，所有道路都通向同一座宫殿。The old maps show an empire stretching from the mountains to the sea.","sceneCN":"这里 empire 指「由一位最高统治者统辖的整片疆域」（第 1 个义项：多个地区与民族被纳入同一权力中心）；句意为旧地图上，一个从山地一直延伸到海边的帝国被完整画出。可辨识物件：沙盘、旗帜、宫殿、道路、地图。","pos":[{"tag":"n.","zh":"帝国；帝国疆域；最高治权；大企业集团；帝国时代"}],"collocations":[{"phrase":"the Roman Empire","zh":"罗马帝国"},{"phrase":"empire building","zh":"扩张版图；建立大集团"},{"phrase":"a business empire","zh":"商业帝国；庞大企业集团"},{"phrase":"the decline of an empire","zh":"帝国的衰落"},{"phrase":"a colonial empire","zh":"殖民帝国"},{"phrase":"empire-wide","zh":"全帝国范围的"}],"forms":[{"label":"单数","form":"empire"},{"label":"复数","form":"empires"},{"label":"形容词（帝国的）","form":"imperial"},{"label":"名词（皇帝）","form":"emperor"},{"label":"名词（帝国主义）","form":"imperialism"}],"derivatives":[{"word":"imperial","pos":"adj.","zh":"imperium + -ialis（关系形容词后缀）→ 由「治权」转为「帝国的、皇帝的」"},{"word":"imperially","pos":"adv.","zh":"imperial + -ly（副词后缀）→ 以帝王气派地"},{"word":"emperor","pos":"n.","zh":"imperator（统帅）经古法语演变 → 皇帝，语义由「军事指挥权」收窄为「帝国君主」"},{"word":"empress","pos":"n.","zh":"emperor + -ess（阴性后缀）→ 女皇、皇后"},{"word":"imperialism","pos":"n.","zh":"imperial + -ism（主义、体系后缀）→ 帝国主义"},{"word":"imperialist","pos":"n./adj.","zh":"imperial + -ist（从事者后缀）→ 帝国主义者；帝国主义的"},{"word":"imperialistic","pos":"adj.","zh":"imperialist + -ic（形容词后缀）→ 带扩张色彩的"}],"senses":[{"no":"01","title":"A realm under one supreme ruler","titleCN":"由一个最高统治者统辖的整片疆域","definition":"a group of countries or peoples governed from one centre by a single supreme authority","definitionCN":"若干净土或民族由同一个中心、同一位最高权威统辖","example":"The empire was governed from a single capital and taxed through provincial governors.","exampleCN":"这个帝国由一座首都统一治理，并通过各行省总督征税。","why":"Latin imperium first named the power to command, and the land that power covered took the same name.","whyCN":"拉丁 imperium 最初指「发号施令的权力」，这块权力覆盖的土地随后也叫作 empire。"},{"no":"02","title":"Supreme command as an abstract power","titleCN":"抽象的至高统治权","definition":"the authority to command others, considered apart from any particular territory","definitionCN":"指挥他人的权力本身，不限于某片具体领土","example":"Command of the legions gave him effective empire over three provinces.","exampleCN":"掌握军团使他实际上对三个行省拥有了统治权。","why":"In Roman usage imperium was a legal power before it was a place, and English kept that abstract reading alongside the territorial one.","whyCN":"在罗马用法中，imperium 先是法律权力、后才是地盘，英语把这一抽象义与领土义一并保留。"},{"no":"03","title":"A state headed by an emperor","titleCN":"以皇帝为国家元首的国家","definition":"a state whose formal head bears the title of emperor or empress","definitionCN":"正式元首拥有皇帝或女皇称号的国家","example":"By 1804 France had become an empire under Napoleon.","exampleCN":"到 1804 年，法国在拿破仑治下已成为一个帝国。","why":"Once a ruler took the imperial title, the state was renamed to match, so the word shifted from dominion to a type of polity.","whyCN":"统治者一旦采用皇帝称号，国家也随之改名，于是这个词从「疆域」转为「一种政体」。"},{"no":"04","title":"A large business group under one control","titleCN":"由一个中心控制的大型企业集团","definition":"a very large group of companies or properties controlled by one person or family","definitionCN":"由一个人或一个家族控制的庞大公司群或产业群","example":"The family built an empire of hotels along the coast.","exampleCN":"这个家族沿海岸建起了一个酒店帝国。","why":"Nineteenth-century writers transferred the language of territorial command to markets, since a chain of shops can be run like a chain of provinces.","whyCN":"十九世纪作家把领土统治的说法移到市场上，因为一串店铺也能像一串行省那样被治理。"},{"no":"05","title":"An informal sphere of influence","titleCN":"没有正式统治名义的势力范围","definition":"a region where a foreign power or firm dominates trade and politics without annexing it","definitionCN":"外国势力或公司支配其贸易与政治、却不正式吞并的地区","example":"The company ran a commercial empire in the delta, though no flag flew there.","exampleCN":"这家公司在三角洲经营着一个商业帝国，尽管那里没有升起它的旗帜。","why":"Control can be exercised through loans, tariffs and shipping lanes, so empire came to describe power without a formal title.","whyCN":"通过贷款、关税与航线同样能施加控制，因此 empire 也指没有正式名分的支配。"},{"no":"06","title":"A private domain ruled absolutely","titleCN":"个人绝对掌控的小天地","definition":"a small area of activity that a person controls completely and without interference","definitionCN":"一个人完全掌控、不容他人插手的小范围活动领域","example":"She ruled a small empire of kitchens and storerooms.","exampleCN":"她经营着一片由厨房与储藏室构成的小天地。","why":"The playful use keeps the core of unchecked command but shrinks the territory to a household scale.","whyCN":"这一戏谑用法保留了「不受制约的指挥」这一核心，只把疆域缩小到家务范围。"},{"no":"07","title":"A style named after an emperor","titleCN":"以帝王命名的风格","definition":"a decorative style in furniture and dress associated with an imperial court, especially that of Napoleon","definitionCN":"与宫廷相关的家具与服饰风格，尤指拿破仑时期的式样","example":"The salon was furnished in the empire style, with mahogany and gilt bronze.","exampleCN":"这间客厅按帝国风格布置，用的是桃花心木与镀金铜饰。","why":"Craftsmen named the severe classical style after the regime that patronised it, so a political empire became a label for taste.","whyCN":"工匠以赞助该风格的政权为其命名，于是政治上的帝国变成了品味标签。"},{"no":"08","title":"The era of imperial rule","titleCN":"帝国统治的时期","definition":"the period during which a particular empire or emperor governed","definitionCN":"某个帝国或某位皇帝在位统治的那段时期","example":"The roads were laid during the empire and survived its fall.","exampleCN":"这些道路建于帝国时期，并在帝国灭亡后留存下来。","why":"Metonymy let the name of the realm stand for the span of its existence, as historians speak of building in the empire.","whyCN":"转喻让疆域之名代表其存在的时段，史家常说「在帝国时期」修建。"}],"etymology":{"intro":{"en":"Empire reaches English through Old French from Latin imperium 'command, authority', a noun built on imperare 'to command', itself in- 'upon' plus parare 'to arrange'. Dates are approximate.","cn":"empire 经古法语来自拉丁 imperium「命令、治权」，该名词由 imperare「命令」构成，而 imperare 又是 in-「向」加 parare「安排」。年代均为约数。"},"items":[{"era":"LATIN PARARE","en":"Parare meant 'to prepare, arrange, make ready'. Its deeper origin is not established; the link sometimes drawn to parere 'to bring forth' is a hypothesis rather than a demonstrated derivation.","cn":"parare 意为「准备、安排、使就绪」。其更深来源未有定论；有人把它与 parere「生出、产生」联系，那只是假说，并非已证实的派生。"},{"era":"LATIN IMPERARE","en":"In- 'upon' plus parare produced imperare 'to command, to order', literally to arrange something upon someone.","cn":"in-「向、加于」加 parare 构成 imperare「命令、吩咐」，字面是把事情安排到某人头上。"},{"era":"LATIN IMPERIUM","en":"The noun imperium named supreme command, the power to levy troops and enforce justice; Roman law kept it distinct from dominium 'ownership'.","cn":"名词 imperium 指最高指挥权，即征兵与执法的权力；罗马法把它与 dominium「所有权」明确区分。"},{"era":"LATIN IMPERATOR","en":"Imperator 'commander' was the title troops acclaimed for a victorious general; from it English took emperor.","cn":"imperator「统帅」是士兵对得胜将领的欢呼称号；英语的 emperor 即由此而来。"},{"era":"OLD FRENCH EMPIRE","en":"Old French empire carried the noun into English in the thirteenth century, at first for a ruler's dominions.","cn":"古法语 empire 在十三世纪把这个名词带入英语，最初指一位统治者统辖的领地。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the commercial sense is generally dated to the nineteenth century, and the furniture style to the French imperial period, but no exact first citation is recorded for either.","cn":"来源不确定（首见年代）：商业义一般认为始于十九世纪，家具风格义系于法国帝政时期，但两者都没有确切的最早书证。"}]},"similar":{"note":{"en":"Group one holds words that share the Latin imperium stock or merely resemble it; group two holds near neighbours for a ruled territory.","cn":"第一组是同出拉丁 imperium 词干或只是形近的词；第二组是表示「被统治的疆域」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"imperial","ipa":"/ɪmˈpɪəriəl/","tag":"same root, adjective","definition":"From imperium plus the relational suffix -ialis: the adjective of empire and emperor, not a separate root.","definitionCN":"由 imperium 加关系形容词后缀 -ialis 构成：帝国与皇帝的形容词，并非另一个词根。"},{"word":"imperious","ipa":"/ɪmˈpɪəriəs/","tag":"same root, manner","definition":"Also from imperium, but through imperiosus 'commanding': it describes a domineering personal manner, not a state.","definitionCN":"同样出自 imperium，但经 imperiosus「好发号施令」：形容个人专横的作风，而非国家。"},{"word":"imperator","ipa":"/ˌɪmpəˈrɑːtə/","tag":"Latin title","definition":"The Latin agent noun 'commander' behind emperor; it is a historical title, not a modern English everyday word.","definitionCN":"emperor 背后的拉丁施动名词「统帅」；它是历史称号，不是现代英语日常词。"},{"word":"empirical","ipa":"/ɪmˈpɪrɪkl/","tag":"different root","definition":"From Greek empeiria 'experience' and Latin empiricus, not from imperium: it means based on observation, so the resemblance is accidental.","definitionCN":"来自希腊 empeiria「经验」与拉丁 empiricus，并非出自 imperium：意为以观察为依据，形近只是巧合。"}]},{"heading":"NEAR MEANING","entries":[{"word":"kingdom","ipa":"/ˈkɪŋdəm/","tag":"royal realm","definition":"A territory ruled by a king or queen; it names the rank of the ruler, while empire implies a wider collection of peoples.","definitionCN":"由国王或女王统治的领土；它标明统治者的等级，而 empire 隐含多个民族被纳入同一体系的更大集合。"},{"word":"realm","ipa":"/relm/","tag":"formal territory","definition":"A literary or formal word for a kingdom or domain, stressing the territory rather than its ruler.","definitionCN":"指王国或领域的书面雅词，侧重领土而非统治者。"},{"word":"dominion","ipa":"/dəˈmɪnjən/","tag":"ruled territory","definition":"From dominium 'ownership': territory under one government, often used of self-governing British possessions.","definitionCN":"出自 dominium「所有权」：受同一政府管辖的领土，常用于英国自治领。"},{"word":"state","ipa":"/steɪt/","tag":"political unit","definition":"The neutral term for an organised political community; it says nothing about size or the ruler's title.","definitionCN":"指有组织的政治共同体的中性词；不涉及规模或统治者称号。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'upon' + parare 'arrange': command is an order arranged upon someone.","cn":"in-「加于」+ parare「安排」：命令就是安排到别人头上的事。"},{"en":"The same family yields emperor, empress, imperial, imperialism, imperialist.","cn":"同一词族衍生出 emperor、empress、imperial、imperialism、imperialist。"},{"en":"Fixed phrases mark the political sense: the Roman Empire, a colonial empire, empire building.","cn":"固定搭配标出政治义：罗马帝国、殖民帝国、扩张版图。"},{"en":"imperator was a military acclamation, so emperor began as 'commander'.","cn":"imperator 本是军队的欢呼，因此 emperor 最初就是「统帅」。"},{"en":"Business pages say a media empire or a hotel empire without any territory at all.","cn":"商业版说「媒体帝国」「酒店帝国」时，根本没有一寸领土。"}],"abstract":[{"en":"Picture a single stamp that every road on the map must pass through.","cn":"想象一枚印章，地图上每条路都必须经过它。"},{"en":"Picture a company org chart drawn exactly like a provincial map.","cn":"想象一张公司架构图，画得和行省地图一模一样。"},{"en":"Picture a style of chair named after the man who sat on the throne.","cn":"想象一种椅子的式样，以坐在王座上的那个人命名。"}]},"examples":[{"en":"The empire lasted four centuries before the provinces broke away.","cn":"这个帝国延续了四个世纪，直到各行省脱离。"},{"en":"He inherited a shipping empire and doubled it within a decade.","cn":"他继承了一个航运帝国，十年内使其规模翻倍。"},{"en":"Historians now study the empire through tax records rather than battle accounts.","cn":"历史学家如今通过税册而非战报来研究这个帝国。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「em」音近「俺」，「pire」音近「派」——俺派出去的人管住一大片地盘 → 帝国","word":"empire"},"root":"拉丁 imperium「治权、统治权」= imperare「命令」= in-「向」+ parare「安排、准备」；imperator「统帅」是同源称号。英语 empire。","sensesIntro":{"en":"Eight senses follow one gesture: a single command laid over a wide space. The command is then read as a power, a state, a company, a sphere, a household, a style and finally a stretch of time.","cn":"八个义项沿同一个动作展开：一道命令覆盖在广阔空间之上。这道命令依次被读作权力、国家、公司、势力范围、家庭小天地、风格，最后读作一段时期。"},"semanticMap":{"core":{"en":"CORE IMAGE: one seal pressed onto a whole map, so that every road leads to the same authority.","cn":"核心意象：一枚印章压在整幅地图上，使每条道路都通向同一个权威。"},"chain":["COMMAND","TERRITORY","SOVEREIGN STATE","COMMERCIAL DOMINION","INFORMAL SPHERE","NAMED ERA"],"branches":[{"senses":"S1 · S2","en":"COMMAND AND LAND: imperium is first a power to order, then the land that power covers.","cn":"权力与土地：imperium 先是发令的权力，随后指这权力覆盖的土地。"},{"senses":"S3 · S8","en":"STATE AND SPAN: a ruler's title renames the polity, and the realm's name then stands for its era.","cn":"国家与时期：统治者的称号给政体改名，疆域之名随后又代表其存在的年代。"},{"senses":"S4","en":"MARKET EMPIRE: a chain of firms can be governed like a chain of provinces.","cn":"市场帝国：一串公司可以像一串行省那样被治理。"},{"senses":"S5 · S6","en":"POWER WITHOUT A FLAG: loans, routes and household rules can bind a space without annexing it.","cn":"无旗之权：贷款、航线与家务规矩都能约束一片空间，却不必吞并它。"},{"senses":"S7","en":"STYLE NAMED AFTER POWER: furniture and dress borrow the name of the court that paid for them.","cn":"以权力命名的风格：家具与服饰借用了出资宫廷的名字。"}]},"affixes":{"intro":{"en":"Empire is a Latin noun made of a prefix, a verb root and a suffix that also build several English words, so the family can be read morpheme by morpheme.","cn":"empire 是一个由前缀、动词词根与后缀构成的拉丁名词，这些成分还构成若干英语词，因此整个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin parare and imperare give empire, emperor, imperial and imperious; in- adds the sense of something laid upon a person.","cn":"拉丁 parare 与 imperare 衍生 empire、emperor、imperial 与 imperious；in- 增添「加到某人身上」的意思。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, upon'; written im- before p)","meaning":"in; upon","meaningCN":"在……之中；加于","example":"The prefix places the action onto its object.","exampleCN":"这个前缀把动作放置到对象之上。"},{"word":"parare","structure":"parare (Latin verb, first conjugation)","meaning":"to prepare, arrange","meaningCN":"准备；安排","example":"The root carries the idea of setting things in order.","exampleCN":"这个词根带着「把事情排好」的意思。"},{"word":"imperare","structure":"in- + parare","meaning":"to command, order","meaningCN":"命令；吩咐","example":"To command is to lay an order upon someone.","exampleCN":"下命令就是把一件事安排到别人头上。"},{"word":"imperium","structure":"imperare + -ium (noun of state or result)","meaning":"command, supreme authority","meaningCN":"治权；最高权力","example":"Imperium gave a magistrate the right to command troops.","exampleCN":"治权赋予长官指挥军队的权力。"},{"word":"imperator","structure":"imperare + -tor (agent noun)","meaning":"commander","meaningCN":"统帅；指挥官","example":"The troops hailed their general as imperator.","exampleCN":"士兵欢呼他们的将领为统帅。"},{"word":"empire","structure":"imperium, through Old French empire","meaning":"a dominion, a realm","meaningCN":"领地；帝国","example":"The empire was ruled from one capital.","exampleCN":"这个帝国由一座首都统治。"},{"word":"imperial","structure":"imperium + -ialis (relational adjective)","meaning":"of an empire or emperor","meaningCN":"帝国的；皇帝的","example":"The imperial seal closed the letter.","exampleCN":"皇帝的印章封上了这封信。"},{"word":"imperialism","structure":"imperial + -ism (doctrine or system)","meaning":"the policy of extending dominion","meaningCN":"扩张统治的政策体系","example":"Imperialism reshaped the region's borders.","exampleCN":"帝国主义重划了该地区的边界。"},{"word":"imperialist","structure":"imperial + -ist (person or agent)","meaning":"a supporter or agent of imperialism","meaningCN":"帝国主义者","example":"The imperialist argued for a larger fleet.","exampleCN":"这位帝国主义者主张扩充舰队。"},{"word":"emperor","structure":"imperator, through Old French empereor","meaning":"the ruler of an empire","meaningCN":"帝国的统治者","example":"The emperor received the envoys in person.","exampleCN":"皇帝亲自接见使节。"}],"latinEntries":[{"word":"parare","structure":"parare, paravi, paratum (verb, first conjugation)","meaning":"to prepare, arrange","meaningCN":"准备；安排"},{"word":"imperare","structure":"imperare, imperavi, imperatum (verb, first conjugation)","meaning":"to command, order","meaningCN":"命令；吩咐"},{"word":"imperium","structure":"imperium, imperii (n., second declension)","meaning":"command, supreme authority","meaningCN":"治权；最高权力"},{"word":"imperator","structure":"imperator, imperatoris (m., third declension)","meaning":"commander","meaningCN":"统帅"},{"word":"imperialis","structure":"imperialis, imperiale (adjective, third declension)","meaning":"of an emperor or empire","meaningCN":"皇帝的；帝国的"}]}},{"word":"imperial","ipa_uk":"/ɪmˈpɪəriəl/","ipa_us":"/ɪmˈpɪriəl/","definition_zh":"帝国的；皇帝的；帝王般威严的；英国法定度量衡制的；帝王开本印张的；唇下小胡须的","definition_en":"relating to an empire or an emperor; also describing a majestic manner, the British official system of weights and measures, a printing paper size and a small beard","core_image":"一根顶端镶金的权杖横放在展开的疆域图上，图边压着一枚标准砝码","scene":"博物馆的展柜里，权杖与地图并排放着，参观者隔着玻璃看见帝号的纹章。The imperial seal was stamped on every charter that left the chancery.","sceneCN":"这里 imperial 指「属于帝国或皇帝的」（第 1 个义项：与帝国这一政治体相关）；句意为每一份离开文书房的特许状都盖上了皇帝的印章。可辨识物件：展柜、权杖、地图、印章、特许状。","pos":[{"tag":"adj.","zh":"帝国的；皇帝的；威严的；英国法定度量衡的；（印张）帝王开本的"},{"tag":"n.","zh":"唇下小胡须；帝王开本印张"}],"collocations":[{"phrase":"imperial palace","zh":"皇宫"},{"phrase":"imperial decree","zh":"皇帝敕令"},{"phrase":"imperial units","zh":"英国法定度量衡单位"},{"phrase":"imperial ambition","zh":"扩张野心"},{"phrase":"imperial purple","zh":"帝王紫（象征皇权的紫色）"},{"phrase":"imperial beard","zh":"唇下小胡须"}],"forms":[{"label":"原级","form":"imperial"},{"label":"比较级","form":"more imperial"},{"label":"最高级","form":"most imperial"},{"label":"副词","form":"imperially"},{"label":"名词（帝国）","form":"empire"}],"derivatives":[{"word":"imperially","pos":"adv.","zh":"imperial + -ly（副词后缀）→ 以帝王气派地"},{"word":"imperialism","pos":"n.","zh":"imperial + -ism（体系、主义后缀）→ 帝国主义，语义由「皇帝的」转为「对外扩张的体系」"},{"word":"imperialist","pos":"n./adj.","zh":"imperial + -ist（从事者后缀）→ 帝国主义者；主张扩张的"},{"word":"imperialistic","pos":"adj.","zh":"imperialist + -ic（形容词后缀）→ 带扩张主义色彩的"},{"word":"imperialness","pos":"n.","zh":"imperial + -ness（性质后缀）→ 威严、帝王气派（较少用）"},{"word":"imperious","pos":"adj.","zh":"imperium + -iosus（形容词后缀）→ 专横的，与 imperial 同根但侧重个人作风"}],"senses":[{"no":"01","title":"Belonging to an empire","titleCN":"属于帝国的","definition":"relating to an empire as a political unit, its institutions or its extent","definitionCN":"与作为政治单位的帝国、其制度或范围相关","example":"Imperial expansion brought roads, garrisons and a common currency.","exampleCN":"帝国的扩张带来了道路、驻军与统一货币。","why":"imperialis was simply the relational adjective of imperium, so anything attached to the empire could be called imperial.","whyCN":"imperialis 本就是 imperium 的关系形容词，凡与帝国相连之物都可称作 imperial。"},{"no":"02","title":"Belonging to an emperor","titleCN":"属于皇帝的","definition":"relating to the person of an emperor or empress, especially to their household or orders","definitionCN":"与皇帝或女皇本人相关，尤指其宫廷与诏令","example":"The imperial decree reached the provinces within a month.","exampleCN":"皇帝的敕令一个月内便传达到各行省。","why":"Because the emperor embodied the empire, the same adjective served both the realm and the person at its head.","whyCN":"由于皇帝是帝国的化身，同一个形容词既修饰疆域，也修饰位于其顶端的人。"},{"no":"03","title":"Majestic in personal manner","titleCN":"个人举止威严的","definition":"commanding and dignified in bearing, as though born to rule","definitionCN":"举止有威势、端庄自持，仿佛生来就该统治","example":"He walked into the meeting with an imperial calm that silenced the room.","exampleCN":"他带着帝王般的沉静走进会场，全场顿时安静。","why":"The adjective moved from the throne to the temperament, so an ordinary person can behave imperially.","whyCN":"这个形容词从王座移到了性情上，因此普通人也能有 imperial 的举止。"},{"no":"04","title":"The British official system of units","titleCN":"英国法定度量衡制","definition":"relating to the traditional British system of weights and measures, as opposed to metric","definitionCN":"指英国传统的度量衡体系，与公制相对","example":"The recipe still uses imperial pints and ounces.","exampleCN":"这份食谱仍使用英制品脱与盎司。","why":"Nineteenth-century statute fixed one set of standards for the whole realm, and 'imperial' marked what belonged to the crown's uniform system.","whyCN":"十九世纪的法规为整个疆域固定了一套标准，「帝国的」便标记出属于王权统一体系的部分。"},{"no":"05","title":"A large printing paper size","titleCN":"帝王开本的大幅印张","definition":"a traditional size of printing paper, larger than a standard sheet, used for folios and plates","definitionCN":"一种传统的大幅印刷纸张规格，用于对开页与图版","example":"The plate was printed on imperial, a sheet larger than the ordinary press run.","exampleCN":"这幅图版印在帝王开本的纸上，比普通印刷用纸更大。","why":"Paper sizes were once named by trade convention; the largest sheets took grand names, and 'imperial' was among them.","whyCN":"纸张规格旧时按行业惯例命名，最大的纸幅取宏大的名号，imperial 便是其中之一。"},{"no":"06","title":"A small beard below the lip","titleCN":"唇下的小胡须","definition":"a narrow tuft of hair grown beneath the lower lip, also called an imperial beard","definitionCN":"下唇下方留的一小撮窄须，又称帝王须","example":"A narrow imperial ran down from his lower lip.","exampleCN":"一撮窄窄的唇下须从他的下唇垂下来。","why":"Nineteenth-century fashion named the tuft after the emperor who wore it, so a beard inherited a political nickname.","whyCN":"十九世纪的时尚以佩戴它的皇帝为这种胡须命名，于是一撮胡子继承了政治绰号。"},{"no":"07","title":"In the style favoured by emperors","titleCN":"帝王偏好的风格","definition":"designating furniture, dress or architecture modelled on the grand classical taste of an imperial court","definitionCN":"指仿照宫廷宏大古典品味制作的家具、服饰或建筑","example":"The salon was furnished in the imperial manner, with gilt bronze and mahogany.","exampleCN":"这间客厅按帝王风格布置，用的是镀金铜饰与桃花心木。","why":"Court patronage set the fashion, so the adjective became a label for a heavy, symmetrical style.","whyCN":"宫廷的赞助引领时尚，因此这个形容词成了厚重、对称风格的标签。"},{"no":"08","title":"Expansionist in policy","titleCN":"政策上的扩张主义","definition":"showing a desire to extend a state's power over other countries","definitionCN":"表现出把国家权力扩张到他国的意图","example":"The party's imperial ambitions reached beyond its borders.","exampleCN":"该党的帝国野心伸到了国界之外。","why":"The same adjective that describes a court also describes a foreign policy that treats other lands as provinces.","whyCN":"修饰宫廷的同一个形容词，也用来修饰把别国土地当作行省的外交政策。"}],"etymology":{"intro":{"en":"Imperial is the Latin relational adjective imperialis, built on imperium 'command, authority' with the suffix -ialis. It entered English through Old French. Dates are approximate.","cn":"imperial 是拉丁关系形容词 imperialis，由 imperium「治权、命令」加后缀 -ialis 构成，经古法语进入英语。年代均为约数。"},"items":[{"era":"LATIN IMPERIUM","en":"Imperium named the supreme power to command troops and enforce law; it is the base of the whole family.","cn":"imperium 指指挥军队与执行法律的最高权力，是整个词族的基础。"},{"era":"LATIN IMPERIALIS","en":"The suffix -ialis turned the noun into an adjective meaning 'of command, of the empire', a very common Latin pattern.","cn":"后缀 -ialis 把名词转为「治权的、帝国的」形容词，这是拉丁语极常见的构词方式。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French imperial passed into English in the fourteenth century, first in the sense 'of an emperor'.","cn":"古法语 imperial 在十四世纪进入英语，最初义为「皇帝的」。"},{"era":"BRITISH STANDARDS","en":"In the nineteenth century the adjective was attached to the statutory British system of weights and measures, which was fixed for the whole realm.","cn":"十九世纪，这个形容词被加在英国法定度量衡体系上，该体系为整个疆域统一固定。"},{"era":"EMPEROR-NAMED THINGS","en":"The beard and the furniture style both took the name from imperial courts, especially the French court of the early nineteenth century.","cn":"唇下须与家具风格都从宫廷得名，尤指十九世纪初的法国宫廷。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact origin of the paper-size name and the first recorded use of the beard sense are not established; both are trade or fashion conventions rather than documented coinages.","cn":"来源不确定（首见年代）：纸张规格名的确切来源与胡须义的最早书证均无定论；两者都是行业或时尚惯例，而非有据可查的新造词。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin stock or accidental look-alikes; group two holds adjectives that also mean grand or royal.","cn":"第一组是同出拉丁词干或偶然形近的词；第二组是同样表示「宏大、王室的」形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"empire","ipa":"/ˈempaɪə/","tag":"same root, noun","definition":"The noun of the same family: the dominion itself, not its adjective.","definitionCN":"同族的名词：指疆域本身，而非其形容词。"},{"word":"imperious","ipa":"/ɪmˈpɪəriəs/","tag":"same root, personal","definition":"From imperium via imperiosus: domineering in manner. Imperial can mean dignified; imperious always implies looking down on others.","definitionCN":"经 imperiosus 出自 imperium：指专横跋扈。imperial 可指威严，imperious 则总含轻视他人之意。"},{"word":"imperator","ipa":"/ˌɪmpəˈrɑːtə/","tag":"Latin title","definition":"The Latin 'commander' behind emperor; a historical title rather than an English adjective.","definitionCN":"emperor 背后的拉丁「统帅」；是历史称号，不是英语形容词。"},{"word":"empirical","ipa":"/ɪmˈpɪrɪkl/","tag":"different root","definition":"From Greek empeiria 'experience', not from imperium: based on observation. The similarity is only in spelling.","definitionCN":"出自希腊 empeiria「经验」，并非 imperium：意为以观察为依据，相同之处仅在拼写。"}]},{"heading":"NEAR MEANING","entries":[{"word":"regal","ipa":"/ˈriːɡl/","tag":"royal bearing","definition":"Fit for a king or queen in appearance and manner; it is about dignity, not about an empire.","definitionCN":"外表与举止配得上君王；说的是威仪，与帝国无关。"},{"word":"royal","ipa":"/ˈrɔɪəl/","tag":"of a king","definition":"Belonging to a king or queen by office; the everyday adjective of monarchy.","definitionCN":"因职位属于国王或女王；是君主制最日常的形容词。"},{"word":"majestic","ipa":"/məˈdʒestɪk/","tag":"grand appearance","definition":"Impressive and dignified to look at, often used of scenery as well as people.","definitionCN":"外观雄伟庄严，常用于景物，也可用于人。"},{"word":"sovereign","ipa":"/ˈsɒvrɪn/","tag":"supreme authority","definition":"Holding supreme and independent power; it stresses legal authority rather than courtly grandeur.","definitionCN":"握有最高且独立的权力；侧重法律权威而非宫廷气派。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"imperium 'command' + -ialis 'relating to': the adjective of empire and emperor.","cn":"imperium「命令」+ -ialis「与……相关」：帝国与皇帝的形容词。"},{"en":"The family runs empire, emperor, empress, imperial, imperialism, imperialist.","cn":"同族词包括 empire、emperor、empress、imperial、imperialism、imperialist。"},{"en":"Fixed phrases: imperial palace, imperial decree, imperial units.","cn":"固定搭配：皇宫、皇帝敕令、英制单位。"},{"en":"British recipes still say imperial pints, while scientists use metric.","cn":"英国食谱仍说英制品脱，而科学家用公制。"},{"en":"The beard and the furniture style both borrow the name of a court.","cn":"唇下须与家具风格都借用了宫廷的名字。"}],"abstract":[{"en":"Picture a ruler's seal falling on a page and making ordinary paper official.","cn":"想象一枚御印落在纸上，让普通纸张变成正式文书。"},{"en":"Picture a man who sits down and makes the whole table straighten.","cn":"想象一个人一坐下，整张桌子的人都挺直了腰。"},{"en":"Picture a weights-and-measures office that refuses to change with the neighbours.","cn":"想象一间度量衡官署，拒绝随邻国更改标准。"}]},"examples":[{"en":"Imperial rule ended when the last garrison withdrew.","cn":"最后一支驻军撤离时，帝国的统治结束了。"},{"en":"The museum keeps a set of imperial measures in its basement.","cn":"博物馆在地下室保存着一套英制度量衡器具。"},{"en":"His imperial manner made even the senior staff wait for permission.","cn":"他帝王般的作风让连资深职员都要等他许可。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「im」音近「印」，「perial」音近「披锐」——印信披锐甲，皇帝出巡 → 帝国的、威严的","word":"imperial"},"root":"拉丁 imperialis「帝国的、皇帝的」= imperium「治权」+ -ialis（关系形容词后缀）；imperium 出自 imperare「命令」。英语 imperial。","sensesIntro":{"en":"Eight senses all attach one adjective to a different owner: an empire, an emperor, a manner, a system of units, a sheet of paper, a beard, a style and a foreign policy.","cn":"八个义项都是把同一个形容词挂到不同的所属者上：帝国、皇帝、举止、度量衡、纸张、胡须、风格与外交政策。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gilded staff laid across a map, with a standard weight holding the corner down.","cn":"核心意象：一根镀金权杖横放在地图上，一枚标准砝码压住图角。"},"chain":["EMPIRE","EMPEROR","COMMAND","GRANDEUR","OFFICIAL STANDARD","NAMED AFTER EMPERORS"],"branches":[{"senses":"S1","en":"THE POLITY: whatever belongs to the empire as a whole takes the adjective.","cn":"政体：凡属于整个帝国的事物都取这个形容词。"},{"senses":"S2","en":"THE PERSON: the emperor's household and orders are described with the same word.","cn":"人：皇帝的宫廷与诏令用同一个词描述。"},{"senses":"S3 · S8","en":"COMMANDING BEARING: dignity in a person and expansion in a state are both rule-like.","cn":"威势：个人的威严与国家的扩张都带「统御」意味。"},{"senses":"S4 · S5","en":"OFFICIAL MEASURES: one statutory system and one grand paper size both carry the crown's label.","cn":"官方尺度：统一度量衡与大幅印张都带着王权的标签。"},{"senses":"S6 · S7","en":"COURT NAMED OBJECTS: a tuft of beard and a furniture style borrow an emperor's name.","cn":"以宫廷命名的物件：一撮胡须与一种家具风格借用了皇帝的名字。"}]},"affixes":{"intro":{"en":"Imperial is a Latin adjective built on a noun and a suffix, and both parts recur in English words, so the family can be read morpheme by morpheme.","cn":"imperial 是由名词加后缀构成的拉丁形容词，两部分都在英语词中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin imperium and the suffix -ialis give imperial; the same noun also yields empire, emperor, imperator and imperious.","cn":"拉丁 imperium 与后缀 -ialis 构成 imperial；同一名词还衍生 empire、emperor、imperator 与 imperious。"},"items":[{"word":"imperium","structure":"imperium, imperii (Latin noun, second declension)","meaning":"command, supreme authority","meaningCN":"治权；最高权力","example":"The noun is the base of the whole family.","exampleCN":"这个名词是整个词族的基础。"},{"word":"-ialis","structure":"-ialis (Latin relational suffix, -al in English)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns a noun into an adjective of relation.","exampleCN":"这个后缀把名词转为关系形容词。"},{"word":"imperialis","structure":"imperium + -ialis","meaning":"of an empire or emperor","meaningCN":"帝国的；皇帝的","example":"The adjective described both the realm and its head.","exampleCN":"这个形容词既修饰疆域也修饰其元首。"},{"word":"imperial","structure":"imperialis, through Old French","meaning":"relating to empire","meaningCN":"与帝国相关的","example":"The imperial seal closed the charter.","exampleCN":"帝国的印章封上了特许状。"},{"word":"imperially","structure":"imperial + -ly (adverb)","meaning":"in an imperial manner","meaningCN":"以帝王气派地","example":"She nodded imperially and the room fell silent.","exampleCN":"她帝王般地点了点头，屋子便静了下来。"},{"word":"imperialism","structure":"imperial + -ism (system or doctrine)","meaning":"the policy of extending rule","meaningCN":"扩张统治的政策","example":"Imperialism redrew the region.","exampleCN":"帝国主义重划了该地区。"},{"word":"imperialist","structure":"imperial + -ist (person or agent)","meaning":"a supporter of imperialism","meaningCN":"帝国主义者","example":"The imperialist wanted a larger fleet.","exampleCN":"这位帝国主义者想要更大的舰队。"},{"word":"imperious","structure":"imperium + -iosus (full of)","meaning":"domineering","meaningCN":"专横的","example":"His imperious tone ended the discussion.","exampleCN":"他专横的语气终止了讨论。"},{"word":"emperor","structure":"imperator, through Old French","meaning":"ruler of an empire","meaningCN":"帝国的统治者","example":"The emperor entered the hall.","exampleCN":"皇帝进入大厅。"}],"latinEntries":[{"word":"imperium","structure":"imperium, imperii (n., second declension)","meaning":"command, supreme authority","meaningCN":"治权；最高权力"},{"word":"imperialis","structure":"imperialis, imperiale (adjective, third declension)","meaning":"of an emperor or empire","meaningCN":"皇帝的；帝国的"},{"word":"imperare","structure":"imperare, imperavi, imperatum (verb, first conjugation)","meaning":"to command, order","meaningCN":"命令；吩咐"},{"word":"imperator","structure":"imperator, imperatoris (m., third declension)","meaning":"commander","meaningCN":"统帅"}]}},{"word":"imperialism","ipa_uk":"/ɪmˈpɪəriəlɪzəm/","ipa_us":"/ɪmˈpɪriəlɪzəm/","definition_zh":"帝国主义；以扩张领土或支配他国为目标的政治体系与观念；资本、文化与语言的对外支配","definition_en":"the policy and ideology of extending a state's or a group's power over other countries, economies or cultures","core_image":"一面旗插在远方的港口，账本与炮舰并排放在同一张桌上","scene":"课本的跨页图上，港口、铁路与炮舰被画进同一张网络，旗子从首都一直插到河口。Textbooks describe imperialism as a system that ties distant ports to one capital.","sceneCN":"这里 imperialism 指「以扩张领土或支配他国为目标的政策体系」（第 1 个义项：把远方港口、铁路与武力纳入同一中心）；句意为教科书把帝国主义描述为把远方港口系于一个首都的制度。可辨识物件：课本、港口、铁路、炮舰、旗帜。","pos":[{"tag":"n.","zh":"帝国主义；扩张主义政策；资本或文化的对外支配（多作不可数）"}],"collocations":[{"phrase":"European imperialism","zh":"欧洲帝国主义"},{"phrase":"cultural imperialism","zh":"文化帝国主义"},{"phrase":"economic imperialism","zh":"经济帝国主义"},{"phrase":"the age of imperialism","zh":"帝国主义时代"},{"phrase":"linguistic imperialism","zh":"语言帝国主义"},{"phrase":"oppose imperialism","zh":"反对帝国主义"}],"forms":[{"label":"通常形式（不可数）","form":"imperialism"},{"label":"复数（指多种帝国主义形态，较少用）","form":"imperialisms"},{"label":"形容词（帝国主义的）","form":"imperialist"},{"label":"形容词（带扩张色彩的）","form":"imperialistic"},{"label":"名词（帝国主义者）","form":"imperialist"}],"derivatives":[{"word":"imperialist","pos":"n./adj.","zh":"imperial + -ist（从事者与主张者后缀）→ 帝国主义者；帝国主义的主张者，语义由形容词转为行动者"},{"word":"imperialistic","pos":"adj.","zh":"imperialist + -ic（形容词后缀）→ 带扩张主义色彩的"},{"word":"imperialistically","pos":"adv.","zh":"imperialistic + -ally（副词后缀）→ 以帝国主义方式地"},{"word":"anti-imperialism","pos":"n.","zh":"anti-（反对前缀）+ imperialism → 反帝国主义，语义指向其对立立场"},{"word":"anti-imperialist","pos":"n./adj.","zh":"anti- + imperialist → 反帝国主义者；反帝国主义的"},{"word":"neo-imperialism","pos":"n.","zh":"neo-（新前缀）+ imperialism → 新帝国主义，语义由旧式占领转为经济与制度支配"}],"senses":[{"no":"01","title":"Policy of extending rule over other lands","titleCN":"把统治扩及他国的政策","definition":"the policy of acquiring and governing foreign territories, often by conquest or settlement","definitionCN":"获取并治理外国领土的政策，常以征服或移民定居为手段","example":"Nineteenth-century imperialism redrew the map of Africa.","exampleCN":"十九世纪的帝国主义重画了非洲地图。","why":"imperial plus -ism names a system, so the word first described the doctrine behind an empire's growth.","whyCN":"imperial 加 -ism 表示一套体系，因此这个词最初指帝国扩张背后的主张。"},{"no":"02","title":"The practice of ruling colonies","titleCN":"统治殖民地的实践","definition":"the actual administration of dependent territories and their peoples","definitionCN":"对附属领土及其人民实际施行的管理","example":"Imperialism brought both railways and forced labour.","exampleCN":"殖民统治既带来铁路，也带来强制劳动。","why":"The suffix names a practice as well as a doctrine, so the word covers what officials did, not only what theorists argued.","whyCN":"这个后缀既能指主张，也能指实践，因此该词涵盖官员的所作所为，而不只是理论家的主张。"},{"no":"03","title":"Economic domination without annexation","titleCN":"不吞并领土的经济支配","definition":"control of another country's markets, loans or resources by powerful investors and firms","definitionCN":"强势投资者与公司对他国市场、贷款或资源的控制","example":"Critics spoke of dollar imperialism behind the loans.","exampleCN":"批评者说这些贷款背后是美元帝国主义。","why":"Twentieth-century writers saw that capital could rule a country without a colonial flag, and extended the word to that mechanism.","whyCN":"二十世纪作家看出资本无需殖民旗帜就能统治一国，于是把这个词扩展到这种机制。"},{"no":"04","title":"Cultural domination","titleCN":"文化上的支配","definition":"the spread of a powerful country's values, media and habits until local cultures are displaced","definitionCN":"强国价值观、媒体与生活方式的扩散，致使本地文化被挤压","example":"Hollywood's cultural imperialism worried European ministers.","exampleCN":"好莱坞的文化帝国主义令欧洲的部长们担忧。","why":"If empire can be economic, it can also be cultural: screens and schools can do the work that garrisons once did.","whyCN":"既然帝国可以是经济的，也就可以是文化的：屏幕与学校能做驻军曾做的事。"},{"no":"05","title":"The historical age of overseas expansion","titleCN":"海外扩张的历史时代","definition":"the period, especially the late nineteenth century, when European powers partitioned much of the world","definitionCN":"欧洲列强瓜分世界的大片地区，尤指十九世纪后期的时期","example":"The age of imperialism ended with the great decolonisation.","exampleCN":"帝国主义时代随大规模非殖民化而结束。","why":"Historians turned the doctrine into a period label, so the word can name an era rather than a policy.","whyCN":"史学家把这种主张变成时期标签，因此这个词可以指一个时代，而不只是政策。"},{"no":"06","title":"Monopoly capital as a stage of capitalism","titleCN":"作为资本主义阶段的垄断资本","definition":"in Marxist theory, the stage in which monopolies and finance capital drive overseas expansion","definitionCN":"马克思主义理论中，垄断与金融资本推动海外扩张的阶段","example":"Lenin argued that imperialism was capitalism in its monopoly stage.","exampleCN":"列宁主张帝国主义是资本主义的垄断阶段。","why":"The word was given a technical place in a theory of economic stages, so it can denote a structural phase rather than a policy.","whyCN":"这个词在一套经济阶段理论中被赋予技术位置，因此可以指结构阶段而非政策。"},{"no":"07","title":"Dominance of one language","titleCN":"某一种语言的支配地位","definition":"the privileged spread of a major language at the expense of local languages","definitionCN":"主要语言占据优势的扩散，代价是本地语言受挤压","example":"English linguistic imperialism spread through school curricula.","exampleCN":"英语的语言帝国主义通过学校课程扩散。","why":"Language carries culture, so the compound 'linguistic imperialism' applies the political frame to classrooms.","whyCN":"语言承载文化，因此「语言帝国主义」把政治框架套用到课堂上。"},{"no":"08","title":"A domineering habit inside an institution","titleCN":"机构内部的专横扩张作风","definition":"a tendency of a department or official to seize territory and authority within an organisation","definitionCN":"某个部门或官员在组织内部夺取地盘与权力的倾向","example":"Bureaucratic imperialism kept departments fighting over turf.","exampleCN":"官僚式的扩张作风让各部门不断争夺地盘。","why":"The playful institutional use keeps the core of seizing ground but shrinks the map to an office floor.","whyCN":"机构内的戏谑用法保留了「夺取地盘」的核心，只把地图缩小到一层办公楼。"}],"etymology":{"intro":{"en":"Imperialism is an English formation from imperial plus the suffix -ism, which came through Latin -ismus from Greek -ismos. The political sense is modern. Dates are approximate.","cn":"imperialism 是英语由 imperial 加后缀 -ism 构成的新词，-ism 经拉丁 -ismus 来自希腊 -ismos。政治义属近代。年代均为约数。"},"items":[{"era":"LATIN IMPERIUM","en":"The base noun imperium 'command, authority' supplies the idea of rule that the whole word carries.","cn":"基础名词 imperium「命令、治权」提供了整词所含的统治观念。"},{"era":"ENGLISH IMPERIAL","en":"The adjective imperial, already used for empire and emperor, was the direct base of the new noun.","cn":"已用于帝国与皇帝的形容词 imperial，是这个新名词的直接基础。"},{"era":"SUFFIX -ISM","en":"-ism entered English through Latin -ismus from Greek -ismos, naming systems, doctrines and practices, as in realism or socialism.","cn":"-ism 经拉丁 -ismus 来自希腊 -ismos，用于命名体系、主张与实践，如 realism、socialism。"},{"era":"POLITICAL SENSE","en":"The noun appeared in the mid-nineteenth century, when debates about colonial expansion needed a word for the doctrine behind it.","cn":"这个名词出现于十九世纪中期，当时关于殖民扩张的辩论需要一个词来指其背后的主张。"},{"era":"MARXIST SENSE","en":"Lenin's 1916 pamphlet made imperialism a technical term for a stage of capitalism, and that reading spread through political theory.","cn":"列宁 1916 年的小册子把帝国主义变成资本主义某一阶段的技术术语，这一读法随后传遍政治理论。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact first English citation is not established, and the earliest uses carried overlapping meanings of rule, trade and settlement, so no single coinage can be named.","cn":"来源不确定（首见年代）：确切的最早英语书证未有定论，早期用法混合了统治、贸易与移民定居几层意思，无法指认唯一的造词者。"}]},"similar":{"note":{"en":"Group one holds forms from the same family or accidental look-alikes; group two holds rival words for expansion and domination.","cn":"第一组是同族形式或偶然形近的词；第二组是表示扩张与支配的竞争性词汇。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"imperialist","ipa":"/ɪmˈpɪəriəlɪst/","tag":"person or adjective","definition":"The agent form: a supporter of imperialism, or the adjective describing such a policy; imperialism is the system itself.","definitionCN":"施动形式：帝国主义者，或形容此类政策；imperialism 指体系本身。"},{"word":"imperialistic","ipa":"/ɪmˌpɪəriəˈlɪstɪk/","tag":"adjective","definition":"The adjective meaning 'marked by imperialism'; it describes behaviour, not the doctrine.","definitionCN":"意为「带有帝国主义色彩的」形容词；描述行为，而非主张本身。"},{"word":"imperial","ipa":"/ɪmˈpɪəriəl/","tag":"base adjective","definition":"Simply 'of an empire or emperor'; it has no inherent criticism, while imperialism usually carries disapproval.","definitionCN":"仅指「帝国的、皇帝的」；本身不含贬义，而 imperialism 通常带批评色彩。"},{"word":"empiricism","ipa":"/ɪmˈpɪrɪsɪzəm/","tag":"different root","definition":"From Greek empeiria 'experience': the theory that knowledge comes from observation. It resembles imperialism only in sound.","definitionCN":"出自希腊 empeiria「经验」：主张知识来自观察的理论；与 imperialism 只是读音相近。"}]},{"heading":"NEAR MEANING","entries":[{"word":"colonialism","ipa":"/kəˈləʊniəlɪzəm/","tag":"settler rule","definition":"The practice of settling and governing a colony; imperialism is the broader policy or ideology that may or may not involve settlement.","definitionCN":"移民定居并治理殖民地的实践；imperialism 是更广的政策或意识形态，未必包含定居。"},{"word":"expansionism","ipa":"/ɪkˈspænʃənɪzəm/","tag":"territorial growth","definition":"A policy of enlarging a state's territory; it names the growth itself rather than the cultural or economic system.","definitionCN":"扩大国家领土的政策；指扩张本身，而非文化或经济体系。"},{"word":"hegemony","ipa":"/hɪˈɡeməni/","tag":"leadership by consent","definition":"Dominance of one power over others, often through consent and institutions rather than direct rule.","definitionCN":"一方对他方的支配，常通过认同与制度而非直接统治实现。"},{"word":"neo-colonialism","ipa":"/ˌniːəʊ kəˈləʊniəlɪzəm/","tag":"post-independence control","definition":"Economic and political control of formally independent states; it is a later variant, not the historical practice of empire.","definitionCN":"对名义上独立国家的经济与政治控制；属较晚变体，不是历史上的帝国实践。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"imperial + -ism: the doctrine attached to an empire.","cn":"imperial + -ism：附着于帝国的主义。"},{"en":"Three fixed compounds mark its range: cultural, economic and linguistic imperialism.","cn":"三个固定复合词标出其范围：文化、经济与语言帝国主义。"},{"en":"The pair imperialism and colonialism differ: the first is the policy, the second the settlement practice.","cn":"imperialism 与 colonialism 有别：前者是政策，后者是移民定居的实践。"},{"en":"Historians also use it as a period name: the age of imperialism.","cn":"史家也把它用作时期名：帝国主义时代。"},{"en":"Lenin fixed the Marxist reading as a stage of capitalism.","cn":"列宁把马克思主义读法固定为资本主义的一个阶段。"}],"abstract":[{"en":"Picture a ledger and a gunboat sharing one desk drawer.","cn":"想象账本与炮舰放在同一张桌子的抽屉里。"},{"en":"Picture a flag planted not in soil but in a shopping arcade.","cn":"想象一面旗不插在土里，而插在购物廊里。"},{"en":"Picture a classroom where the textbook arrives with the warship's timetable.","cn":"想象一间教室，课本和军舰的时刻表一起送到。"}]},"examples":[{"en":"The lecture traced imperialism from chartered companies to modern trade agreements.","cn":"讲座追溯帝国主义，从特许公司一直讲到现代贸易协定。"},{"en":"Local writers resisted cultural imperialism by publishing in their own language.","cn":"本地作家用自己的语言出版，以抵抗文化帝国主义。"},{"en":"The seminar compared British and French imperialism in the same decade.","cn":"研讨课比较了同一时期英国与法国的帝国主义。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「imperial」皇帝 + 「ism」主义——把皇帝的旗插到别人家门口 → 帝国主义","word":"imperialism"},"root":"英语 imperial「帝国的」+ -ism「主义、体系」；imperial 出自拉丁 imperium「治权」，再上溯 imperare「命令」。英语 imperialism。","sensesIntro":{"en":"Eight senses follow one expansion: a flag moves outward. It can plant in soil, in a market, in a cinema, in a school, in a theory, or merely in a neighbouring office.","cn":"八个义项沿同一次扩张展开：一面旗向外移动。它可以插进土地、市场、影院、学校、理论，甚至只是隔壁办公室。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger and a gunboat in the same drawer, both serving one distant capital.","cn":"核心意象：账本与炮舰放在同一抽屉里，都为远方同一个首都服务。"},"chain":["EXPANSION","COLONIAL RULE","ECONOMIC CONTROL","CULTURAL CONTROL","THEORETICAL STAGE","EVERYDAY DOMINATION"],"branches":[{"senses":"S1 · S2","en":"LAND AND ADMINISTRATION: the doctrine and the daily running of dependent territories.","cn":"土地与管理：既有主张，也有对附属领土的日常治理。"},{"senses":"S3","en":"CAPITAL WITHOUT A FLAG: loans and markets can hold a country without annexing it.","cn":"无旗资本：贷款与市场无需吞并即可控制一国。"},{"senses":"S4 · S7","en":"SCREENS AND SCHOOLS: culture and language carry the same outward pressure.","cn":"屏幕与学校：文化与语言承载同样的向外压力。"},{"senses":"S5 · S6","en":"AN ERA AND A STAGE: historians and theorists turn the policy into period and structure.","cn":"时代与阶段：史家与理论家把政策转为时期与结构。"},{"senses":"S8","en":"OFFICE TURF: the same seizing gesture appears in miniature inside an institution.","cn":"办公室地盘：同一种夺取姿态在机构内部缩小重现。"}]},"affixes":{"intro":{"en":"Imperialism is a two-part English word: a Latin-derived adjective plus a Greek-derived suffix, each productive in many other words.","cn":"imperialism 是由两部分构成的英语词：拉丁来源的形容词加希腊来源的后缀，两者都能构成许多其他词。"},"latinIntro":{"en":"Latin imperium and imperare give imperial; Greek -ismos, through Latin -ismus, gives the English suffix -ism.","cn":"拉丁 imperium 与 imperare 衍生 imperial；希腊 -ismos 经拉丁 -ismus 形成英语后缀 -ism。"},"items":[{"word":"imperium","structure":"imperium, imperii (Latin noun, second declension)","meaning":"command, authority","meaningCN":"治权；权威","example":"The noun supplies the idea of rule.","exampleCN":"这个名词提供了统治的观念。"},{"word":"-alis","structure":"-alis (Latin relational suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix built imperialis from imperium.","exampleCN":"这个后缀由 imperium 构成 imperialis。"},{"word":"imperial","structure":"imperialis, through Old French","meaning":"of empire or emperor","meaningCN":"帝国的；皇帝的","example":"Imperial policy shaped the region.","exampleCN":"帝国政策塑造了该地区。"},{"word":"-ism","structure":"-ismus (Latin, from Greek -ismos)","meaning":"system, doctrine, practice","meaningCN":"体系；主张；实践","example":"The suffix also builds realism and socialism.","exampleCN":"这个后缀也构成 realism 与 socialism。"},{"word":"imperialism","structure":"imperial + -ism","meaning":"the doctrine of extending rule","meaningCN":"扩张统治的主张","example":"Imperialism redrew the map.","exampleCN":"帝国主义重画了地图。"},{"word":"imperialist","structure":"imperial + -ist (person)","meaning":"a supporter of the doctrine","meaningCN":"该主张的支持者","example":"The imperialist defended the fleet.","exampleCN":"这位帝国主义者为舰队辩护。"},{"word":"imperialistic","structure":"imperialist + -ic (adjective)","meaning":"marked by imperialism","meaningCN":"带帝国主义色彩的","example":"The tone was openly imperialistic.","exampleCN":"那语气是公开的帝国主义腔调。"},{"word":"anti-imperialism","structure":"anti- (against) + imperialism","meaning":"opposition to imperialism","meaningCN":"反对帝国主义","example":"Anti-imperialism grew after the war.","exampleCN":"战后反帝国主义情绪高涨。"},{"word":"neo-imperialism","structure":"neo- (new) + imperialism","meaning":"indirect domination after independence","meaningCN":"独立后的间接支配","example":"Neo-imperialism works through debt.","exampleCN":"新帝国主义通过债务运作。"},{"word":"empire","structure":"imperium, through Old French","meaning":"a dominion","meaningCN":"疆域；帝国","example":"The empire dissolved in a decade.","exampleCN":"这个帝国十年内瓦解。"}],"latinEntries":[{"word":"imperium","structure":"imperium, imperii (n., second declension)","meaning":"command, supreme authority","meaningCN":"治权；最高权力"},{"word":"imperialis","structure":"imperialis, imperiale (adjective, third declension)","meaning":"of an emperor or empire","meaningCN":"皇帝的；帝国的"},{"word":"imperare","structure":"imperare, imperavi, imperatum (verb, first conjugation)","meaning":"to command, order","meaningCN":"命令；吩咐"}]}},{"word":"emperor","ipa_uk":"/ˈempərə/","ipa_us":"/ˈempərər/","definition_zh":"皇帝；帝国的男性君主；日本天皇；罗马军队欢呼的统帅；一种大型蛱蝶；塔罗牌中的「皇帝」；某个领域里的霸主","definition_en":"the male sovereign of an empire, or a ruler bearing that title; also a large butterfly, a moth, a tarot trump and a dominant figure","core_image":"金冠压在一枚军徽上，冠下的披风一直铺到地图边缘","scene":"古装剧的宫殿里，金冠摆在台阶最高处，群臣在下面等候旨意。The emperor received the envoys in the great hall.","sceneCN":"这里 emperor 指「帝国的男性最高君主」（第 1 个义项：统治整片帝国的人）；句意为皇帝在大殿里接见使节。可辨识物件：宫殿、金冠、台阶、群臣、使节。","pos":[{"tag":"n.","zh":"皇帝；帝国君主；天皇；大型蛱蝶；塔罗牌「皇帝」；领域霸主"}],"collocations":[{"phrase":"the Roman emperor","zh":"罗马皇帝"},{"phrase":"the emperor of Japan","zh":"日本天皇"},{"phrase":"emperor penguin","zh":"帝企鹅"},{"phrase":"the emperor's decree","zh":"皇帝的敕令"},{"phrase":"a reigning emperor","zh":"在位的皇帝"},{"phrase":"emperor butterfly","zh":"帝王蛱蝶"}],"forms":[{"label":"单数","form":"emperor"},{"label":"复数","form":"emperors"},{"label":"阴性形式","form":"empress"},{"label":"形容词（帝国的）","form":"imperial"},{"label":"名词（帝国）","form":"empire"},{"label":"抽象名词（皇帝身份）","form":"emperorship"}],"derivatives":[{"word":"empress","pos":"n.","zh":"emperor + -ess（阴性后缀）→ 女皇、皇后，语义由男性君主转为女性君主"},{"word":"emperorship","pos":"n.","zh":"emperor + -ship（身份、职位后缀）→ 皇帝的身份或在位期"},{"word":"imperial","pos":"adj.","zh":"imperator + -ialis（关系形容词后缀）→ 皇帝的、帝国的，语义由人称转为属性"},{"word":"empire","pos":"n.","zh":"imperium（治权）经古法语 → 帝国，语义由权力转为疆域"},{"word":"imperialism","pos":"n.","zh":"imperial + -ism（体系后缀）→ 帝国主义"},{"word":"emperor-sized","pos":"adj.","zh":"emperor + -sized（复合后缀）→ 皇帝尺码的、特大的（多见于商品描述）"}],"senses":[{"no":"01","title":"Sovereign of an empire","titleCN":"帝国的最高君主","definition":"the male ruler of an empire, holding supreme political authority","definitionCN":"帝国的男性统治者，握有最高政治权威","example":"The emperor received the envoys in the great hall.","exampleCN":"皇帝在大殿里接见使节。","why":"imperator was a commander's title, and the ruler of the whole commanded world naturally took it.","whyCN":"imperator 本是指挥官的称号，统辖整个受命世界的人自然沿用了它。"},{"no":"02","title":"A particular historical title-holder","titleCN":"某位具体的历史君主","definition":"a named ruler in a particular empire, used as a historical designation","definitionCN":"某个帝国中具名的统治者，用作历史称谓","example":"The emperor Hadrian rebuilt the wall across the north.","exampleCN":"皇帝哈德良重建了北方的长城。","why":"Once the title became institutional, it worked like a name, so histories say 'the emperor' before a proper name.","whyCN":"称号一旦制度化，便像名字一样使用，因此史书在专名前加「皇帝」。"},{"no":"03","title":"The head of state of Japan","titleCN":"日本的国家元首","definition":"the constitutional head of state of Japan, a hereditary office without governing power","definitionCN":"日本依宪设定的国家元首，世袭而无实际治理权","example":"The emperor of Japan opens the parliament in person.","exampleCN":"日本天皇亲自为国会开幕。","why":"Japan kept the English title for its hereditary head of state even after the office became ceremonial.","whyCN":"日本在其元首职位改为礼仪性之后，仍以英语 emperor 称呼这位世袭元首。"},{"no":"04","title":"A Roman commander hailed by troops","titleCN":"被罗马士兵欢呼的统帅","definition":"a victorious Roman general acclaimed as imperator on the battlefield","definitionCN":"在战场上被士兵欢呼为统帅的罗马得胜将领","example":"Roman soldiers could hail a victorious general as emperor on the field.","exampleCN":"罗马士兵可以在战场上欢呼得胜的将领为统帅。","why":"This is the oldest layer: the acclamation itself, before the word settled into a throne title.","whyCN":"这是最古老的一层：欢呼本身，早于这个词固定为皇位称号。"},{"no":"05","title":"A large butterfly","titleCN":"一种大型蛱蝶","definition":"any of several large, strongly marked butterflies, especially of the genus Apatura and its relatives","definitionCN":"若干体型大、斑纹鲜明的蛱蝶，尤指紫蛱蝶属及其近缘类群","example":"An emperor settled on the rotting fruit at the edge of the path.","exampleCN":"一只帝王蛱蝶停在小路边的烂果上。","why":"Naturalists gave grand titles to the largest and most conspicuous members of a family, and butterflies were no exception.","whyCN":"博物学者常给一个科中最大最显眼的成员加上宏大称号，蝴蝶也不例外。"},{"no":"06","title":"A tarot trump","titleCN":"塔罗牌中的「皇帝」","definition":"the fourth trump of the Major Arcana, depicting a seated ruler","definitionCN":"大阿卡那中的第四张王牌，画着一位端坐的统治者","example":"In the spread, the emperor faced the empress across the table.","exampleCN":"在牌阵中，「皇帝」隔着桌子与「皇后」相对。","why":"Tarot designers borrowed social ranks for the trumps, so the ruler card was simply called the emperor.","whyCN":"塔罗设计者借用社会等级为王牌命名，统治者那张牌便直接叫「皇帝」。"},{"no":"07","title":"A dominant figure in a field","titleCN":"某一领域里的霸主","definition":"a person who dominates an industry, sport or art as if by royal right","definitionCN":"在某个行业、运动或艺术中像凭王权般支配全局的人","example":"He was the emperor of the city's newspaper trade.","exampleCN":"他是这座城市报业的霸主。","why":"The metaphor transfers absolute command from a state to a market, where one figure can set every price.","whyCN":"这一比喻把绝对统治从国家移到市场，一个人便可定下所有价格。"},{"no":"08","title":"A large emperor moth","titleCN":"大型的帝王蛾","definition":"a large moth of the family Saturniidae, named for its size and eye-spotted wings","definitionCN":"天蚕蛾科的大型蛾类，因体型与翅上眼斑而得名","example":"A great emperor moth came to the lamp and stayed there till dawn.","exampleCN":"一只巨大的帝王蛾飞到灯前，一直停到天亮。","why":"The same naming habit that produced the emperor butterfly gave the largest local moth the same borrowed title.","whyCN":"给帝王蛱蝶命名的那套习惯，也把同一个借来的称号给了当地最大的蛾。"}],"etymology":{"intro":{"en":"Emperor comes through Old French from Latin imperator 'commander', an agent noun from imperare 'to command'. It is a title before it is a word for a butterfly. Dates are approximate.","cn":"emperor 经古法语来自拉丁 imperator「统帅」，那是 imperare「命令」的施动名词。它先是称号，后来才被借去命名蝴蝶。年代均为约数。"},"items":[{"era":"LATIN IMPERARE","en":"In- 'upon' plus parare 'arrange' gave imperare 'to command, to order'.","cn":"in-「加于」加 parare「安排」构成 imperare「命令、吩咐」。"},{"era":"LATIN IMPERATOR","en":"The agent suffix -tor made imperator 'one who commands'; troops acclaimed a victorious general with it.","cn":"施动后缀 -tor 构成 imperator「发令者」；士兵用这个词欢呼得胜的将领。"},{"era":"OLD FRENCH EMPEREOUR","en":"Old French empereor carried the title into English in the twelfth century, already meaning the ruler of an empire.","cn":"古法语 empereor 在十二世纪把这个称号带入英语，当时已指帝国的统治者。"},{"era":"ENGLISH TITLE","en":"English kept emperor for the highest secular ruler, and empress was formed beside it with the French feminine suffix.","cn":"英语用 emperor 指最高的世俗君主，并借法语阴性后缀造出并行的 empress。"},{"era":"BORROWED NAMES","en":"Naturalists and card makers later borrowed the title for a large butterfly, a large moth and a tarot trump, all by naming the grandest member of a set.","cn":"博物学者与制牌人后来借这个称号命名大型蛱蝶、大型蛾与一张塔罗王牌，思路都是给一组事物中最宏大者冠名。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest use of emperor for a butterfly or a moth is not recorded precisely, and the tarot trump's naming convention has no single documented origin.","cn":"来源不确定（首见年代）：emperor 用于蛱蝶或蛾的最早记录并不确切，塔罗王牌的命名惯例也没有唯一可考的来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same Latin title or accidental neighbours; group two holds words for a supreme ruler.","cn":"第一组是同出拉丁称号或偶然相邻的形式；第二组是表示最高统治者的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"empress","ipa":"/ˈempres/","tag":"feminine counterpart","definition":"The female ruler or consort, formed from emperor with the French feminine suffix -ess.","definitionCN":"女性统治者或皇后，由 emperor 加法语阴性后缀 -ess 构成。"},{"word":"empire","ipa":"/ˈempaɪə/","tag":"same root, realm","definition":"The dominion ruled by an emperor, from imperium; it names the territory, not the person.","definitionCN":"皇帝统治的疆域，出自 imperium；指领土而非人。"},{"word":"imperial","ipa":"/ɪmˈpɪəriəl/","tag":"same root, adjective","definition":"The relational adjective of emperor and empire, from imperialis.","definitionCN":"皇帝与帝国的关系形容词，出自 imperialis。"},{"word":"imperator","ipa":"/ˌɪmpəˈrɑːtə/","tag":"Latin original","definition":"The Latin commander's title itself, still used in Roman history; emperor is its French-shaped descendant.","definitionCN":"拉丁统帅称号本身，罗马史中仍在使用；emperor 是其经法语改造的后代。"}]},{"heading":"NEAR MEANING","entries":[{"word":"king","ipa":"/kɪŋ/","tag":"royal ruler","definition":"The ruler of a kingdom; the rank is lower than emperor in the traditional hierarchy of titles.","definitionCN":"王国的统治者；在传统称号等级中低于皇帝。"},{"word":"monarch","ipa":"/ˈmɒnək/","tag":"generic sovereign","definition":"A neutral word for a sole hereditary ruler, whether king, queen or emperor.","definitionCN":"指唯一的世袭统治者，不论国王、女王或皇帝，是中性的说法。"},{"word":"sovereign","ipa":"/ˈsɒvrɪn/","tag":"supreme authority","definition":"A ruler or state holding supreme power; it stresses legal independence rather than title.","definitionCN":"握有最高权力的统治者或国家；强调法律上的独立而非称号。"},{"word":"tsar","ipa":"/tsɑː/","tag":"Russian title","definition":"The Russian imperial title, from Caesar; it is a national equivalent, not a synonym in English usage.","definitionCN":"俄国的皇帝称号，源自 Caesar；是国别对应词，在英语用法中并非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"imperare 'command' + -tor 'one who': the one who gives orders.","cn":"imperare「命令」+ -tor「做事者」：发号施令的人。"},{"en":"The family runs emperor, empress, emperorship, empire, imperial, imperialism.","cn":"同族词包括 emperor、empress、emperorship、empire、imperial、imperialism。"},{"en":"Fixed phrases: the Roman emperor, the emperor of Japan, emperor penguin.","cn":"固定搭配：罗马皇帝、日本天皇、帝企鹅。"},{"en":"Roman troops acclaimed a general as imperator before the title belonged to a throne.","cn":"罗马士兵先欢呼将领为统帅，后来这个称号才属于皇位。"},{"en":"Naturalists name the biggest butterfly and moth of a group after an emperor.","cn":"博物学者把一组中最大的蛱蝶与蛾以皇帝命名。"}],"abstract":[{"en":"Picture a crown resting on top of a military badge.","cn":"想象一顶金冠压在军徽之上。"},{"en":"Picture a man whose cloak is longer than the room he stands in.","cn":"想象一个人的披风比他站的房间还长。"},{"en":"Picture a newspaper owner who signs his name the way a ruler signs a decree.","cn":"想象一位报业老板签名的样子，像君主签署敕令。"}]},"examples":[{"en":"The emperor granted the city a charter and a garrison.","cn":"皇帝授予这座城市特许状与一支驻军。"},{"en":"An emperor butterfly basked on the warm stone of the wall.","cn":"一只帝王蛱蝶在墙上的暖石上晒着翅膀。"},{"en":"The biographer described him as an emperor of the auction room.","cn":"传记作者称他为拍卖场上的霸主。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「emperor」音近「俺怕老」——群臣都怕的老者坐在金冠之下 → 皇帝","word":"emperor"},"root":"拉丁 imperator「统帅、发令者」= imperare「命令」+ -tor（施动名词后缀）；imperare 出自 in-「加于」+ parare「安排」。英语 emperor。","sensesIntro":{"en":"Eight senses follow one title as it travels: from a battlefield acclamation to a throne, then to a constitutional figurehead, then to any unquestioned master, and finally to the largest butterfly and moth.","cn":"八个义项随一个称号移动：从战场欢呼到皇位，再到立宪元首，再到任何不受质疑的支配者，最后落到最大的蛱蝶与蛾。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crown placed on top of a commander's badge, with a cloak spreading to the edge of the map.","cn":"核心意象：金冠压在统帅军徽之上，披风一直铺到地图边缘。"},"chain":["ACCLAIMED COMMANDER","IMPERIAL SOVEREIGN","HEAD OF AN EMPIRE","CONSTITUTIONAL FIGUREHEAD","DOMINANT PERSON","BORROWED NAME"],"branches":[{"senses":"S4","en":"THE ACCLAMATION: the oldest layer, a general hailed on the field.","cn":"欢呼：最古老的一层，战场上被欢呼的将领。"},{"senses":"S1 · S2 · S3","en":"THE THRONE: the title becomes an office, then a named historical ruler, then a ceremonial head of state.","cn":"皇位：称号变成职位，再变成具名的历史君主，最后成为礼仪性元首。"},{"senses":"S7","en":"THE METAPHOR: absolute command transferred to an industry or a sport.","cn":"比喻：绝对统治被移到行业或运动上。"},{"senses":"S5 · S8","en":"THE CREATURES: the largest butterfly and moth borrow the grandest title.","cn":"生物：最大的蛱蝶与蛾借用了最宏大的称号。"},{"senses":"S6","en":"THE CARD: a tarot trump depicts a seated ruler and takes his name.","cn":"纸牌：一张塔罗王牌画着端坐的统治者，并取其名。"}]},"affixes":{"intro":{"en":"Emperor is a Latin agent noun plus a French-shaped ending, and its parts also build empire and imperial, so the family can be read morpheme by morpheme.","cn":"emperor 是拉丁施动名词加法语化词尾，其成分也构成 empire 与 imperial，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin imperare and its agent noun imperator give emperor; the same verb yields imperial and imperium.","cn":"拉丁 imperare 及其施动名词 imperator 衍生 emperor；同一动词还衍生 imperial 与 imperium。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, upon'; im- before p)","meaning":"in; upon","meaningCN":"在……之中；加于","example":"The prefix places the command onto its object.","exampleCN":"这个前缀把命令放置到对象之上。"},{"word":"parare","structure":"parare (Latin verb, first conjugation)","meaning":"to arrange, prepare","meaningCN":"安排；准备","example":"The root carries the idea of setting things in order.","exampleCN":"这个词根带着「把事情排好」的意思。"},{"word":"imperare","structure":"in- + parare","meaning":"to command","meaningCN":"命令","example":"To command is to lay an order upon someone.","exampleCN":"下命令就是把一件事安排到别人头上。"},{"word":"-tor","structure":"-tor (Latin agent-noun suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix turns a verb into the person who performs it.","exampleCN":"这个后缀把动词转为执行该动作的人。"},{"word":"imperator","structure":"imperare + -tor","meaning":"commander","meaningCN":"统帅","example":"The troops hailed their general as imperator.","exampleCN":"士兵欢呼他们的将领为统帅。"},{"word":"emperor","structure":"imperator, through Old French empereor","meaning":"ruler of an empire","meaningCN":"帝国的统治者","example":"The emperor received the envoys.","exampleCN":"皇帝接见了使节。"},{"word":"empress","structure":"emperor + -ess (feminine suffix)","meaning":"female ruler or consort","meaningCN":"女皇；皇后","example":"The empress opened the ceremony.","exampleCN":"女皇为典礼揭幕。"},{"word":"imperial","structure":"imperium + -ialis (relational adjective)","meaning":"of an emperor","meaningCN":"皇帝的","example":"The imperial seal closed the letter.","exampleCN":"皇帝的印章封上了信。"},{"word":"empire","structure":"imperium, through Old French","meaning":"dominion","meaningCN":"疆域；帝国","example":"The empire stretched to the sea.","exampleCN":"帝国一直延伸到海边。"}],"latinEntries":[{"word":"imperare","structure":"imperare, imperavi, imperatum (verb, first conjugation)","meaning":"to command, order","meaningCN":"命令；吩咐"},{"word":"imperator","structure":"imperator, imperatoris (m., third declension)","meaning":"commander","meaningCN":"统帅"},{"word":"imperium","structure":"imperium, imperii (n., second declension)","meaning":"command, authority","meaningCN":"治权；权威"},{"word":"imperialis","structure":"imperialis, imperiale (adjective, third declension)","meaning":"of an emperor or empire","meaningCN":"皇帝的；帝国的"}]}},{"word":"dynasty","ipa_uk":"/ˈdɪnəsti/","ipa_us":"/ˈdaɪnəsti/","definition_zh":"王朝；同一家族世代相继的统治；某王朝统治的时期；世代传承的大家族或企业；长期称霸的队伍","definition_en":"a succession of rulers from the same family, the period of their rule, and by extension any powerful family or dominant group that lasts for generations","core_image":"一条族谱横贯数代画像，每幅画像手里都握着同一枚印玺","scene":"祠堂的墙上挂着十几幅画像，面容不同，手中都握着同一枚印。The dynasty ruled for three hundred years before the last heir died childless.","sceneCN":"这里 dynasty 指「同一家族世代相继的统治」（第 1 个义项：权力在同一血脉内传递）；句意为这个王朝统治三百年，直到最后一位继承人无子而终。可辨识物件：祠堂、画像、族谱、印玺、蜡烛。","pos":[{"tag":"n.","zh":"王朝；王朝统治期；世家；长期称霸的团队"}],"collocations":[{"phrase":"the Tang dynasty","zh":"唐朝"},{"phrase":"a ruling dynasty","zh":"统治王朝"},{"phrase":"found a dynasty","zh":"建立王朝"},{"phrase":"a political dynasty","zh":"政治世家"},{"phrase":"a business dynasty","zh":"商业世家"},{"phrase":"the dynasty's decline","zh":"王朝的衰亡"}],"forms":[{"label":"单数","form":"dynasty"},{"label":"复数","form":"dynasties"},{"label":"形容词（王朝的）","form":"dynastic"},{"label":"名词（王朝成员、君王）","form":"dynast"},{"label":"副词（以王朝方式）","form":"dynastically"}],"derivatives":[{"word":"dynastic","pos":"adj.","zh":"dynasty + -ic（形容词后缀，经拉丁 -icus、希腊 -ikos）→ 王朝的，语义由家族名转为属性"},{"word":"dynastically","pos":"adv.","zh":"dynastic + -ally（副词后缀）→ 以王朝、世袭方式地"},{"word":"dynast","pos":"n.","zh":"希腊 dynastes 经拉丁 dynasta → 王朝君主、世袭统治者，语义由抽象统治转为具体的人"},{"word":"dynasticism","pos":"n.","zh":"dynastic + -ism（体系后缀）→ 王朝主义、以世袭家族为中心的政治（较少用）"}],"senses":[{"no":"01","title":"A ruling family succeeding itself","titleCN":"同一家族世代相继的统治","definition":"a line of rulers drawn from one family and following one another by inheritance","definitionCN":"出自同一家族、依继承顺序相继即位的一连串统治者","example":"The dynasty ruled for three hundred years before the last heir died childless.","exampleCN":"这个王朝统治了三百年，直到最后一位继承人无子而终。","why":"Greek dynasteia named lordship itself, and English narrowed it to a family's continuous hold on power.","whyCN":"希腊 dynasteia 本指领主统治，英语把它收窄为一个家族对权力的连续掌握。"},{"no":"02","title":"The period of a family's rule","titleCN":"某个王朝统治的时期","definition":"the span of time during which one ruling family held power, used as a historical period","definitionCN":"一个统治家族掌权的时段，用作历史分期","example":"Most of the canal was dug during the dynasty.","exampleCN":"这条运河的大部分是在该王朝时期开凿的。","why":"A ruling house marks time so strongly that its name becomes a period label, as in 'Tang poetry'.","whyCN":"统治家族对时间的标记如此强烈，其名便成为时期标签，如「唐诗」。"},{"no":"03","title":"A family business carried through generations","titleCN":"世代传承的家族企业","definition":"a family that controls a business or fortune across several generations","definitionCN":"连续数代控制一家企业或一笔家产的家族","example":"The dynasty of shipbuilders lasted five generations.","exampleCN":"这个造船世家延续了五代。","why":"The political model was transferred to commerce: inheritance and continuity matter more than any single owner.","whyCN":"政治模型被移到商业上：继承与延续比任何单一所有者都重要。"},{"no":"04","title":"A political family","titleCN":"政治世家","definition":"a family that holds public office or party power across generations","definitionCN":"连续数代掌握公职或政党权力的家族","example":"A political dynasty held the mayor's office for decades.","exampleCN":"一个政治世家把市长职位握了几十年。","why":"Elections do not prevent the same surname from recurring, so the hereditary image fits modern politics too.","whyCN":"选举并不能阻止同一个姓氏反复出现，因此世袭意象也适用于现代政治。"},{"no":"05","title":"A team that dominates a sport","titleCN":"长期称霸某运动的队伍","definition":"a sports team that wins championships repeatedly over a long stretch","definitionCN":"在很长一段时期内反复夺冠的运动队","example":"The club became a dynasty by winning six titles in eight years.","exampleCN":"这家俱乐部八年内六次夺冠，成为一个王朝。","why":"American sports writing borrowed the word for uninterrupted excellence, keeping the sense of succession without a crown.","whyCN":"美国体育写作借这个词形容不间断的卓越，保留了「相继」之意，却不再有王冠。"},{"no":"06","title":"A named house used as a period label","titleCN":"作为历史分期名称的具名王朝","definition":"the proper name of a ruling house used to divide history into eras","definitionCN":"统治家族的专名，被用来把历史划分为若干时期","example":"Scholars divide the era by dynasty rather than by century.","exampleCN":"学者按王朝而非世纪来划分这个时代。","why":"Where one family ruled long enough, its name became the standard unit of chronology.","whyCN":"当一个家族统治足够久，其名便成为年代学的标准单位。"},{"no":"07","title":"A line of artists or craftsmen","titleCN":"世代相传的艺人或工匠世家","definition":"a family whose members carry on the same art or craft over several generations","definitionCN":"家族成员连续数代从事同一门艺术或手艺","example":"A dynasty of violin makers trained every apprentice in the valley.","exampleCN":"一个制琴世家训练了山谷里所有的学徒。","why":"Craft succession copies biological succession: the workshop passes like a throne.","whyCN":"手艺的传承模仿血脉的传承：作坊像王位一样传下去。"},{"no":"08","title":"A bloodline traced through generations","titleCN":"世代可追溯的血脉","definition":"a family line itself, considered as a continuous descent rather than as rulers","definitionCN":"家族血脉本身，被视为连续世系而非统治者","example":"The genealogy traces the dynasty back to a single magistrate.","exampleCN":"这份族谱把这个家族一直追溯到一位地方官。","why":"Before it meant rulers, the Greek word meant lordship; the family line is the substratum that carries the office.","whyCN":"在指统治者之前，这个希腊词指领主身份；家族血脉是承载职位的底层。"}],"etymology":{"intro":{"en":"Dynasty comes through Latin and French from Greek dynasteia 'lordship, rule', built on dynastes 'lord' and dynasthai 'to be able, to have power'. Dates are approximate.","cn":"dynasty 经拉丁与法语来自希腊 dynasteia「领主统治」，由 dynastes「领主」与 dynasthai「能够、有权力」构成。年代均为约数。"},"items":[{"era":"GREEK DYNASTHAI","en":"Dynasthai meant 'to be able, to have power'; it is related to dynamis 'power', the source of dynamic and dynamo.","cn":"dynasthai 意为「能够、拥有权力」，与 dynamis「力量」同源，后者是 dynamic 与 dynamo 的来源。"},{"era":"GREEK DYNASTES","en":"The agent noun dynastes named a lord or ruler, literally one who has power.","cn":"施动名词 dynastes 指领主或统治者，字面就是「有权力的人」。"},{"era":"GREEK DYNASTEIA","en":"The abstract noun dynasteia named lordship or rule, and it is this form that passed into Latin.","cn":"抽象名词 dynasteia 指领主统治，进入拉丁语的正是这一形式。"},{"era":"LATIN AND FRENCH","en":"Latin dynastia and French dynastie carried the word westward; English had it by the late fourteenth century.","cn":"拉丁 dynastia 与法语 dynastie 把这个词向西传；英语在十四世纪后期已有此词。"},{"era":"MODERN EXTENSIONS","en":"The business sense is nineteenth-century, and the sports sense is twentieth-century American usage; both keep the idea of unbroken succession.","cn":"商业义出现于十九世纪，体育义是二十世纪美国用法；两者都保留「不间断相继」的观念。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact first English citation is not established, and the precise relationship between dynasthai and dynamis is accepted in outline but not documented in every detail.","cn":"来源不确定（首见年代）：确切的最早英语书证未有定论；dynasthai 与 dynamis 的关系在大体上被接受，但细节并非全部有据。"}]},"similar":{"note":{"en":"Group one holds forms from the same Greek root or accidental neighbours; group two holds words for a continuous ruling line.","cn":"第一组是同出希腊词根或偶然相邻的形式；第二组是表示连续统治世系的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dynastic","ipa":"/dɪˈnæstɪk/","tag":"same root, adjective","definition":"The adjective of dynasty, from Greek dynastikos through Latin dynasticus.","definitionCN":"dynasty 的形容词，经拉丁 dynasticus 出自希腊 dynastikos。"},{"word":"dynast","ipa":"/ˈdaɪnæst/","tag":"same root, person","definition":"A ruler or member of a ruling family, from Greek dynastes; it names the person, not the line.","definitionCN":"统治者或统治家族成员，出自希腊 dynastes；指人而非世系。"},{"word":"dynamic","ipa":"/daɪˈnæmɪk/","tag":"related root","definition":"From Greek dynamis 'power', a cousin of dynasthai: it means full of force or change, not hereditary rule.","definitionCN":"出自希腊 dynamis「力量」，与 dynasthai 同族：意为充满力量或变化的，与世袭统治无关。"},{"word":"dynamo","ipa":"/ˈdaɪnəməʊ/","tag":"related root","definition":"A machine that generates current, named from dynamis 'power'; it shares the power root but not the political sense.","definitionCN":"发电机的名称，取自动力之义；共享「力量」词根，但无政治义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"house","ipa":"/haʊs/","tag":"ruling family","definition":"A royal or noble family, as in the House of Habsburg; it stresses lineage and alliance rather than a sequence of rulers.","definitionCN":"王室或贵族家族，如哈布斯堡家族；侧重血脉与联姻，而非统治者序列。"},{"word":"line","ipa":"/laɪn/","tag":"descent","definition":"A continuous descent from an ancestor; it can describe any family, not only one that rules.","definitionCN":"自某一祖先传下的连续血脉；可指任何家族，不限统治家族。"},{"word":"regime","ipa":"/rɪˈdʒiːm/","tag":"system of rule","definition":"A particular government or system; it need not be hereditary and usually names the arrangement, not the family.","definitionCN":"特定的政府或制度；不必世袭，通常指制度安排而非家族。"},{"word":"family","ipa":"/ˈfæməli/","tag":"kin group","definition":"The ordinary word for relatives; it lacks the political sense of inherited rule that dynasty carries.","definitionCN":"指亲属的日常词；不含 dynasty 那种继承统治的政治含义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek dynasthai 'have power' + -eia: a body of power held in one line.","cn":"希腊 dynasthai「拥有权力」+ -eia：握在一条世系里的权力。"},{"en":"The family runs dynasty, dynastic, dynast, dynastically.","cn":"同族词包括 dynasty、dynastic、dynast、dynastically。"},{"en":"Fixed phrases: the Tang dynasty, a ruling dynasty, found a dynasty.","cn":"固定搭配：唐朝、统治王朝、建立王朝。"},{"en":"dynamic and dynamo share the power root dynamis but not the political sense.","cn":"dynamic 与 dynamo 共享 dynamis 这一「力量」词根，但无政治义。"},{"en":"The same word covers a shipbuilding family and a championship team.","cn":"同一个词既能指造船世家，也能指夺冠球队。"}],"abstract":[{"en":"Picture a family portrait where every face holds the same seal.","cn":"想象一幅全家福，每张脸都握着同一枚印。"},{"en":"Picture a relay race in which the baton is a crown.","cn":"想象一场接力赛，接力棒是一顶王冠。"},{"en":"Picture a workshop sign repainted with the same surname for five generations.","cn":"想象一块作坊招牌，同一个姓氏被重描了五代。"}]},"examples":[{"en":"The last dynasty fell after a decade of harvest failures.","cn":"最后一个王朝在连续十年歉收后覆灭。"},{"en":"The museum labels the pottery by dynasty and by kiln.","cn":"博物馆按王朝与窑口给这些陶器贴标签。"},{"en":"A banking dynasty survived three financial crises by staying private.","cn":"一个银行世家靠保持私有挺过了三次金融危机。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dynasty」音近「代那事体」——一代接一代都办同一件事：坐江山 → 王朝","word":"dynasty"},"root":"希腊 dynasteia「领主统治」= dynastes「领主」+ -eia（抽象名词后缀）；dynastes 出自 dynasthai「拥有权力」，与 dynamis「力量」同源。经拉丁 dynastia、法语 dynastie 入英语。","sensesIntro":{"en":"Eight senses follow one bloodline: a family hands power downward. The line becomes a period, a firm, a party, a team, a craft and finally a genealogy.","cn":"八个义项沿同一条血脉展开：一个家族把权力往下传。这条线依次成为时期、企业、政党、球队、手艺，最后成为族谱。"},"semanticMap":{"core":{"en":"CORE IMAGE: a family tree laid across a row of portraits, each hand holding the same seal.","cn":"核心意象：一条族谱横贯一排画像，每只手都握着同一枚印。"},"chain":["BLOODLINE","SUCCESSION","RULE","PERIOD","FAMILY ENTERPRISE","DOMINANT TEAM"],"branches":[{"senses":"S1 · S8","en":"THE LINE: ancestry is the channel through which power passes.","cn":"血脉：祖先世系是权力传递的通道。"},{"senses":"S2 · S6","en":"THE PERIOD: a long-ruling house becomes a unit of chronology.","cn":"时期：长期统治的家族成为年代单位。"},{"senses":"S3 · S4","en":"THE FAMILY HOLDING: commerce and politics inherit the hereditary pattern.","cn":"家族把持：商业与政治都继承了世袭模式。"},{"senses":"S5","en":"THE TEAM: sport keeps the succession but drops the crown.","cn":"球队：体育保留了「相继」，去掉了王冠。"},{"senses":"S7","en":"THE CRAFT: a workshop can pass like a throne.","cn":"手艺：作坊也能像王位一样传下去。"}]},"affixes":{"intro":{"en":"Dynasty is a Greek noun that came west through Latin and French; its root and suffix also build dynast, dynastic and dynamic, so the family can be read morpheme by morpheme.","cn":"dynasty 是经拉丁与法语西传的希腊名词；其词根与后缀也构成 dynast、dynastic 与 dynamic，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Greek dynasthai and dynastes give dynast and dynasty; Latin dynastia passed into French dynastie and then English.","cn":"希腊 dynasthai 与 dynastes 衍生 dynast 与 dynasty；拉丁 dynastia 传入法语 dynastie，再进入英语。"},"items":[{"word":"dynasthai","structure":"dynasthai (Greek verb, 'to be able, to have power')","meaning":"to have power","meaningCN":"拥有权力","example":"The root ties ruling to the idea of being able.","exampleCN":"这个词根把统治与「有能力」联系起来。"},{"word":"-tes","structure":"-tes (Greek agent-noun suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix makes a person out of the verb.","exampleCN":"这个后缀把动词变成人。"},{"word":"dynastes","structure":"dynasthai + -tes","meaning":"lord, ruler","meaningCN":"领主；统治者","example":"A dynastes held power by inheritance.","exampleCN":"领主凭继承掌握权力。"},{"word":"-eia","structure":"-eia (Greek abstract-noun suffix)","meaning":"state or system of","meaningCN":"……的状态或体系","example":"The suffix turns the ruler into the institution of rule.","exampleCN":"这个后缀把统治者转为统治制度。"},{"word":"dynasteia","structure":"dynastes + -eia","meaning":"lordship, rule","meaningCN":"领主统治","example":"Lordship passed from father to son.","exampleCN":"领主之位由父传子。"},{"word":"-ic","structure":"-ikos (Greek adjective suffix, -icus in Latin)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix built dynastic from dynasty.","exampleCN":"这个后缀由 dynasty 构成 dynastic。"},{"word":"dynasty","structure":"dynasteia, through Latin dynastia and French dynastie","meaning":"a ruling family line","meaningCN":"统治家族世系","example":"The dynasty ruled for three centuries.","exampleCN":"这个王朝统治了三个世纪。"},{"word":"dynastic","structure":"dynasty + -ic","meaning":"of a dynasty","meaningCN":"王朝的","example":"Dynastic marriage joined two crowns.","exampleCN":"王朝联姻把两顶王冠连在一起。"},{"word":"dynast","structure":"dynastes, through Latin dynasta","meaning":"a ruler of a line","meaningCN":"世袭统治者","example":"The last dynast abdicated.","exampleCN":"最后一位世袭君主退位了。"},{"word":"dynamic","structure":"Greek dynamis 'power' + -ikos","meaning":"full of force","meaningCN":"充满力量的","example":"The market was dynamic and unpredictable.","exampleCN":"市场充满活力且难以预测。"}],"latinEntries":[{"word":"dynastia","structure":"dynastia, dynastiae (f., first declension)","meaning":"lordship, rule","meaningCN":"领主统治"},{"word":"dynastes","structure":"dynastes, dynastae (m., first declension)","meaning":"lord, ruler","meaningCN":"领主；统治者"},{"word":"dynasticus","structure":"dynasticus, dynastica, dynasticum (adjective, first and second declension)","meaning":"of a ruling house","meaningCN":"统治家族的"}]}},{"word":"dynastic","ipa_uk":"/dɪˈnæstɪk/","ipa_us":"/dɪˈnæstɪk/","definition_zh":"王朝的；与王朝统治相关的；以家族世袭为基础的；涉及王朝联姻或继承争斗的","definition_en":"relating to a dynasty or to rule inherited within one family, including marriages and succession disputes between ruling houses","core_image":"两枚族徽并排刻在同一份婚约上，纸边压着一份未拆的继承诏书","scene":"老档案馆的桌上摊开一份婚约，两枚族徽被红线系在一起，旁边放着一封尚未拆开的继承诏书。The dynastic marriage joined two rival houses and ended a century of war.","sceneCN":"这里 dynastic 指「与王朝或家族世袭统治相关的」（第 4 个义项：以联姻连接两个统治家族）；句意为这场王朝联姻把两个敌对家族连在一起，终结了百年战争。可辨识物件：婚约、族徽、红线、继承诏书、蜡封。","pos":[{"tag":"adj.","zh":"王朝的；世袭统治的；涉及王朝联姻或继承的"}],"collocations":[{"phrase":"dynastic rule","zh":"王朝统治"},{"phrase":"dynastic marriage","zh":"王朝联姻"},{"phrase":"dynastic succession","zh":"王朝继承"},{"phrase":"dynastic dispute","zh":"王朝继承争端"},{"phrase":"dynastic politics","zh":"家族世袭政治"},{"phrase":"dynastic change","zh":"王朝更替"}],"forms":[{"label":"原级","form":"dynastic"},{"label":"比较级","form":"more dynastic"},{"label":"最高级","form":"most dynastic"},{"label":"副词","form":"dynastically"},{"label":"名词（王朝）","form":"dynasty"}],"derivatives":[{"word":"dynastically","pos":"adv.","zh":"dynastic + -ally（副词后缀）→ 以王朝或世袭方式地"},{"word":"dynasticism","pos":"n.","zh":"dynastic + -ism（体系后缀）→ 以世袭家族为核心的政治主张（较少用）"},{"word":"dynasty","pos":"n.","zh":"dynastic 去掉 -ic 后回溯到希腊 dynasteia → 王朝，语义由属性回到实体"},{"word":"dynast","pos":"n.","zh":"希腊 dynastes 经拉丁 → 世袭君主，语义由属性转为人"},{"word":"non-dynastic","pos":"adj.","zh":"non-（否定前缀）+ dynastic → 非王朝的、非世袭的"},{"word":"anti-dynastic","pos":"adj.","zh":"anti-（反对前缀）+ dynastic → 反王朝世袭的"}],"senses":[{"no":"01","title":"Relating to a dynasty","titleCN":"与王朝相关的","definition":"connected with a ruling family line as such","definitionCN":"与统治家族世系本身相关","example":"Dynastic rule depended on a recognised heir.","exampleCN":"王朝统治依赖一位被承认的继承人。","why":"The suffix -ic simply makes the noun into an adjective of relation, so anything touching a dynasty is dynastic.","whyCN":"后缀 -ic 只是把名词转为关系形容词，凡与王朝相关的事物都是 dynastic。"},{"no":"02","title":"Relating to a named historical house","titleCN":"与某个具名历史王朝相关的","definition":"used of a particular ruling house as a period or regime, often capitalised in historical writing","definitionCN":"指某一特定统治家族作为时期或政权，历史写作中常大写","example":"Dynastic Egypt lasted for thousands of years.","exampleCN":"王朝时期的埃及延续了数千年。","why":"Historians label whole eras by the house that ruled, so the adjective attaches to a proper period name.","whyCN":"史家用统治家族标记整个时代，因此这个形容词附着在专有时期名上。"},{"no":"03","title":"Based on hereditary succession","titleCN":"以家族世袭为基础的","definition":"describing a system in which office passes by inheritance within one family","definitionCN":"指职位在同一家族内依继承传递的制度","example":"The party rejected dynastic politics in its charter.","exampleCN":"该党在章程中排斥家族世袭政治。","why":"The adjective can criticise a modern institution by measuring it against the hereditary model.","whyCN":"这个形容词可以用世袭模型衡量现代机构，从而带批评意味。"},{"no":"04","title":"Of a marriage between ruling houses","titleCN":"统治家族之间联姻的","definition":"describing a marriage arranged to unite two dynasties or their claims","definitionCN":"指为联合两个王朝或其继承主张而安排的婚姻","example":"The dynastic marriage joined two rival houses and ended a century of war.","exampleCN":"这场王朝联姻把两个敌对家族连在一起，终结了百年战争。","why":"Marriage was a treaty instrument, so the adjective marks unions made for succession rather than affection.","whyCN":"婚姻曾是条约工具，因此这个形容词标记为继承而非情感缔结的联合。"},{"no":"05","title":"Of a succession dispute","titleCN":"继承争端引起的","definition":"describing a conflict over which heir or house should hold power","definitionCN":"指围绕哪位继承人、哪个家族应掌权的冲突","example":"A dynastic war followed the old king's death.","exampleCN":"老王去世后爆发了一场王朝战争。","why":"When inheritance rules are unclear, the family line itself becomes the fault line of a war.","whyCN":"当继承规则不明，家族世系本身就成了战争的分裂线。"},{"no":"06","title":"Of inherited control in a firm","titleCN":"企业中世袭控制的","definition":"describing a business in which ownership and top posts pass within one family","definitionCN":"指所有权与高位在同一家族内传递的企业","example":"The firm's dynastic control passed to a cousin.","exampleCN":"这家公司的世袭控制权传给了一位表亲。","why":"The political pattern repeats in commerce whenever shares and seats follow the family tree.","whyCN":"只要股份与席位沿族谱传递，政治模式就会在商业中重演。"},{"no":"07","title":"Of a family's official portraits","titleCN":"王朝官方肖像的","definition":"describing art or imagery made to present a ruling family as a continuous line","definitionCN":"指为把统治家族呈现为连续世系而制作的艺术或图像","example":"The gallery hung a series of dynastic portraits in one long row.","exampleCN":"画廊把一系列王朝肖像排成长长的一行。","why":"Portraits were political tools, so their style and arrangement are called dynastic rather than merely royal.","whyCN":"肖像曾是政治工具，因此其风格与排列被称作王朝式，而不只是王室式。"},{"no":"08","title":"Of long-lasting dominance in sport or art","titleCN":"体育或艺术中长期称霸的","definition":"describing a period in which one team or school dominates as if by inheritance","definitionCN":"指某支队伍或流派像凭继承般长期支配的时期","example":"The team's dynastic run ended in the final.","exampleCN":"这支球队的王朝式连胜在决赛中结束。","why":"The sports extension keeps succession and dominance but drops the crown, just as dynasty did.","whyCN":"体育引申保留了相继与支配，却去掉了王冠，与 dynasty 的路径相同。"}],"etymology":{"intro":{"en":"Dynastic is the adjective of dynasty, formed with the Greek suffix -ikos, which Latin reshaped as -icus. It reached English through French and Latin. Dates are approximate.","cn":"dynastic 是 dynasty 的形容词，由希腊后缀 -ikos 构成，拉丁语把它改造为 -icus，再经法语与拉丁进入英语。年代均为约数。"},"items":[{"era":"GREEK DYNASTHAI","en":"Dynasthai 'to have power' is the root of the whole family, related to dynamis 'power'.","cn":"dynasthai「拥有权力」是整个词族的词根，与 dynamis「力量」同源。"},{"era":"GREEK DYNASTEIA","en":"Dynasteia 'lordship, rule' passed into Latin as dynastia, the noun behind dynasty.","cn":"dynasteia「领主统治」进入拉丁语作 dynastia，是 dynasty 背后的名词。"},{"era":"GREEK -IKOS","en":"The suffix -ikos meant 'relating to'; it was the standard way to make an adjective from a noun.","cn":"后缀 -ikos 意为「与……相关的」，是把名词转为形容词的标准手段。"},{"era":"LATIN DYNASTICUS","en":"Latin dynasticus carried the adjective form, and French transmitted it to English.","cn":"拉丁 dynasticus 承载这一形容词形式，再经法语传入英语。"},{"era":"MODERN USES","en":"The marriage, dispute and sports senses are later extensions, all keeping the idea of a line that passes something down.","cn":"联姻、争端与体育义都是较晚的引申，均保留「沿世系传递」的观念。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English use of the adjective is not recorded precisely, and the sports sense has no single documented origin.","cn":"来源不确定（首见年代）：这个形容词的最早英语书证并不确切，体育义也没有唯一可考的来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same root or accidental neighbours; group two holds adjectives describing inherited or royal power.","cn":"第一组是同出该词根或偶然相邻的形式；第二组是描述世袭或王权的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dynasty","ipa":"/ˈdɪnəsti/","tag":"same root, noun","definition":"The ruling family line itself; dynastic is its relational adjective.","definitionCN":"统治家族世系本身；dynastic 是它的关系形容词。"},{"word":"dynast","ipa":"/ˈdaɪnæst/","tag":"same root, person","definition":"A ruler belonging to such a line, from Greek dynastes.","definitionCN":"属于该世系的统治者，出自希腊 dynastes。"},{"word":"dynamic","ipa":"/daɪˈnæmɪk/","tag":"related root","definition":"From dynamis 'power': energetic or changing. It shares the power root but has nothing to do with inheritance.","definitionCN":"出自 dynamis「力量」：有活力或不断变化的。共享「力量」词根，但与继承无关。"},{"word":"dynasticism","ipa":"/daɪˈnæstɪsɪzəm/","tag":"derived noun","definition":"The rare noun for a political attachment to hereditary houses; a derived form, not a synonym.","definitionCN":"指依附于世袭家族的政治主张，是罕见派生名词，并非同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hereditary","ipa":"/həˈredɪtəri/","tag":"passed by blood","definition":"Passing by inheritance from parent to child; it describes the mechanism, while dynastic describes the family line as a political unit.","definitionCN":"由父母传子女；描述机制，而 dynastic 描述作为政治单位的家族世系。"},{"word":"royal","ipa":"/ˈrɔɪəl/","tag":"of a king","definition":"Belonging to a king or queen; dynastic can apply to any ruling house, including non-royal ones in modern politics.","definitionCN":"属于国王或女王；dynastic 可用于任何统治家族，包括现代政治中的非王室家族。"},{"word":"lineal","ipa":"/ˈlaɪnəl/","tag":"direct descent","definition":"Descended in a direct line from an ancestor; it is about genealogy, not about rule.","definitionCN":"自祖先直系传下；说的是谱系，而非统治。"},{"word":"succession","ipa":"/səkˈseʃn/","tag":"of succession","definition":"The process by which one person takes over an office or throne from another; it names the legal process rather than the family.","definitionCN":"一人接替另一人职位或王位的过程；指法律程序而非家族。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"dynasty + -ic: the adjective of a ruling family line.","cn":"dynasty + -ic：统治家族世系的形容词。"},{"en":"The family runs dynasty, dynast, dynastic, dynastically.","cn":"同族词包括 dynasty、dynast、dynastic、dynastically。"},{"en":"Fixed phrases: dynastic rule, dynastic marriage, dynastic dispute.","cn":"固定搭配：王朝统治、王朝联姻、王朝争端。"},{"en":"dynamic shares the power root dynamis but is about energy, not inheritance.","cn":"dynamic 共享 dynamis 这一力量词根，但讲的是活力，不是继承。"},{"en":"Modern politics and sport both use it for inherited or uninterrupted dominance.","cn":"现代政治与体育都用它指世袭或不间断的支配。"}],"abstract":[{"en":"Picture two family crests tied by a single red thread.","cn":"想象两枚族徽被一根红线系在一起。"},{"en":"Picture a job title that is written on a birth certificate.","cn":"想象一个职位头衔被写进出生证明。"},{"en":"Picture a trophy cabinet arranged like a family tree.","cn":"想象一座奖杯柜，排列得像一棵族谱树。"}]},"examples":[{"en":"Dynastic loyalty held the province quiet for a generation.","cn":"对王朝的忠诚让这个行省安稳了一代人。"},{"en":"The treaty was sealed by a dynastic marriage rather than by a border.","cn":"这项条约靠一桩王朝联姻而非一条边界来缔结。"},{"en":"Critics called the arrangement dynastic because the post passed to a son.","cn":"批评者称这种安排为世袭，因为职位传给了儿子。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dynasty」去掉 y 加 ic——凡沾上王朝的，都叫 dynastic；记「王朝的」先记 dynasty","word":"dynastic"},"root":"dynasty「王朝」+ -ic（希腊 -ikos、拉丁 -icus 形容词后缀）；dynasty 出自希腊 dynasteia「领主统治」，再上溯 dynasthai「拥有权力」。英语 dynastic。","sensesIntro":{"en":"Eight senses apply one adjective to everything a ruling line touches: its rule, its named era, its inheritance rule, its marriages, its wars, its firms, its portraits and even its modern imitators.","cn":"八个义项把同一个形容词用到统治世系触及的一切：统治、具名时代、继承规则、联姻、战争、企业、肖像，乃至现代的模仿者。"},"semanticMap":{"core":{"en":"CORE IMAGE: two crests tied by a red thread on a marriage contract, with an unopened succession decree beside it.","cn":"核心意象：婚约上两枚族徽被红线系住，旁边放着一份未拆的继承诏书。"},"chain":["RULING HOUSE","HEIR","SUCCESSION","MARRIAGE ALLIANCE","SUCCESSION WAR","ENDURING DOMINANCE"],"branches":[{"senses":"S1 · S2","en":"THE HOUSE: the family line and the era named after it.","cn":"家族：世系本身与以之命名的时代。"},{"senses":"S3","en":"THE RULE OF INHERITANCE: office passes by blood, whether in a state or a modern party.","cn":"继承规则：职位凭血脉传递，无论在国家还是现代政党。"},{"senses":"S4","en":"THE ALLIANCE: marriage joins two claims into one.","cn":"联盟：婚姻把两项继承主张并为一项。"},{"senses":"S5","en":"THE DISPUTE: unclear inheritance turns the family line into a frontline.","cn":"争端：继承不明使家族世系变成前线。"},{"senses":"S6 · S7 · S8","en":"THE IMITATION: firms, portraits and teams copy the hereditary pattern.","cn":"模仿：企业、肖像与球队都在复制世袭模式。"}]},"affixes":{"intro":{"en":"Dynastic is a Greek-rooted noun plus an adjective suffix, and both parts recur in English, so the family can be read morpheme by morpheme.","cn":"dynastic 是希腊词根名词加形容词后缀，两部分都在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Greek dynasthai and dynasteia give dynast and dynasty; the suffix -ikos, Latin -icus, gives dynastic and dynamic.","cn":"希腊 dynasthai 与 dynasteia 衍生 dynast 与 dynasty；后缀 -ikos（拉丁 -icus）衍生 dynastic 与 dynamic。"},"items":[{"word":"dynasthai","structure":"dynasthai (Greek verb, 'to have power')","meaning":"to have power","meaningCN":"拥有权力","example":"The root links rule to capacity.","exampleCN":"这个词根把统治与能力联系起来。"},{"word":"dynastes","structure":"dynasthai + -tes (agent noun)","meaning":"lord, ruler","meaningCN":"领主；统治者","example":"The dynastes held the estate by inheritance.","exampleCN":"领主凭继承持有这片产业。"},{"word":"dynasteia","structure":"dynastes + -eia (abstract noun)","meaning":"lordship, rule","meaningCN":"领主统治","example":"Lordship passed to the eldest son.","exampleCN":"领主之位传给长子。"},{"word":"-ikos","structure":"-ikos (Greek adjective suffix; Latin -icus)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns a noun into a relational adjective.","exampleCN":"这个后缀把名词转为关系形容词。"},{"word":"dynastic","structure":"dynasty + -ic","meaning":"of a ruling house","meaningCN":"统治家族的","example":"Dynastic marriage joined two crowns.","exampleCN":"王朝联姻连接两顶王冠。"},{"word":"dynasty","structure":"dynasteia, through Latin dynastia and French dynastie","meaning":"a ruling family line","meaningCN":"统治家族世系","example":"The dynasty ruled for centuries.","exampleCN":"这个王朝统治了数百年。"},{"word":"dynast","structure":"dynastes, through Latin dynasta","meaning":"a hereditary ruler","meaningCN":"世袭统治者","example":"The last dynast left no heir.","exampleCN":"最后一位世袭君主没有留下继承人。"},{"word":"dynastically","structure":"dynastic + -ally (adverb)","meaning":"in a dynastic way","meaningCN":"以王朝方式地","example":"The provinces were joined dynastically.","exampleCN":"这些行省通过王朝联姻被连在一起。"},{"word":"dynamic","structure":"Greek dynamis 'power' + -ikos","meaning":"full of force","meaningCN":"充满力量的","example":"The port grew into a dynamic market.","exampleCN":"这个港口发展成充满活力的市场。"}],"latinEntries":[{"word":"dynastia","structure":"dynastia, dynastiae (f., first declension)","meaning":"lordship, rule","meaningCN":"领主统治"},{"word":"dynastes","structure":"dynastes, dynastae (m., first declension)","meaning":"lord, ruler","meaningCN":"领主；统治者"},{"word":"dynasticus","structure":"dynasticus, dynastica, dynasticum (adjective, first and second declension)","meaning":"of a ruling house","meaningCN":"统治家族的"}]}},{"word":"monarch","ipa_uk":"/ˈmɒnək/","ipa_us":"/ˈmɑːnərk/","definition_zh":"君主；国王或女王；世袭的国家元首；帝王蛱蝶；某个领域里的霸主；某一方天地中最宏大者","definition_en":"a sole hereditary ruler such as a king or queen; also a large migratory butterfly and, figuratively, a dominant person or thing","core_image":"一顶王冠落在唯一的座位上，两侧的座椅都空着","scene":"礼仪厅里只有一张高背椅，椅背刻着王冠，两侧的座位都空着。The monarch opened the session with a short address from the throne.","sceneCN":"这里 monarch 指「唯一的世袭君主」（第 1 个义项：由一人继承国家元首之位）；句意为君主在御座上为会议作简短开幕致辞。可辨识物件：高背椅、王冠、空座位、御座、礼袍。","pos":[{"tag":"n.","zh":"君主；国王；女王；帝王蛱蝶；霸主"}],"collocations":[{"phrase":"a constitutional monarch","zh":"立宪君主"},{"phrase":"an absolute monarch","zh":"专制君主"},{"phrase":"the reigning monarch","zh":"在位的君主"},{"phrase":"monarch butterfly","zh":"帝王蛱蝶"},{"phrase":"a hereditary monarch","zh":"世袭君主"},{"phrase":"the monarch's residence","zh":"君主的居所"}],"forms":[{"label":"单数","form":"monarch"},{"label":"复数","form":"monarchs"},{"label":"阴性形式（女君主）","form":"monarchess"},{"label":"形容词（君主的）","form":"monarchic"},{"label":"形容词（君主制的）","form":"monarchical"},{"label":"名词（君主制）","form":"monarchy"}],"derivatives":[{"word":"monarchy","pos":"n.","zh":"monarch + -y（经拉丁 -ia、希腊 -ia 的状态后缀）→ 君主制，语义由人转为制度"},{"word":"monarchic","pos":"adj.","zh":"monarch + -ic（希腊 -ikos、拉丁 -icus 形容词后缀）→ 君主的、君主制的"},{"word":"monarchical","pos":"adj.","zh":"monarch + -ical（形容词后缀变体）→ 君主制的，与 monarchic 近义"},{"word":"monarchism","pos":"n.","zh":"monarch + -ism（主义后缀）→ 君主主义，主张保留君主制"},{"word":"monarchist","pos":"n./adj.","zh":"monarch + -ist（主张者后缀）→ 君主主义者；拥护君主制的"},{"word":"monarchess","pos":"n.","zh":"monarch + -ess（阴性后缀）→ 女君主（较少用）"}],"senses":[{"no":"01","title":"A sole hereditary ruler","titleCN":"唯一的世袭统治者","definition":"a king, queen or emperor who holds office by inheritance and stands alone at the head of the state","definitionCN":"凭继承取得职位、独自居于国家顶端的国王、女王或皇帝","example":"The monarch opened the session with a short address from the throne.","exampleCN":"君主在御座上为会议作了简短开幕致辞。","why":"Greek monarkhes joined monos 'alone' to arkhein 'rule', so the word begins with the idea of one person ruling.","whyCN":"希腊 monarkhes 把 monos「单独」与 arkhein「统治」结合，词的核心从一开始就是「一人统治」。"},{"no":"02","title":"A constitutional king or queen","titleCN":"立宪制下的国王或女王","definition":"a hereditary head of state whose powers are limited by a constitution and exercised through ministers","definitionCN":"世袭的国家元首，其权力受宪法限制、由大臣行使","example":"In a constitutional system the monarch reigns but does not rule.","exampleCN":"在立宪制度下，君主在位而不亲政。","why":"The title survived even when real power moved to parliament, so monarch now often means a ceremonial sovereign.","whyCN":"即使实权移入议会，称号仍保留，因此 monarch 如今常指礼仪性的元首。"},{"no":"03","title":"An absolute ruler","titleCN":"握有绝对权力的君主","definition":"a ruler who makes law and raises revenue without a representative body","definitionCN":"不经代议机构便立法与征税的统治者","example":"The monarch could raise taxes without consulting a council.","exampleCN":"这位君主无需咨询议事会便可加税。","why":"The original sense had no constitutional limit, and that older reading survives when historians discuss absolute rule.","whyCN":"原义并无宪法限制，史家讨论专制统治时保留的正是这一较早读法。"},{"no":"04","title":"A migratory orange butterfly","titleCN":"橙色的迁徙性帝王蛱蝶","definition":"a large orange-and-black butterfly, Danaus plexippus, famous for its long annual migration","definitionCN":"橙黑相间的大型蛱蝶，以每年长距离迁徙著称","example":"A monarch drifted south along the coast.","exampleCN":"一只帝王蛱蝶沿着海岸向南飘飞。","why":"Nineteenth-century naturalists called the most impressive local butterfly a monarch, borrowing the title of the grandest ruler.","whyCN":"十九世纪博物学者把当地最引人注目的蛱蝶称作君主，借用了最高统治者的称号。"},{"no":"05","title":"A dominant figure in a field","titleCN":"某一领域里的霸主","definition":"a person who dominates an activity or industry as though by royal authority","definitionCN":"像凭王权般支配某项活动或行业的人","example":"She was the monarch of the city's concert halls.","exampleCN":"她是这座城市音乐厅的霸主。","why":"The metaphor moves sole rule from a state to a social sphere, where one person sets the tone for everyone.","whyCN":"这一比喻把「一人统治」从国家移到社会领域，一个人便为所有人定调。"},{"no":"06","title":"The ruler of a small state","titleCN":"小邦的君主","definition":"a ruler of a small kingdom or princely state, especially in historical accounts","definitionCN":"小王国或土邦的统治者，尤见于历史记述","example":"The monarch of the island state kept his own coinage.","exampleCN":"这个岛国的君主保有自己的铸币权。","why":"Scale does not change the title: a ruler who holds sole hereditary power is a monarch whatever the size of the map.","whyCN":"规模不改变称号：只要独自掌握世袭权力，无论地图多小都是君主。"},{"no":"07","title":"A magnate compared to a king","titleCN":"被比作君王的巨头","definition":"a wealthy or powerful magnate described as ruling an industry like a king","definitionCN":"被形容为像国王一样统治某个行业的富有或有权势者","example":"The railway monarch travelled in a private carriage.","exampleCN":"这位铁路巨头乘坐私人车厢出行。","why":"Nineteenth-century newspapers nicknamed industry barons 'monarchs' because their decisions moved whole regions.","whyCN":"十九世纪报纸把产业大亨戏称为「君主」，因为他们的决定能牵动整片地区。"},{"no":"08","title":"The grandest thing of its kind","titleCN":"同类中最宏大者","definition":"the largest or most impressive example of a natural kind, imagined as ruling over the rest","definitionCN":"某一自然类别中最大或最壮观的个体，被想象为统辖其余","example":"The old oak was called the monarch of the wood.","exampleCN":"那棵老橡树被称为林中之王。","why":"The same habit that names the biggest butterfly also crowns the biggest tree, so monarch can mean simply the grandest member.","whyCN":"给最大蛱蝶命名的习惯也把最大的树加冕，因此 monarch 可仅指最宏大的那一个。"}],"etymology":{"intro":{"en":"Monarch comes through Latin and French from Greek monarkhes 'sole ruler', built on monos 'alone' and arkhein 'to rule'. Dates are approximate.","cn":"monarch 经拉丁与法语来自希腊 monarkhes「唯一统治者」，由 monos「单独」与 arkhein「统治」构成。年代均为约数。"},"items":[{"era":"GREEK MONOS","en":"Monos meant 'alone, single'; it is the same element found in monologue and monopoly.","cn":"monos 意为「单独、唯一」，与 monologue、monopoly 中的成分相同。"},{"era":"GREEK ARKHEIN","en":"Arkhein meant 'to begin, to rule'; its noun arkhe could mean both a starting point and an office of rule.","cn":"arkhein 意为「开始、统治」；其名词 arkhe 既可指起点，也可指统治职位。"},{"era":"GREEK MONARKHES","en":"Monos plus arkhein produced monarkhes, 'one who rules alone', the direct source of the English word.","cn":"monos 加 arkhein 构成 monarkhes「独自统治的人」，是英语该词的直接来源。"},{"era":"LATIN MONARCHA","en":"Latin monarcha kept the Greek meaning and passed it to French monarque and then to English.","cn":"拉丁 monarcha 保留了希腊含义，传给法语 monarque，再进入英语。"},{"era":"NATURALIST NAMES","en":"The butterfly name is a nineteenth-century naturalist borrowing, and the magnate and 'grandest tree' uses are journalistic extensions of the same image.","cn":"蝴蝶名是十九世纪博物学者的借用，巨头义与「林中最高大的树」义都是同一意象的报刊引申。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact first use of monarch for the butterfly is not established, and the naming motive, whether royal colour or size, is a matter of conjecture.","cn":"来源不确定（首见年代）：monarch 用于该蛱蝶的最早记录未有定论，命名动机是王室色彩还是体型，也属推测。"}]},"similar":{"note":{"en":"Group one holds forms from the same Greek pair or accidental neighbours; group two holds words for a sole ruler.","cn":"第一组是同出希腊组合或偶然相邻的形式；第二组是表示唯一统治者的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"monarchy","ipa":"/ˈmɒnəki/","tag":"same root, system","definition":"The system or state of rule by one monarch, from Greek monarkhia; monarch is the person.","definitionCN":"由一位君主统治的制度或国家，出自希腊 monarkhia；monarch 指人。"},{"word":"monarchic","ipa":"/məˈnɑːkɪk/","tag":"same root, adjective","definition":"The relational adjective 'of a monarch or monarchy'.","definitionCN":"「君主的、君主制的」关系形容词。"},{"word":"monastery","ipa":"/ˈmɒnəstri/","tag":"different root","definition":"From Greek monazein 'to live alone', but with no arkhein element: a community of monks, not a ruler.","definitionCN":"出自希腊 monazein「独居」，但无 arkhein 成分：是僧侣团体，不是统治者。"},{"word":"hierarchy","ipa":"/ˈhaɪərɑːki/","tag":"shared element","definition":"From hieros 'sacred' plus arkhein: rule by priests, later any ranked order. It shares the second element only.","definitionCN":"由 hieros「神圣」加 arkhein 构成：最初指祭司统治，后指任何等级秩序。只共享第二个成分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"king","ipa":"/kɪŋ/","tag":"royal title","definition":"The male ruler of a kingdom; a specific rank, while monarch is the general category.","definitionCN":"王国的男性统治者；是具体等级，而 monarch 是总类。"},{"word":"sovereign","ipa":"/ˈsɒvrɪn/","tag":"supreme authority","definition":"A ruler or state with supreme legal power; it stresses authority rather than heredity.","definitionCN":"握有最高法律权力的统治者或国家；强调权威而非世袭。"},{"word":"emperor","ipa":"/ˈempərə/","tag":"higher title","definition":"The ruler of an empire, traditionally ranked above a king; an emperor is a kind of monarch.","definitionCN":"帝国的统治者，传统等级高于国王；皇帝是君主的一种。"},{"word":"ruler","ipa":"/ˈruːlə/","tag":"generic","definition":"Anyone who governs, elected or not; the neutral word that need not imply a crown.","definitionCN":"任何治理者，无论是否经选举；是不必含王冠的中性词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"monos 'alone' + arkhein 'rule': one person rules.","cn":"monos「单独」+ arkhein「统治」：一个人统治。"},{"en":"The family runs monarch, monarchy, monarchic, monarchical, monarchist, monarchism.","cn":"同族词包括 monarch、monarchy、monarchic、monarchical、monarchist、monarchism。"},{"en":"Fixed phrases: constitutional monarch, absolute monarch, reigning monarch.","cn":"固定搭配：立宪君主、专制君主、在位君主。"},{"en":"The butterfly keeps the grand title, and so does the biggest tree in the wood.","cn":"蝴蝶保留了这个宏大称号，林中最大的树也一样。"},{"en":"monastery also starts with monos but has no arkhein, so it is not a relative.","cn":"monastery 也以 monos 开头，却没有 arkhein，因此并非同族词。"}],"abstract":[{"en":"Picture one chair in a hall full of empty chairs.","cn":"想象一间满是空椅的大厅里只坐着一张椅子。"},{"en":"Picture a butterfly carrying a tiny crown across a whole continent.","cn":"想象一只蝴蝶戴着小小的王冠飞越整块大陆。"},{"en":"Picture an old tree that the village treats as its ruler.","cn":"想象一棵老树，被全村当作君主。"}]},"examples":[{"en":"The monarch and the parliament disagreed over the new tax.","cn":"君主与议会就新税发生分歧。"},{"en":"Monarchs migrate thousands of kilometres every autumn.","cn":"帝王蛱蝶每年秋天迁徙数千公里。"},{"en":"In the trade, he was treated as a monarch whose word settled prices.","cn":"在这一行里，他被当作一句话就能定下价格的君主。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mono」单一 + 「arch」统治——一个人统治全场 → 君主","word":"monarch"},"root":"希腊 monarkhes「唯一统治者」= monos「单独」+ arkhein「统治」；经拉丁 monarcha、法语 monarque 入英语。英语 monarch。","sensesIntro":{"en":"Eight senses all rest on one seat: a single ruler, whether crowned by a constitution, by absolute power, by a magnate's fortune, or only by being the grandest thing in the wood.","cn":"八个义项都落在同一个座位上：唯一的统治者，无论是宪法所加冕、绝对权力所加冕、巨富所加冕，还是只因为它是林中最大者。"},"semanticMap":{"core":{"en":"CORE IMAGE: one throne in a hall of empty chairs.","cn":"核心意象：满是空椅的大厅里只有一张御座。"},"chain":["SOLE RULER","KING OR QUEEN","CONSTITUTIONAL SOVEREIGN","ABSOLUTE RULER","DOMINANT FIGURE","BORROWED GRANDEUR"],"branches":[{"senses":"S1","en":"THE SEAT: one person holds the office by inheritance.","cn":"座位：一人凭继承占据职位。"},{"senses":"S2 · S3","en":"TWO LIMITS: the same title covers a ceremonial sovereign and an unlimited autocrat.","cn":"两种界限：同一称号既指礼仪元首，也指不受限的专制者。"},{"senses":"S6","en":"SMALL MAP: size does not change the title of a sole hereditary ruler.","cn":"小地图：领土大小不改变唯一世袭统治者的称号。"},{"senses":"S5 · S7 · S8","en":"BORROWED GRANDEUR: a magnate, a butterfly or a great tree is crowned by metaphor.","cn":"借来的宏大：巨头、蝴蝶或大树都被比喻加冕。"},{"senses":"S4","en":"THE CREATURE: the most striking local butterfly takes the grandest name.","cn":"生物：当地最引人注目的蛱蝶取用了最宏大的名字。"}]},"affixes":{"intro":{"en":"Monarch is a two-morpheme Greek compound, and both halves recur in English words, so the family can be read morpheme by morpheme.","cn":"monarch 是双语素的希腊复合词，两半都在英语词中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Greek monos and arkhein give monarch, monarchy and monarchic; Latin monarcha and monarchia carried the forms westward.","cn":"希腊 monos 与 arkhein 衍生 monarch、monarchy 与 monarchic；拉丁 monarcha 与 monarchia 把这些形式向西传。"},"items":[{"word":"monos","structure":"monos (Greek adjective, 'alone, single')","meaning":"alone; single","meaningCN":"单独；唯一","example":"The element also appears in monologue.","exampleCN":"这个成分也出现在 monologue 中。"},{"word":"arkhein","structure":"arkhein (Greek verb, 'to begin, to rule')","meaning":"to rule; to begin","meaningCN":"统治；开始","example":"The root joins ruling to the idea of taking the lead.","exampleCN":"这个词根把统治与「领头」联系起来。"},{"word":"monarkhes","structure":"monos + arkhein + -es (agent)","meaning":"one who rules alone","meaningCN":"独自统治的人","example":"A monarkhes held the office by birth.","exampleCN":"唯一统治者凭出生取得职位。"},{"word":"-ia","structure":"-ia (Greek abstract-noun suffix)","meaning":"state or system","meaningCN":"状态或制度","example":"The suffix turns the ruler into the system of rule.","exampleCN":"这个后缀把统治者转为统治制度。"},{"word":"monarch","structure":"monarkhes, through Latin monarcha","meaning":"sole ruler","meaningCN":"唯一统治者","example":"The monarch opened the session.","exampleCN":"君主为会议开幕。"},{"word":"monarchy","structure":"monarch + -y (Greek -ia)","meaning":"rule by one monarch","meaningCN":"君主统治的制度","example":"The monarchy survived two republics.","exampleCN":"这个君主国挺过了两个共和国时期。"},{"word":"-ic","structure":"-ikos (Greek adjective suffix; Latin -icus)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix built monarchic from monarch.","exampleCN":"这个后缀由 monarch 构成 monarchic。"},{"word":"monarchic","structure":"monarch + -ic","meaning":"of a monarch","meaningCN":"君主的","example":"The monarchic title passed to the eldest son.","exampleCN":"君主称号传给了长子。"},{"word":"monarchist","structure":"monarch + -ist (supporter)","meaning":"a supporter of monarchy","meaningCN":"君主制的拥护者","example":"The monarchist opposed the referendum.","exampleCN":"这位君主主义者反对公投。"},{"word":"monastery","structure":"Greek monazein 'live alone' + -terion (place)","meaning":"a place of monks","meaningCN":"僧院","example":"The monastery stood above the valley.","exampleCN":"僧院坐落在山谷之上。"}],"latinEntries":[{"word":"monarcha","structure":"monarcha, monarchae (m., first declension)","meaning":"sole ruler","meaningCN":"唯一统治者"},{"word":"monarchia","structure":"monarchia, monarchiae (f., first declension)","meaning":"rule by one","meaningCN":"一人统治"},{"word":"monarchicus","structure":"monarchicus, monarchica, monarchicum (adjective, first and second declension)","meaning":"of a monarch","meaningCN":"君主的"}]}},{"word":"monarchy","ipa_uk":"/ˈmɒnəki/","ipa_us":"/ˈmɑːnərki/","definition_zh":"君主制；君主国；君主制度本身；某个王室家族；由单一力量支配的状态","definition_en":"a form of government in which one hereditary ruler holds the throne, the state so governed, and by extension any system dominated by a single authority","core_image":"一顶王冠放在宪法文本上，书页压住了权杖的下端","scene":"议会厅的陈列柜里，王冠搁在一本宪法上，权杖被书页压住一截。Constitutional monarchy keeps the crown but places the budget under parliament.","sceneCN":"这里 monarchy 指「由君主掌握国家元首之位的政体」（第 1 个义项：君主制这一政府形式）；句意为立宪君主制保留王冠，却把预算权交给议会。可辨识物件：陈列柜、王冠、宪法、权杖、议会席位。","pos":[{"tag":"n.","zh":"君主制；君主国；王室；单一支配的体系"}],"collocations":[{"phrase":"constitutional monarchy","zh":"君主立宪制"},{"phrase":"absolute monarchy","zh":"绝对君主制"},{"phrase":"a hereditary monarchy","zh":"世袭君主制"},{"phrase":"the British monarchy","zh":"英国王室"},{"phrase":"abolish the monarchy","zh":"废除君主制"},{"phrase":"restore the monarchy","zh":"恢复君主制"}],"forms":[{"label":"单数","form":"monarchy"},{"label":"复数","form":"monarchies"},{"label":"名词（君主）","form":"monarch"},{"label":"形容词（君主制的）","form":"monarchic"},{"label":"形容词（君主制的）","form":"monarchical"},{"label":"名词（君主主义者）","form":"monarchist"}],"derivatives":[{"word":"monarch","pos":"n.","zh":"monarchy 去掉 -y 回溯到希腊 monarkhes → 君主，语义由制度转为人"},{"word":"monarchic","pos":"adj.","zh":"monarch + -ic（希腊 -ikos）→ 君主制的"},{"word":"monarchical","pos":"adj.","zh":"monarch + -ical（形容词后缀变体）→ 君主制的，语气更正式"},{"word":"monarchism","pos":"n.","zh":"monarch + -ism（主义后缀）→ 君主主义，语义由制度转为主张"},{"word":"monarchist","pos":"n./adj.","zh":"monarch + -ist（主张者后缀）→ 君主主义者"},{"word":"anti-monarchist","pos":"n./adj.","zh":"anti-（反对前缀）+ monarchist → 反君主主义者"}],"senses":[{"no":"01","title":"Government by a single hereditary ruler","titleCN":"由一位世袭君主执政的政体","definition":"a form of government in which one person holds the throne by inheritance","definitionCN":"由一人凭继承占据王位的政府形式","example":"Constitutional monarchy keeps the crown but places the budget under parliament.","exampleCN":"君主立宪制保留王冠，却把预算权交给议会。","why":"Greek monarkhia named the rule of one person, and English kept it as the name of a constitutional form.","whyCN":"希腊 monarkhia 本指一人统治，英语把它保留为一种宪政形式的名称。"},{"no":"02","title":"A state ruled by a monarch","titleCN":"由君主统治的国家","definition":"a country whose head of state is a king, queen or emperor","definitionCN":"以国王、女王或皇帝为国家元首的国家","example":"The monarchy survived two republics before it fell.","exampleCN":"这个君主国挺过了两个共和国时期才覆灭。","why":"Metonymy let the form of government stand for the country that uses it, as in 'a constitutional monarchy'.","whyCN":"转喻让政体之名代表采用它的国家，如「一个君主立宪国」。"},{"no":"03","title":"The institution of royal rule","titleCN":"王室统治这一制度","definition":"the enduring institution of the crown, apart from any one ruler or country","definitionCN":"王权这一长期存在的制度，独立于任何具体君主或国家","example":"The monarchy as an institution lost its landed revenue.","exampleCN":"作为制度的君主制失去了地产收入。","why":"Institutions outlast individuals, so the word can name the arrangement rather than the person or the state.","whyCN":"制度比个人长寿，因此这个词可指安排本身，而非人或国家。"},{"no":"04","title":"A particular royal family","titleCN":"某个具体的王室家族","definition":"the royal house of a country, considered as a family and a public body","definitionCN":"一国的王室家族，被视为家族与公共机构","example":"The British monarchy has narrowed its public role.","exampleCN":"英国王室已缩小了其公共角色。","why":"Journalists use the word for the family in the palace, since the household is the visible face of the institution.","whyCN":"记者用这个词指宫殿里的家族，因为王室家庭是这一制度可见的面孔。"},{"no":"05","title":"Rule without constitutional limit","titleCN":"不受宪法限制的君主统治","definition":"a system in which the monarch's power is not limited by law or parliament","definitionCN":"君主的权力不受法律或议会限制的制度","example":"Absolute monarchy left no room for a parliament.","exampleCN":"绝对君主制没有给议会留下空间。","why":"The compound 'absolute monarchy' marks the older, unlimited reading of the word.","whyCN":"「绝对君主制」这一复合词标出了该词较早的、不受限的读法。"},{"no":"06","title":"Rule limited by a constitution","titleCN":"受宪法约束的君主制","definition":"a system in which the monarch reigns within constitutional limits and ministers govern","definitionCN":"君主在宪法限度内临朝、由大臣治理的制度","example":"Constitutional monarchy made the crown ceremonial.","exampleCN":"君主立宪制使王冠变为礼仪性的。","why":"The compound marks the modern settlement in which the title survives but power does not.","whyCN":"这一复合词标出现代安排：称号保留，权力不留。"},{"no":"07","title":"Dominance by one power in a field","titleCN":"某一领域由单一力量支配","definition":"a situation in which one firm or group rules an activity as a monarch rules a state","definitionCN":"一家公司或团体像君主统治国家般支配某项活动的情形","example":"A handful of firms held a monarchy over the coffee trade.","exampleCN":"少数几家公司对咖啡贸易形成了君主式的支配。","why":"The political image is borrowed for markets where one player sets terms for all the rest.","whyCN":"这一政治意象被借到市场上：一个玩家为其余所有人定条件。"},{"no":"08","title":"The period of royal rule","titleCN":"君主统治的时期","definition":"the span of time during which a country was governed as a monarchy","definitionCN":"一个国家作为君主国被治理的那段时期","example":"Many of the palaces were built during the monarchy.","exampleCN":"许多宫殿建于君主制时期。","why":"As with empire, the name of the system can stand for the years it lasted.","whyCN":"与 empire 一样，制度之名可以代表它延续的岁月。"}],"etymology":{"intro":{"en":"Monarchy comes through Latin monarchia from Greek monarkhia 'rule of one', built on monos 'alone' and arkhein 'to rule'. Dates are approximate.","cn":"monarchy 经拉丁 monarchia 来自希腊 monarkhia「一人统治」，由 monos「单独」与 arkhein「统治」构成。年代均为约数。"},"items":[{"era":"GREEK MONOS","en":"Monos 'alone, single' supplies the first element, the same one seen in monologue and monopoly.","cn":"monos「单独、唯一」提供第一个成分，与 monologue、monopoly 中的相同。"},{"era":"GREEK ARKHEIN","en":"Arkhein 'to rule, to begin' supplies the second element; its noun arkhe covers both a start and an office.","cn":"arkhein「统治、开始」提供第二个成分；其名词 arkhe 兼指起点与职位。"},{"era":"GREEK MONARKHIA","en":"The abstract noun monarkhia named the rule of one person, as opposed to oligarchy or democracy.","cn":"抽象名词 monarkhia 指一人统治，与寡头制或民主制相对。"},{"era":"LATIN AND FRENCH","en":"Latin monarchia and French monarchie carried the word to English by the fourteenth century.","cn":"拉丁 monarchia 与法语 monarchie 在十四世纪前把这个词带入英语。"},{"era":"CONSTITUTIONAL SPLIT","en":"From the seventeenth century English writers distinguished absolute from constitutional monarchy, and both compounds became standard.","cn":"自十七世纪起，英语作者区分绝对君主制与君主立宪制，两个复合词都成为标准说法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact first English citation is not established, and the extension to firms and markets has no single documented origin.","cn":"来源不确定（首见年代）：确切的最早英语书证未有定论，向公司与市场的引申也没有唯一可考来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same Greek compound or words sharing one element; group two holds names of governing systems.","cn":"第一组是同出该希腊复合词或共享一个成分的词；第二组是各种政体名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"monarch","ipa":"/ˈmɒnək/","tag":"same root, person","definition":"The ruler himself or herself; monarchy is the office, system or state.","definitionCN":"统治者本人；monarchy 指职位、制度或国家。"},{"word":"monarchic","ipa":"/məˈnɑːkɪk/","tag":"same root, adjective","definition":"The relational adjective, meaning 'of a monarch or of monarchy'.","definitionCN":"关系形容词，意为「君主的、君主制的」。"},{"word":"monarchical","ipa":"/məˈnɑːkɪkl/","tag":"adjective variant","definition":"A longer variant of the same adjective, now more common in political writing.","definitionCN":"同一形容词的较长变体，如今在政治写作中更常见。"},{"word":"hierarchy","ipa":"/ˈhaɪərɑːki/","tag":"shared element","definition":"From hieros 'sacred' plus arkhein: rule by priests, later any ranked order. It shares only the second element.","definitionCN":"由 hieros「神圣」加 arkhein 构成：最初指祭司统治，后指任何等级秩序。只共享第二个成分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"kingdom","ipa":"/ˈkɪŋdəm/","tag":"realm","definition":"The territory or state ruled by a king or queen; it names the country, while monarchy names the system.","definitionCN":"由国王或女王统治的领土或国家；指国家，而 monarchy 指制度。"},{"word":"principality","ipa":"/ˌprɪnsɪˈpæləti/","tag":"small state","definition":"A small state ruled by a prince; it is a species of monarchy with a lower title.","definitionCN":"由亲王统治的小国；是君主制的一种，称号较低。"},{"word":"autocracy","ipa":"/ɔːˈtɒkrəsi/","tag":"unlimited rule","definition":"Rule by one person with no constitutional limit; it stresses the absence of checks rather than heredity.","definitionCN":"一人不受宪法限制的统治；强调缺乏制约，而非世袭。"},{"word":"republic","ipa":"/rɪˈpʌblɪk/","tag":"opposite system","definition":"A state whose head is chosen rather than inherited; it is the usual contrast to monarchy.","definitionCN":"元首经选择而非继承的国家；是君主制通常的对立面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"monos 'alone' + arkhein 'rule' + -ia 'system': the system of one ruler.","cn":"monos「单独」+ arkhein「统治」+ -ia「制度」：一人统治的制度。"},{"en":"The family runs monarchy, monarch, monarchic, monarchical, monarchist.","cn":"同族词包括 monarchy、monarch、monarchic、monarchical、monarchist。"},{"en":"Two fixed compounds split the field: absolute monarchy and constitutional monarchy.","cn":"两个固定复合词划出领域：绝对君主制与君主立宪制。"},{"en":"A republic is the usual contrast, since its head is chosen rather than inherited.","cn":"共和国是通常的对照，因为其元首经选择而非继承。"},{"en":"Journalists say 'the British monarchy' when they mean the royal family.","cn":"记者说「英国王室」时，指的就是那个王室家族。"}],"abstract":[{"en":"Picture a crown resting on a constitution as if pinned in place.","cn":"想象一顶王冠放在宪法上，像被压住一样。"},{"en":"Picture a throne that has outlived every person who sat in it.","cn":"想象一张御座比所有坐过它的人都活得久。"},{"en":"Picture one café chain setting the price for every other café on the street.","cn":"想象一家连锁咖啡馆替整条街的咖啡馆定价。"}]},"examples":[{"en":"The country moved from absolute monarchy to a limited one in a single century.","cn":"这个国家在一个世纪内从绝对君主制转为有限君主制。"},{"en":"Support for the monarchy fell after the war.","cn":"战后民众对君主制的支持下降。"},{"en":"The constitution defines the monarchy without naming the present king.","cn":"宪法界定了君主制，却没有写出在任国王的名字。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mono」单一 + 「archy」统治——一个人统治的制度 → 君主制","word":"monarchy"},"root":"希腊 monarkhia「一人统治」= monos「单独」+ arkhein「统治」+ -ia（抽象名词后缀）；经拉丁 monarchia、法语 monarchie 入英语。英语 monarchy。","sensesIntro":{"en":"Eight senses follow one system: rule by one person. It can be read as a form, a state, an institution, a family, two constitutional variants, a market habit and a stretch of years.","cn":"八个义项沿同一种制度展开：一人统治。它可被读作形式、国家、制度、家族、两种宪政变体、市场习性与一段岁月。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crown resting on a constitution, with a sceptre pinned under the pages.","cn":"核心意象：王冠放在宪法上，权杖被书页压住。"},"chain":["ONE RULER","FORM OF GOVERNMENT","STATE","INSTITUTION","ROYAL FAMILY","CEREMONIAL CROWN"],"branches":[{"senses":"S1 · S2","en":"FORM AND COUNTRY: the arrangement and the nation that adopts it share one name.","cn":"制度与国家：安排本身与采用它的国家共享一名。"},{"senses":"S3","en":"THE INSTITUTION: the crown as a lasting body, not a person.","cn":"制度：王冠作为持久的机构，而非个人。"},{"senses":"S4","en":"THE FAMILY: the household in the palace is the visible face of the system.","cn":"家族：宫殿里的家族是该制度可见的面孔。"},{"senses":"S5 · S6","en":"TWO CONSTITUTIONS: unlimited rule and ceremonial rule are rival readings of one word.","cn":"两种宪制：不受限统治与礼仪统治是同一个词的两种读法。"},{"senses":"S7 · S8","en":"THE IMITATION AND THE YEARS: a market can be ruled like a state, and a system's name can mark its era.","cn":"模仿与岁月：市场可像国家一样被统治，制度之名也能标记其时代。"}]},"affixes":{"intro":{"en":"Monarchy is a Greek compound plus an abstract suffix, and all three parts recur in English, so the family can be read morpheme by morpheme.","cn":"monarchy 是希腊复合词加抽象后缀，三部分都在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Greek monos, arkhein and -ia give monarchy; Latin monarchia and French monarchie carried the form into English.","cn":"希腊 monos、arkhein 与 -ia 构成 monarchy；拉丁 monarchia 与法语 monarchie 把该形式带入英语。"},"items":[{"word":"monos","structure":"monos (Greek adjective, 'alone, single')","meaning":"alone; single","meaningCN":"单独；唯一","example":"The element also appears in monopoly.","exampleCN":"这个成分也出现在 monopoly 中。"},{"word":"arkhein","structure":"arkhein (Greek verb, 'to rule, to begin')","meaning":"to rule","meaningCN":"统治","example":"The root links rule to taking the lead.","exampleCN":"这个词根把统治与领头联系起来。"},{"word":"-ia","structure":"-ia (Greek abstract-noun suffix)","meaning":"state, system","meaningCN":"状态；制度","example":"The suffix turns a ruler into a system of rule.","exampleCN":"这个后缀把统治者转为统治制度。"},{"word":"monarkhia","structure":"monos + arkhein + -ia","meaning":"rule by one","meaningCN":"一人统治","example":"Monarkhia was contrasted with oligarchy.","exampleCN":"一人统治与寡头制相对照。"},{"word":"monarchy","structure":"monarkhia, through Latin monarchia","meaning":"rule by a monarch","meaningCN":"君主统治","example":"The monarchy survived two republics.","exampleCN":"这个君主国挺过了两个共和国时期。"},{"word":"monarch","structure":"monarkhes, through Latin monarcha","meaning":"sole ruler","meaningCN":"唯一统治者","example":"The monarch opened the session.","exampleCN":"君主为会议开幕。"},{"word":"-ic","structure":"-ikos (Greek adjective suffix; Latin -icus)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix built monarchic from monarch.","exampleCN":"这个后缀由 monarch 构成 monarchic。"},{"word":"monarchical","structure":"monarch + -ical (adjective variant)","meaning":"of monarchy","meaningCN":"君主制的","example":"The monarchical system lasted longer than the empire.","exampleCN":"君主制体系比帝国延续更久。"},{"word":"monarchist","structure":"monarch + -ist (supporter)","meaning":"supporter of monarchy","meaningCN":"君主制拥护者","example":"The monarchist opposed the referendum.","exampleCN":"这位君主主义者反对公投。"},{"word":"hierarchy","structure":"Greek hieros 'sacred' + arkhein","meaning":"rule by priests, later ranked order","meaningCN":"祭司统治，后指等级秩序","example":"The hierarchy of the church was strict.","exampleCN":"教会的等级秩序很严格。"}],"latinEntries":[{"word":"monarchia","structure":"monarchia, monarchiae (f., first declension)","meaning":"rule by one","meaningCN":"一人统治"},{"word":"monarcha","structure":"monarcha, monarchae (m., first declension)","meaning":"sole ruler","meaningCN":"唯一统治者"},{"word":"monarchicus","structure":"monarchicus, monarchica, monarchicum (adjective, first and second declension)","meaning":"of a monarch","meaningCN":"君主的"}]}},{"word":"monarchic","ipa_uk":"/məˈnɑːkɪk/","ipa_us":"/məˈnɑːrkɪk/","definition_zh":"君主的；君主制的；拥护君主制的；君主般专断的；以一人为顶点的","definition_en":"relating to a monarch or to monarchy; favouring royal rule; or resembling a monarch in manner and structure","core_image":"一份组织图的最上方只画着一个王冠，下面的线全部汇到这一点","scene":"会议室的白板上画着一张架构图，最上方只有一个圆圈，底下所有箭头都汇向它。The board's monarchic structure gave one chair the final word on every budget.","sceneCN":"这里 monarchic 指「以一人为顶点、像君主制那样组织的」（第 5 个义项：单一首脑结构）；句意为董事会的君主式结构让一把椅子对每项预算拥有最终决定权。可辨识物件：白板、架构图、圆圈、箭头、椅子。","pos":[{"tag":"adj.","zh":"君主的；君主制的；拥护君主制的；专断的"}],"collocations":[{"phrase":"monarchic system","zh":"君主制体系"},{"phrase":"monarchic rule","zh":"君主统治"},{"phrase":"monarchic party","zh":"拥护君主制的政党"},{"phrase":"monarchic structure","zh":"单一首脑的结构"},{"phrase":"monarchic tendencies","zh":"君主制倾向"},{"phrase":"monarchic authority","zh":"君主式权威"}],"forms":[{"label":"原级","form":"monarchic"},{"label":"比较级","form":"more monarchic"},{"label":"最高级","form":"most monarchic"},{"label":"变体形容词","form":"monarchical"},{"label":"副词","form":"monarchically"},{"label":"名词（君主制）","form":"monarchy"}],"derivatives":[{"word":"monarchically","pos":"adv.","zh":"monarchic + -ally（副词后缀）→ 以君主方式地"},{"word":"monarchical","pos":"adj.","zh":"monarchic 的 -ical 变体，语义相同而语体更正式"},{"word":"monarchism","pos":"n.","zh":"monarch + -ism（主义后缀）→ 君主主义，由形容词转为政治主张"},{"word":"monarchist","pos":"n./adj.","zh":"monarch + -ist（主张者后缀）→ 君主主义者"},{"word":"monarchy","pos":"n.","zh":"monarch + -y（状态后缀）→ 君主制，由属性转回制度"},{"word":"monarch","pos":"n.","zh":"希腊 monarkhes 经拉丁 → 君主，为整个词族的人称基础"}],"senses":[{"no":"01","title":"Relating to a monarch","titleCN":"与君主本人相关的","definition":"belonging to the person of a king, queen or emperor","definitionCN":"属于国王、女王或皇帝本人的","example":"The monarchic title passed to the eldest son.","exampleCN":"君主称号传给了长子。","why":"The suffix -ic makes a relational adjective, so the word simply means 'of a monarch' at its base.","whyCN":"后缀 -ic 构成关系形容词，因此这个词最基本的意思就是「君主的」。"},{"no":"02","title":"Relating to monarchy as a system","titleCN":"与君主制这一制度相关的","definition":"describing the institutions and practices of rule by a hereditary head of state","definitionCN":"描述由世袭元首统治的制度与实践","example":"Monarchic government survived in a few small states.","exampleCN":"君主制政府在少数小国中留存下来。","why":"Because the adjective can modify 'government' or 'system', it extends from the person to the whole arrangement.","whyCN":"因为这个形容词可修饰「政府」或「体系」，便从人扩展到整套安排。"},{"no":"03","title":"Favouring royal rule","titleCN":"拥护君主制的","definition":"supporting the restoration or preservation of a monarchy","definitionCN":"支持恢复或保留君主制","example":"The monarchic party opposed the referendum.","exampleCN":"拥护君主制的政党反对这次公投。","why":"A political adjective often names a stance rather than a fact, so monarchic can mean 'on the side of the crown'.","whyCN":"政治形容词常命名立场而非事实，因此 monarchic 可指「站在王冠一边」。"},{"no":"04","title":"Characteristic of a monarch's manner","titleCN":"具有君主作风的","definition":"showing the assurance, distance or dignity associated with a ruler","definitionCN":"表现出与统治者相关的笃定、距离感或威仪","example":"He spoke with a monarchic assurance that ended debate.","exampleCN":"他带着君主般的笃定说话，终止了辩论。","why":"The adjective moves from office to temperament, so an unelected chair can sound monarchic.","whyCN":"这个形容词从职位移到性情，因此一位非经选举的主席也能显得像君主。"},{"no":"05","title":"Structured with one person at the top","titleCN":"以一人为顶点的结构","definition":"organised so that a single person holds final authority over everyone else","definitionCN":"组织方式使一人对其余所有人握有最终权威","example":"The board's monarchic structure gave one chair the final word on every budget.","exampleCN":"董事会的君主式结构让一把椅子对每项预算拥有最终决定权。","why":"The political shape is applied to an organisation, where one signature can override a whole committee.","whyCN":"政治形态被套用到组织上，一个签名便可压倒整个委员会。"},{"no":"06","title":"Of a state with a crowned head","titleCN":"以君主为国家元首的","definition":"describing a country whose head of state holds a royal title","definitionCN":"描述元首拥有王室称号的国家","example":"Monarchic states dominated the peninsula for centuries.","exampleCN":"君主制国家曾支配这个半岛数百年。","why":"The adjective attaches to the state as well as to the office, since a country can be described by its constitutional form.","whyCN":"这个形容词也修饰国家，因为一国可由其宪制形式来描述。"},{"no":"07","title":"Domineering in personal habit","titleCN":"作风专断的","definition":"acting as though one's word cannot be questioned, like an absolute ruler","definitionCN":"行事仿佛自己的话不容置疑，像绝对统治者","example":"Her monarchic habits alienated the staff.","exampleCN":"她专断的作风让员工疏远了她。","why":"The critical use turns the adjective from description into reproach: a small tyrant in an office.","whyCN":"批评性用法把这个形容词从描述变为责备：办公室里的一个小暴君。"},{"no":"08","title":"Of a particular royal era","titleCN":"某个君主统治时代的","definition":"describing a historical period governed by a monarch or a royal regime","definitionCN":"描述由君主或王室政权统治的历史时期","example":"Monarchic France collapsed in the revolution.","exampleCN":"君主制的法国在大革命中崩溃。","why":"Historians use the adjective to label a regime and its era, just as they use dynastic for a ruling house.","whyCN":"史家用这个形容词标记政权及其时代，正如用 dynastic 标记统治家族。"}],"etymology":{"intro":{"en":"Monarchic is the Greek adjective monarkhikos, built on monarkhes 'sole ruler' with the suffix -ikos, which Latin reshaped as -icus. Dates are approximate.","cn":"monarchic 是希腊形容词 monarkhikos，由 monarkhes「唯一统治者」加后缀 -ikos 构成，拉丁语把它改造为 -icus。年代均为约数。"},"items":[{"era":"GREEK MONOS","en":"Monos 'alone' supplies the first element of the compound, as in monologue and monopoly.","cn":"monos「单独」提供复合词的第一个成分，与 monologue、monopoly 相同。"},{"era":"GREEK ARKHEIN","en":"Arkhein 'to rule' supplies the second element, shared with hierarchy though the prefixes differ.","cn":"arkhein「统治」提供第二个成分，与 hierarchy 共享，但前缀不同。"},{"era":"GREEK MONARKHIKOS","en":"The adjective monarkhikos meant 'of a sole ruler' or 'fit for a ruler'.","cn":"形容词 monarkhikos 意为「唯一统治者的」或「适合统治者的」。"},{"era":"LATIN -ICUS","en":"Latin reshaped Greek -ikos as -icus, the standard relational suffix that English later reduced to -ic.","cn":"拉丁把希腊 -ikos 改造为 -icus，这是标准的关系后缀，英语后来简化为 -ic。"},{"era":"ENGLISH USE","en":"English adopted the adjective beside monarchy and monarch, and later extended it to organisations and personal manner.","cn":"英语在 monarchy 与 monarch 旁采纳了这个形容词，后来又扩展到组织与个人作风。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English citation is not recorded precisely, and the organisational sense has no single documented origin.","cn":"来源不确定（首见年代）：最早的英语书证并不确切，组织义也没有唯一可考来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same compound or a shared element; group two holds adjectives describing rule by one person.","cn":"第一组是同出该复合词或共享成分的形式；第二组是描述一人统治的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"monarchical","ipa":"/məˈnɑːkɪkl/","tag":"variant","definition":"The -ical variant of the same adjective, now the more usual form in political prose.","definitionCN":"同一形容词的 -ical 变体，如今在政治文章中更常用。"},{"word":"monarch","ipa":"/ˈmɒnək/","tag":"same root, person","definition":"The ruler; monarchic is the adjective derived from this person.","definitionCN":"统治者；monarchic 是由这个人称派生的形容词。"},{"word":"monarchy","ipa":"/ˈmɒnəki/","tag":"same root, system","definition":"The system or state of rule by one; the adjective can modify either this system or its ruler.","definitionCN":"一人统治的制度或国家；该形容词既可修饰制度也可修饰君主。"},{"word":"monastery","ipa":"/ˈmɒnəstri/","tag":"different root","definition":"From monazein 'live alone', with no arkhein element: a monastic house, not a political form.","definitionCN":"出自 monazein「独居」，无 arkhein 成分：是僧院，不是政治形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"royal","ipa":"/ˈrɔɪəl/","tag":"of a king","definition":"Belonging to a king or queen; it names the rank, while monarchic names the constitutional type.","definitionCN":"属于国王或女王；指等级，而 monarchic 指宪制类型。"},{"word":"autocratic","ipa":"/ˌɔːtəˈkrætɪk/","tag":"unlimited","definition":"Ruling without constitutional checks; it stresses unlimited power rather than inheritance.","definitionCN":"不受宪法制约地统治；强调无限权力而非世袭。"},{"word":"despotic","ipa":"/dɪˈspɒtɪk/","tag":"tyrannical","definition":"Ruling with arbitrary cruelty; a strongly negative word that monarchic does not always carry.","definitionCN":"专横残暴地统治；贬义很强，而 monarchic 未必带有这层。"},{"word":"hierarchical","ipa":"/ˌhaɪəˈrɑːkɪkl/","tag":"ranked","definition":"Arranged in ranks; it shares the arkhein element but describes any ladder, not one crown.","definitionCN":"按等级排列；共享 arkhein 成分，但描述任何阶梯，而非一顶王冠。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"monarch + -ic: the adjective of one-person rule.","cn":"monarch + -ic：一人统治的形容词。"},{"en":"The family runs monarchic, monarchical, monarchically, monarch, monarchy, monarchist.","cn":"同族词包括 monarchic、monarchical、monarchically、monarch、monarchy、monarchist。"},{"en":"Fixed phrases: monarchic system, monarchic party, monarchic structure.","cn":"固定搭配：君主制体系、拥护君主制的政党、单一首脑结构。"},{"en":"hierarchy shares arkhein but adds hieros 'sacred', so it is a cousin, not a twin.","cn":"hierarchy 共享 arkhein，却加了 hieros「神圣」，因此是表亲而非孪生。"},{"en":"The adjective easily slips from describing a state to criticising a boss.","cn":"这个形容词很容易从描述国家滑向批评上司。"}],"abstract":[{"en":"Picture an org chart with a crown at the top and no second box.","cn":"想象一张架构图，顶端是王冠，下面没有第二个框。"},{"en":"Picture a committee where only one pen can sign.","cn":"想象一个委员会，只有一支笔能签字。"},{"en":"Picture a meeting where everyone waits for one person to nod.","cn":"想象一场会议，所有人都等一个人点头。"}]},"examples":[{"en":"The monarchic regime lasted until the constitution was rewritten.","cn":"这个君主制政权一直延续到宪法被重写。"},{"en":"His monarchic gestures made the committee feel like a court.","cn":"他君主般的姿态让委员会像一座宫廷。"},{"en":"The report criticised the monarchic concentration of power in one office.","cn":"报告批评权力君主式地集中在一个办公室。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「monarch」君主 + 「ic」的——君主式的、君主制的","word":"monarchic"},"root":"希腊 monarkhikos「君主的」= monarkhes「唯一统治者」+ -ikos（形容词后缀，拉丁作 -icus）；monarkhes 出自 monos「单独」+ arkhein「统治」。英语 monarchic。","sensesIntro":{"en":"Eight senses apply one adjective to a person, a system, a political stance, a manner, an org chart, a state, a domineering habit and a historical era.","cn":"八个义项把同一个形容词用到人、制度、政治立场、作风、组织图、国家、专断习性与一个历史时代上。"},"semanticMap":{"core":{"en":"CORE IMAGE: an org chart whose top box is a crown and whose every arrow converges on it.","cn":"核心意象：一张架构图，顶端方框是王冠，所有箭头都汇向它。"},"chain":["MONARCH","MONARCHY","SYSTEM","POLITICAL STANCE","PERSONAL MANNER","DOMINEERING HABIT"],"branches":[{"senses":"S1 · S4","en":"THE PERSON: the ruler and the ruler-like manner share one adjective.","cn":"人：统治者与类似统治者的作风共享一个形容词。"},{"senses":"S2 · S6 · S8","en":"THE SYSTEM: a form of government, a state that uses it and the era it marks.","cn":"制度：政府形式、采用它的国家，以及它所标记的时代。"},{"senses":"S3","en":"THE STANCE: to be monarchic is to take the crown's side in a debate.","cn":"立场：持 monarchic 立场就是在辩论中站在王冠一边。"},{"senses":"S5","en":"THE ORG CHART: one signature outweighs a whole committee.","cn":"组织图：一个签名重于整个委员会。"},{"senses":"S7","en":"THE HABIT: a small tyrant can reign inside an office.","cn":"习性：小暴君也能在办公室里临朝。"}]},"affixes":{"intro":{"en":"Monarchic is a Greek compound plus the adjective suffix -ikos, and all three parts recur in English, so the family can be read morpheme by morpheme.","cn":"monarchic 是希腊复合词加形容词后缀 -ikos，三部分都在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Greek monos and arkhein give monarch and monarchy; -ikos, Latin -icus, gives monarchic and hierarchical.","cn":"希腊 monos 与 arkhein 衍生 monarch 与 monarchy；-ikos（拉丁 -icus）衍生 monarchic 与 hierarchical。"},"items":[{"word":"monos","structure":"monos (Greek adjective, 'alone, single')","meaning":"alone; single","meaningCN":"单独；唯一","example":"The element also appears in monologue.","exampleCN":"这个成分也出现在 monologue 中。"},{"word":"arkhein","structure":"arkhein (Greek verb, 'to rule, to begin')","meaning":"to rule","meaningCN":"统治","example":"The root links rule to taking the lead.","exampleCN":"这个词根把统治与领头联系起来。"},{"word":"monarkhes","structure":"monos + arkhein + -es (agent)","meaning":"one who rules alone","meaningCN":"独自统治的人","example":"A monarkhes held the throne by birth.","exampleCN":"唯一统治者凭出生取得王位。"},{"word":"-ikos","structure":"-ikos (Greek adjective suffix; Latin -icus)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns a ruler into an adjective.","exampleCN":"这个后缀把统治者转为形容词。"},{"word":"monarchic","structure":"monarkhes + -ikos","meaning":"of a sole ruler","meaningCN":"唯一统治者的","example":"The monarchic title passed to the son.","exampleCN":"君主称号传给了儿子。"},{"word":"monarchical","structure":"monarchic + -al (variant ending)","meaning":"of monarchy","meaningCN":"君主制的","example":"The monarchical system endured.","exampleCN":"君主制体系延续下来。"},{"word":"monarchically","structure":"monarchic + -ally (adverb)","meaning":"in a monarchic way","meaningCN":"以君主方式地","example":"He ruled monarchically over the department.","exampleCN":"他像君主一样统治这个部门。"},{"word":"monarchy","structure":"monarkhia, through Latin monarchia","meaning":"rule by one","meaningCN":"一人统治","example":"The monarchy fell after the war.","exampleCN":"战后君主制倾覆。"},{"word":"monarch","structure":"monarkhes, through Latin monarcha","meaning":"sole ruler","meaningCN":"唯一统治者","example":"The monarch spoke briefly.","exampleCN":"君主简短地讲了话。"},{"word":"hierarchy","structure":"Greek hieros 'sacred' + arkhein","meaning":"rule by priests, later ranked order","meaningCN":"祭司统治，后指等级秩序","example":"The hierarchy was rigid.","exampleCN":"等级秩序很僵化。"}],"latinEntries":[{"word":"monarchicus","structure":"monarchicus, monarchica, monarchicum (adjective, first and second declension)","meaning":"of a monarch","meaningCN":"君主的"},{"word":"monarcha","structure":"monarcha, monarchae (m., first declension)","meaning":"sole ruler","meaningCN":"唯一统治者"},{"word":"monarchia","structure":"monarchia, monarchiae (f., first declension)","meaning":"rule by one","meaningCN":"一人统治"}]}},{"word":"sovereignty","ipa_uk":"/ˈsɒvrənti/","ipa_us":"/ˈsɑːvrənti/","definition_zh":"主权；国家握有的最高权力；主权国家的地位；对某片领土的管辖权；个人自主；神对历史的支配","definition_en":"supreme authority within a state, the status of being an independent state, jurisdiction over territory, and by extension personal autonomy or divine rule","core_image":"一把钥匙插在国界碑的锁孔里，钥匙柄铸成王冠的形状","scene":"国界碑旁的石台上放着一把钥匙，钥匙柄铸成王冠形状，两侧的哨兵站得笔直。The treaty recognised the new state's sovereignty over the whole valley.","sceneCN":"这里 sovereignty 指「国家握有的最高权力」（第 1 个义项：对内最高、对外不受支配的统治权）；句意为条约承认这个新国家对整个山谷拥有主权。可辨识物件：国界碑、钥匙、王冠形钥匙柄、哨兵、条约文本。","pos":[{"tag":"n.","zh":"主权；最高统治权；主权国家地位；个人自主（多作不可数）"}],"collocations":[{"phrase":"national sovereignty","zh":"国家主权"},{"phrase":"territorial sovereignty","zh":"领土主权"},{"phrase":"sovereignty over the islands","zh":"对这些岛屿的主权"},{"phrase":"a claim to sovereignty","zh":"主权主张"},{"phrase":"transfer sovereignty","zh":"移交主权"},{"phrase":"food sovereignty","zh":"粮食主权"}],"forms":[{"label":"通常形式（不可数）","form":"sovereignty"},{"label":"复数（指多项主权，较少用）","form":"sovereignties"},{"label":"形容词（握有主权的）","form":"sovereign"},{"label":"名词（君主、主权者）","form":"sovereign"},{"label":"副词（以主权方式）","form":"sovereignly"}],"derivatives":[{"word":"sovereign","pos":"n./adj.","zh":"sovereignty 去掉 -ty 回溯到古法语 soverain → 君主、握有主权的，语义由抽象权力回到握权者"},{"word":"sovereignly","pos":"adv.","zh":"sovereign + -ly（副词后缀）→ 以最高权力方式地"},{"word":"suzerain","pos":"n.","zh":"古法语 suserain（无插入 g 的形式）→ 宗主，语义由完全主权降为对他国的宗主权"},{"word":"suzerainty","pos":"n.","zh":"suzerain + -ty（状态后缀）→ 宗主权，语义为主权的部分让渡"}],"senses":[{"no":"01","title":"Supreme authority within a state","titleCN":"国家内部的最高权力","definition":"the full power to make and enforce law within a territory, subject to no higher domestic authority","definitionCN":"在一国领土内制定与执行法律的完整权力，不受更高的国内权威约束","example":"The treaty recognised the new state's sovereignty over the whole valley.","exampleCN":"条约承认这个新国家对整个山谷拥有主权。","why":"The word names the quality of being sovereign, and sovereign meant 'above' others in the hierarchy of power.","whyCN":"这个词指「处于主权者地位」的性质，而 sovereign 本指在权力等级中「居于其上」。"},{"no":"02","title":"The status of an independent state","titleCN":"主权国家的地位","definition":"the recognised standing of a state as independent and equal in international law","definitionCN":"一国在国际法上被视为独立且平等的地位","example":"Recognition of sovereignty came only after the war.","exampleCN":"主权地位直到战后才得到承认。","why":"In international law sovereignty is a status that other states grant, not merely a fact of power.","whyCN":"在国际法中，主权是其他国家给予的地位，而不只是权力事实。"},{"no":"03","title":"Jurisdiction over a particular territory","titleCN":"对某片领土的管辖权","definition":"the legal right to govern a specific area, often disputed between states","definitionCN":"治理特定地区的法律权利，常在国家间发生争议","example":"The court disputed sovereignty over the islands.","exampleCN":"法院对这些岛屿的主权归属存在争议。","why":"Supreme power has to be located somewhere, so the word is often used with 'over' plus a named place.","whyCN":"最高权力必须落在某处，因此这个词常与 over 加具体地名连用。"},{"no":"04","title":"The authority of a monarch","titleCN":"君主所握的统治权","definition":"the personal right of a king or queen to rule, in the older constitutional order","definitionCN":"在较早的宪政秩序中，国王或女王个人拥有的统治权利","example":"In the old order, sovereignty belonged to the crown alone.","exampleCN":"在旧秩序中，主权只属于王冠。","why":"Before states were impersonal, sovereignty was the ruler's own possession, and that historical layer remains in the word.","whyCN":"在国家尚未非人格化之前，主权是统治者本人的财产，这一历史层仍留在词中。"},{"no":"05","title":"Freedom from outside control","titleCN":"不受外部控制的自主","definition":"the ability of a people or state to decide its own affairs without foreign direction","definitionCN":"一个民族或国家不受外国指挥而自决事务的能力","example":"The movement demanded sovereignty in economic policy.","exampleCN":"这场运动要求在经济政策上拥有自主权。","why":"If supreme authority is not held abroad, then autonomy at home is the same idea seen from the border.","whyCN":"既然最高权力不在国外，那么国内自主就是从边界那一侧看到的同一观念。"},{"no":"06","title":"Supreme power as a theoretical concept","titleCN":"政治理论中的最高权力概念","definition":"the abstract location of final law-making authority in a political community","definitionCN":"政治共同体中最终立法权威的抽象归属","example":"Bodin placed sovereignty in the office that makes law.","exampleCN":"博丹把主权放在制定法律的职位上。","why":"Political theory turned a practical power into an analytic question: where does final authority sit?","whyCN":"政治理论把一种实际权力转为分析问题：最终权威究竟位于何处？"},{"no":"07","title":"Personal autonomy over one's own life","titleCN":"对自身生活的个人自主","definition":"an individual's authority over their own body, choices and private sphere","definitionCN":"个人对自己身体、选择与私域的权力","example":"She defended her sovereignty over her own body.","exampleCN":"她捍卫对自己身体的自主权。","why":"Modern rights language applies the state's self-rule to the person, producing a moral rather than legal sovereignty.","whyCN":"现代权利话语把国家的自治套用到个人身上，产生道德而非法律意义上的主权。"},{"no":"08","title":"Divine rule over history","titleCN":"神对历史的支配","definition":"in theology, God's supreme and unchallenged control of events","definitionCN":"神学中神对万事万物至高无上的支配","example":"The sermon stressed God's sovereignty over history.","exampleCN":"布道强调神对历史的主权。","why":"The word's core of unquestioned supremacy fits theology, where no earthly court can review the ruler.","whyCN":"这个词「不容置疑的最高」这一核心适合神学，因为世间没有法庭能复审这位统治者。"}],"etymology":{"intro":{"en":"Sovereignty is the abstract noun of sovereign, from Old French soverain plus the suffix -ty, ultimately from Latin superanus 'chief' and super 'above'. Dates are approximate.","cn":"sovereignty 是 sovereign 的抽象名词，由古法语 soverain 加后缀 -ty 构成，最终出自拉丁 superanus「首领」与 super「在上」。年代均为约数。"},"items":[{"era":"LATIN SUPER","en":"Super meant 'above, over'; it is the source of many English words about rank and excess.","cn":"super 意为「在上、超过」，是许多表示等级与过量的英语词的来源。"},{"era":"LATIN SUPERANUS","en":"The adjective superanus meant 'chief, superior', literally the one above the rest.","cn":"形容词 superanus 意为「首领的、优越的」，字面就是居于其余之上者。"},{"era":"OLD FRENCH SOVEREIN","en":"Old French soverain carried the word forward, and English adopted it as sovereign with an intrusive g of uncertain origin.","cn":"古法语 soverain 把词向前传，英语以 sovereign 采纳，其中插入的 g 来源不确定。"},{"era":"SUFFIX -TY","en":"The French abstract ending -té, from Latin -tas, made sovereignty the name of the quality or office.","cn":"法语抽象词尾 -té（源自拉丁 -tas）使 sovereignty 成为性质或职位的名称。"},{"era":"POLITICAL THEORY","en":"From Bodin in the sixteenth century, sovereignty became the technical term for the final law-making power in a state.","cn":"自十六世纪的博丹起，主权成为指国家最终立法权力的技术术语。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): no exact first English citation is established, and the intrusive g in sovereign has never been fully explained; forms without it survive in suzerain.","cn":"来源不确定（首见年代）：确切的最早英语书证未有定论；sovereign 中插入的 g 从未得到完满解释，不带 g 的形式保存在 suzerain 中。"}]},"similar":{"note":{"en":"Group one holds forms from the same superanus stock or accidental neighbours; group two holds words for self-rule and supreme authority.","cn":"第一组是同出 superanus 词干或偶然相邻的形式；第二组是表示自治与最高权威的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sovereign","ipa":"/ˈsɒvrɪn/","tag":"same root, base","definition":"The ruler or the adjective 'supreme'; sovereignty is the abstract quality or office.","definitionCN":"统治者或形容词「最高的」；sovereignty 是抽象性质或职位。"},{"word":"suzerain","ipa":"/ˈsuːzəreɪn/","tag":"same root, without g","definition":"From the same Old French word without the inserted g: a lord who controls another state's foreign affairs while leaving it internally self-governing.","definitionCN":"同出古法语而不带插入的 g：控制他国外交、却让其内部自治的宗主。"},{"word":"superior","ipa":"/suːˈpɪəriə/","tag":"related root","definition":"From Latin superior, the comparative of super: higher in rank. It shares the 'above' root but not the legal sense.","definitionCN":"出自拉丁 superior，super 的比较级：等级更高。共享「在上」词根，但无法律义。"},{"word":"superb","ipa":"/suːˈpɜːb/","tag":"different sense","definition":"From superbus 'proud, magnificent': excellent. It looks like a relative but the meaning took a different path.","definitionCN":"出自 superbus「骄傲、壮丽」：极好的。看似同族，但语义走了另一条路。"}]},{"heading":"NEAR MEANING","entries":[{"word":"autonomy","ipa":"/ɔːˈtɒnəmi/","tag":"self-rule","definition":"The right of a group to govern itself; it is often a limited or delegated form of sovereignty.","definitionCN":"一个群体自我治理的权利；常为主权的有限或授让形式。"},{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","tag":"freedom from control","definition":"Freedom from external rule; it names the fact of being free, while sovereignty names the legal authority.","definitionCN":"不受外部统治；指自由这一事实，而 sovereignty 指法律权威。"},{"word":"authority","ipa":"/ɔːˈθɒrəti/","tag":"power to act","definition":"The right to give orders or make decisions; it need not be supreme or territorial.","definitionCN":"发令或决策的权利；不必是最高的，也不必与领土相关。"},{"word":"dominion","ipa":"/dəˈmɪnjən/","tag":"ruled territory","definition":"Territory under one government, or the power to rule it; sovereignty is the authority, dominion often the land.","definitionCN":"受同一政府管辖的领土，或其统治权；sovereignty 侧重权威，dominion 常指土地。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"super 'above' + -anus 'belonging to' + -ty 'state': the state of being above all rivals.","cn":"super「在上」+ -anus「属于」+ -ty「状态」：居于所有对手之上的状态。"},{"en":"The family runs sovereign, sovereignty, sovereignly, suzerain, suzerainty.","cn":"同族词包括 sovereign、sovereignty、sovereignly、suzerain、suzerainty。"},{"en":"Fixed phrases: national sovereignty, territorial sovereignty, sovereignty over the islands.","cn":"固定搭配：国家主权、领土主权、对这些岛屿的主权。"},{"en":"The g in sovereign is unexplained; suzerain keeps the older shape without it.","cn":"sovereign 中的 g 无法解释；suzerain 保留了不带 g 的较早形态。"},{"en":"Bodin turned sovereignty into the technical question of where final law-making power sits.","cn":"博丹把主权变成「最终立法权位于何处」的技术问题。"}],"abstract":[{"en":"Picture a key that opens a border gate and cannot be copied abroad.","cn":"想象一把钥匙能打开国门，却无法在境外复制。"},{"en":"Picture a state with no higher court to appeal to.","cn":"想象一个国家，没有更高的法庭可以上诉。"},{"en":"Picture a person drawing a line around their own life and calling it a border.","cn":"想象一个人在自己生活周围画一条线，称它为边界。"}]},"examples":[{"en":"The constitution places sovereignty in the people rather than in a crown.","cn":"宪法把主权放在人民而非王冠手中。"},{"en":"Talks over sovereignty stalled for a decade.","cn":"关于主权的谈判停滞了十年。"},{"en":"Theologians write about sovereignty without any reference to parliaments.","cn":"神学家谈主权时完全不提议会。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sovereign」君主 + 「ty」状态——君主所握的那种最高权 → 主权","word":"sovereignty"},"root":"古法语 soverain「首领」+ -ty（状态后缀，源自拉丁 -tas）；soverain 出自通俗拉丁 superanus「居上者」，再上溯 super「在上」。英语 sovereignty。","sensesIntro":{"en":"Eight senses follow one claim to be above all rivals: it can sit in a state, a status, a territory, a throne, a people, a theory, a person or a god.","cn":"八个义项沿同一个「居于所有对手之上」的主张展开：它可以落在国家、地位、领土、王座、人民、理论、个人或神身上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crown-shaped key turning in the lock of a border stone.","cn":"核心意象：一把王冠形钥匙在国界碑的锁孔中转动。"},"chain":["SUPREME POWER","STATEHOOD","TERRITORY","CROWN","AUTONOMY","DIVINE RULE"],"branches":[{"senses":"S1 · S3","en":"POWER OVER A PLACE: supreme authority is always located somewhere.","cn":"对某地的权力：最高权威总落在某处。"},{"senses":"S2","en":"THE STATUS: other states recognise independence and equality.","cn":"地位：他国承认其独立与平等。"},{"senses":"S4","en":"THE CROWN: in the older order the power belonged to a person.","cn":"王冠：在较早秩序中，权力属于一个人。"},{"senses":"S5 · S7","en":"SELF-RULE: a people and a person can both claim authority over their own affairs.","cn":"自治：民族与个人都能主张对自身事务的权威。"},{"senses":"S6 · S8","en":"THEORY AND THEOLOGY: final authority becomes an analytic question, then an article of faith.","cn":"理论与神学：最终权威先成为分析问题，再成为信仰条款。"}]},"affixes":{"intro":{"en":"Sovereignty is a Latin-rooted base plus a French abstract ending, and its parts recur in English, so the family can be read morpheme by morpheme.","cn":"sovereignty 是拉丁词根基础加法语抽象词尾，其成分在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin super and superanus give sovereign; the abstract ending -tas, through French -té, gives sovereignty; suzerain keeps the same base without the intrusive g.","cn":"拉丁 super 与 superanus 衍生 sovereign；抽象词尾 -tas 经法语 -té 构成 sovereignty；suzerain 保留同一词基而不带插入的 g。"},"items":[{"word":"super","structure":"super (Latin preposition and prefix, 'above')","meaning":"above; over","meaningCN":"在上；超过","example":"The element also appears in superior and supervise.","exampleCN":"这个成分也出现在 superior 与 supervise 中。"},{"word":"-anus","structure":"-anus (Latin adjective suffix, 'belonging to')","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix made an adjective from a preposition.","exampleCN":"这个后缀由介词构成形容词。"},{"word":"superanus","structure":"super + -anus","meaning":"chief, superior","meaningCN":"首领；居上者","example":"Superanus named the one above the rest.","exampleCN":"superanus 指居于其余之上者。"},{"word":"soverain","structure":"superanus, through Old French","meaning":"chief, lord","meaningCN":"首领；君主","example":"Old French kept the sense of a lord above other lords.","exampleCN":"古法语保留了「众领主之上的领主」之意。"},{"word":"-ty","structure":"-té (French, from Latin -tas)","meaning":"state or quality","meaningCN":"状态或性质","example":"The suffix also builds royalty and loyalty.","exampleCN":"这个后缀也构成 royalty 与 loyalty。"},{"word":"sovereignty","structure":"sovereign + -ty","meaning":"supreme authority","meaningCN":"最高权力","example":"The state defended its sovereignty.","exampleCN":"这个国家捍卫自己的主权。"},{"word":"sovereign","structure":"soverain, with an intrusive g","meaning":"supreme ruler","meaningCN":"最高统治者","example":"The sovereign opened parliament.","exampleCN":"君主为议会开幕。"},{"word":"suzerain","structure":"Old French suserain, without the intrusive g","meaning":"a lord over another state","meaningCN":"凌驾于他国之上的宗主","example":"The suzerain controlled foreign policy.","exampleCN":"宗主控制外交政策。"},{"word":"suzerainty","structure":"suzerain + -ty","meaning":"partial sovereignty over another state","meaningCN":"对他国的部分主权","example":"Suzerainty left the province self-governing.","exampleCN":"宗主权让该省保持自治。"},{"word":"superior","structure":"super + -ior (comparative suffix)","meaning":"higher in rank","meaningCN":"等级更高的","example":"The superior officer signed the order.","exampleCN":"上级军官签署了命令。"}],"latinEntries":[{"word":"super","structure":"super (preposition, 'above, over')","meaning":"above, over","meaningCN":"在上；超过"},{"word":"superanus","structure":"superanus, superana, superanum (adjective, first and second declension)","meaning":"chief, superior","meaningCN":"首领的；居上的"},{"word":"superior","structure":"superior, superius (comparative adjective, third declension)","meaning":"higher","meaningCN":"更高的"}]}},{"word":"sovereign","ipa_uk":"/ˈsɒvrɪn/","ipa_us":"/ˈsɑːvrɪn/","definition_zh":"君主；主权国家；英国旧时一镑金币；握有最高权力的；独立自主的；（药）极有效的；完全的","definition_en":"a supreme ruler or an independent state; as an adjective, holding supreme power, self-governing, highly effective or complete","core_image":"一枚金币正面铸着君主侧面像，边缘的齿纹像国界的界桩","scene":"展柜里躺着一枚旧金币，正面是君主侧面像，旁边放着一份独立国家的条约副本。The sovereign refused to let a foreign court review the decree.","sceneCN":"这里 sovereign 指「握有最高权力、不受外部复审的君主或国家」（第 1 个义项：君主本人）；句意为这位君主拒绝让外国法庭复审这项敕令。可辨识物件：展柜、金币、侧面像、条约副本、敕令。","pos":[{"tag":"n.","zh":"君主；主权国家；英国旧时一镑金币"},{"tag":"adj.","zh":"握有最高权力的；独立自主的；极有效的；完全的"}],"collocations":[{"phrase":"a sovereign state","zh":"主权国家"},{"phrase":"sovereign debt","zh":"主权债务"},{"phrase":"sovereign immunity","zh":"主权豁免"},{"phrase":"a sovereign remedy","zh":"特效药"},{"phrase":"sovereign power","zh":"最高权力"},{"phrase":"a gold sovereign","zh":"一枚一镑金币"}],"forms":[{"label":"原级","form":"sovereign"},{"label":"比较级","form":"more sovereign"},{"label":"最高级","form":"most sovereign"},{"label":"名词复数","form":"sovereigns"},{"label":"抽象名词（主权）","form":"sovereignty"},{"label":"副词","form":"sovereignly"}],"derivatives":[{"word":"sovereignty","pos":"n.","zh":"sovereign + -ty（状态后缀，源自拉丁 -tas）→ 主权，语义由握权者转为抽象权力"},{"word":"sovereignly","pos":"adv.","zh":"sovereign + -ly（副词后缀）→ 以最高权力方式地"},{"word":"suzerain","pos":"n.","zh":"古法语 suserain（不带插入的 g）→ 宗主，语义由完全主权降为部分主权"},{"word":"suzerainty","pos":"n.","zh":"suzerain + -ty（状态后缀）→ 宗主权"},{"word":"sovereigntist","pos":"n./adj.","zh":"sovereignty + -ist（主张者后缀）→ 主权主义者，主张把权力留在本国"}],"senses":[{"no":"01","title":"A supreme ruler","titleCN":"握有最高权力的君主","definition":"a king, queen or other ruler who holds supreme authority","definitionCN":"握有最高权威的国王、女王或其他统治者","example":"The sovereign refused to let a foreign court review the decree.","exampleCN":"这位君主拒绝让外国法庭复审这项敕令。","why":"The adjective 'above all others' became a noun for the person who occupies that top place.","whyCN":"形容词「居于一切之上」转为名词，指占据那个最高位置的人。"},{"no":"02","title":"A former British gold coin","titleCN":"英国旧时的一镑金币","definition":"a British gold coin worth one pound sterling, minted until the early twentieth century","definitionCN":"英国旧时面值一英镑的金币，铸造至二十世纪初","example":"A sovereign hung on a chain in the museum case.","exampleCN":"展柜里，一枚金币挂在链子上。","why":"Coins were named after the portrait of the sovereign stamped on them, so the ruler's title became the coin's name.","whyCN":"硬币以铸在其上的君主肖像命名，于是统治者的称号成了硬币之名。"},{"no":"03","title":"Holding supreme power","titleCN":"握有最高权力的","definition":"possessing final authority that no other body can override","definitionCN":"拥有任何其他机构都无法推翻的最终权威","example":"The sovereign assembly could repeal any law.","exampleCN":"这个最高议会可以废除任何法律。","why":"The adjective keeps the original spatial image: the sovereign body sits above every other body.","whyCN":"这个形容词保留了原初的空间意象：主权机构位于所有其他机构之上。"},{"no":"04","title":"Independent and self-governing","titleCN":"独立自主的","definition":"describing a state that governs itself and is not subject to another's laws","definitionCN":"描述一个自我治理、不受他国法律约束的国家","example":"A sovereign state cannot be bound by another country's courts.","exampleCN":"主权国家不受他国法庭约束。","why":"If no power is above a state, then it is above every other state's jurisdiction, which is independence.","whyCN":"如果没有权力高于一国，那么它也不受任何他国管辖，这便是独立。"},{"no":"05","title":"Extremely effective as a remedy","titleCN":"作为药方极有效的","definition":"having a sure and powerful effect in curing a problem, used especially of medicines","definitionCN":"在解决问题上确有强效，尤用于药物","example":"Honey was once a sovereign remedy for wounds.","exampleCN":"蜂蜜曾是治疗伤口的特效药。","why":"A remedy that works above all others takes the same adjective of supremacy, so sovereign came to mean 'sure'.","whyCN":"效力高于一切其他手段的药方也取用这个「最高」形容词，于是 sovereign 有了「确效」之义。"},{"no":"06","title":"Of the highest worth","titleCN":"价值最高的","definition":"ranking first among goods or aims, as in philosophical discussion of the highest good","definitionCN":"在诸善或诸目标中居于首位，如哲学讨论中的最高善","example":"Scholars debated the sovereign good of the city.","exampleCN":"学者们辩论城邦的最高善。","why":"The word's rank sense fits moral philosophy, where one good is above all the others.","whyCN":"这个词的等级义适合道德哲学，其中有一种善高于其余一切。"},{"no":"07","title":"Complete and unlimited","titleCN":"完全而不受限制的","definition":"used before a noun to mean total, as in sovereign contempt or sovereign right","definitionCN":"用于名词前表示彻底，如完全的蔑视或绝对的权利","example":"He treated the proposal with sovereign contempt.","exampleCN":"他对这项提议报以彻底的蔑视。","why":"An attitude held by a ruler needs no one's approval, so 'sovereign' before a noun marks a feeling that admits no limit.","whyCN":"统治者的态度无需任何人批准，因此名词前的 sovereign 标记一种不受限制的情绪。"},{"no":"08","title":"Of a state's official debt or immunity","titleCN":"国家主权债务或豁免的","definition":"relating to a state in its capacity as a borrower or as a legal person immune from suit","definitionCN":"指国家作为借款人或免于被诉的法律人格","example":"Sovereign debt worries markets more than corporate borrowing.","exampleCN":"主权债务比企业借贷更令市场担忧。","why":"Finance needed a word for the state's own borrowing, and the state's supreme legal standing supplied it.","whyCN":"金融需要一个词指国家自身的借贷，而国家的最高法律地位提供了这个词。"}],"etymology":{"intro":{"en":"Sovereign comes through Old French soverain from Vulgar Latin superanus 'chief', from Latin super 'above'. The g in English spelling has no settled explanation. Dates are approximate.","cn":"sovereign 经古法语 soverain 来自通俗拉丁 superanus「首领」，再上溯拉丁 super「在上」。英语拼写中的 g 没有定论。年代均为约数。"},"items":[{"era":"LATIN SUPER","en":"Super 'above, over' is the root of rank words such as superior and supervise.","cn":"super「在上、超过」是 superior、supervise 等表示等级的词的词根。"},{"era":"VULGAR LATIN SUPERANUS","en":"Superanus meant 'chief, the one above', formed with the adjective suffix -anus.","cn":"superanus 意为「首领、居上者」，由形容词后缀 -anus 构成。"},{"era":"OLD FRENCH SOVEREIN","en":"Old French soverain carried the word to English, where the spelling gained a g that no Latin or French form shows.","cn":"古法语 soverain 把词带入英语，英语拼写多出一个 g，而拉丁或法语形式都没有这个字母。"},{"era":"THE COIN","en":"From 1817 the gold pound coin was called a sovereign because it bore the monarch's portrait.","cn":"自 1817 年起，一英镑金币因铸有君主肖像而被称为 sovereign。"},{"era":"LEGAL AND FINANCIAL USES","en":"International law and finance extended the adjective to states, producing sovereign immunity and sovereign debt.","cn":"国际法与金融把这个形容词扩展到国家，产生主权豁免与主权债务。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the intrusive g has never been fully explained, and the earliest English citation is not established; forms without it survive in suzerain.","cn":"来源不确定（首见年代）：插入的 g 从未得到完满解释，最早的英语书证也未确定；不带 g 的形式保存在 suzerain 中。"}]},"similar":{"note":{"en":"Group one holds forms from the same superanus stock or accidental look-alikes; group two holds words for supreme or independent power.","cn":"第一组是同出 superanus 词干或偶然形近的形式；第二组是表示最高或独立权力的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sovereignty","ipa":"/ˈsɒvrənti/","tag":"same root, abstract","definition":"The abstract noun for the authority itself; sovereign is the holder or the adjective.","definitionCN":"指权威本身的抽象名词；sovereign 指握有者或形容词。"},{"word":"suzerain","ipa":"/ˈsuːzəreɪn/","tag":"same root, no g","definition":"The same Old French base without the inserted g: a lord over a state that keeps internal self-rule.","definitionCN":"同一古法语词基而不带插入的 g：凌驾于一国之上、却让其内部自治的宗主。"},{"word":"superior","ipa":"/suːˈpɪəriə/","tag":"related comparative","definition":"Latin comparative of super, 'higher'; it shares the root but means relative rank, not supreme legal power.","definitionCN":"super 的拉丁比较级「更高的」；共享词根，但指相对等级，而非最高法律权力。"},{"word":"superb","ipa":"/suːˈpɜːb/","tag":"different sense","definition":"From superbus 'proud, splendid': excellent. The spelling suggests kinship, but the sense developed separately.","definitionCN":"出自 superbus「骄傲、辉煌」：极佳的。拼写显得同族，但语义另有发展。"}]},{"heading":"NEAR MEANING","entries":[{"word":"monarch","ipa":"/ˈmɒnək/","tag":"ruler","definition":"A sole hereditary ruler; sovereign may be any supreme authority, including an elected assembly.","definitionCN":"唯一的世袭统治者；sovereign 可指任何最高权威，包括经选举的议会。"},{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","tag":"self-governing","definition":"Free from outside control; it stresses the fact of freedom, while sovereign stresses legal supremacy.","definitionCN":"不受外部控制；强调自由的事实，而 sovereign 强调法律上的最高性。"},{"word":"supreme","ipa":"/suːˈpriːm/","tag":"highest rank","definition":"Highest in rank or degree; it is a plainer adjective and lacks the political and legal history of sovereign.","definitionCN":"等级或程度上最高的；是更朴素的形容词，没有 sovereign 那样的政治与法律史。"},{"word":"paramount","ipa":"/ˈpærəmaʊnt/","tag":"above all others","definition":"More important than all others; it ranks concerns, not institutions.","definitionCN":"比其余一切更重要；排列的是事务，而非机构。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"super 'above' + -anus 'belonging to': the one belonging above all others.","cn":"super「在上」+ -anus「属于」：属于所有人之上的那一个。"},{"en":"The family runs sovereign, sovereignty, sovereignly, suzerain, suzerainty.","cn":"同族词包括 sovereign、sovereignty、sovereignly、suzerain、suzerainty。"},{"en":"Fixed phrases: sovereign state, sovereign debt, sovereign immunity, sovereign remedy.","cn":"固定搭配：主权国家、主权债务、主权豁免、特效药。"},{"en":"The gold coin was named after the portrait on its face.","cn":"金币因币面上的肖像而得名。"},{"en":"suzerain preserves the older spelling without the unexplained g.","cn":"suzerain 保留了不带那个无法解释的 g 的较早拼写。"}],"abstract":[{"en":"Picture a coin whose face is a ruler and whose edge is a border.","cn":"想象一枚金币，正面是君主，边缘是国界。"},{"en":"Picture a courtroom with a sign saying no appeal beyond this room.","cn":"想象一间法庭，挂着「此室外无上诉」的牌子。"},{"en":"Picture a medicine that works before the diagnosis is finished.","cn":"想象一种药，诊断还没结束就已见效。"}]},"examples":[{"en":"Each sovereign state prints its own passports.","cn":"每个主权国家都印自己的护照。"},{"en":"The coin dealer offered him a sovereign from the old mint.","cn":"钱币商向他出售一枚旧铸币厂的金币。"},{"en":"Investors watched sovereign debt as closely as company earnings.","cn":"投资者关注主权债务，如同关注公司盈利。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sovereign」音近「谁负人」——没人能负在他之上，因为他是最高统治者 → 君主、主权的","word":"sovereign"},"root":"古法语 soverain「首领」← 通俗拉丁 superanus「居上者」← 拉丁 super「在上」+ -anus（形容词后缀）。英语 sovereign，插入的 g 来源不确定。","sensesIntro":{"en":"Eight senses follow one position at the top: a person, a coin, an assembly, a state, a medicine, a good, a mood and a debt can all be described as beyond appeal.","cn":"八个义项沿同一个「居于顶端」的位置展开：人、硬币、议会、国家、药物、善、情绪与债务都可以被称为「无从上诉」。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gold coin bearing a ruler's profile, its milled edge like a row of border stones.","cn":"核心意象：一枚铸着君主侧面像的金币，齿边像一排界桩。"},"chain":["RULER","SUPREME POWER","INDEPENDENT STATE","GOLD COIN","EFFECTIVE REMEDY","ABSOLUTE QUALITY"],"branches":[{"senses":"S1","en":"THE PERSON: the one who occupies the top place in a realm.","cn":"人：在疆域中占据最高位置的那一个。"},{"senses":"S2","en":"THE COIN: a portrait turns a title into a piece of money.","cn":"硬币：一张肖像把称号变成一枚钱币。"},{"senses":"S3 · S8","en":"THE INSTITUTION: an assembly or a state acts beyond any appeal.","cn":"机构：议会或国家行事不受任何上诉约束。"},{"senses":"S4","en":"THE STATE: no foreign court sits above it.","cn":"国家：没有外国法庭位于其上。"},{"senses":"S5 · S6 · S7","en":"ABSOLUTE QUALITY: a cure, a good or a contempt that admits no rival.","cn":"绝对性质：一种疗法、一种善或一种蔑视，都不容对手。"}]},"affixes":{"intro":{"en":"Sovereign is a Latin-rooted adjective that became a noun, and its parts recur in English, so the family can be read morpheme by morpheme.","cn":"sovereign 是由拉丁词根构成的形容词，后转为名词，其成分在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin super and superanus give sovereign and suzerain; the abstract ending -ty gives sovereignty.","cn":"拉丁 super 与 superanus 衍生 sovereign 与 suzerain；抽象词尾 -ty 衍生 sovereignty。"},"items":[{"word":"super","structure":"super (Latin preposition and prefix, 'above')","meaning":"above; over","meaningCN":"在上；超过","example":"The element also appears in superior.","exampleCN":"这个成分也出现在 superior 中。"},{"word":"-anus","structure":"-anus (Latin adjective suffix, 'belonging to')","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix built an adjective from a preposition.","exampleCN":"这个后缀由介词构成形容词。"},{"word":"superanus","structure":"super + -anus","meaning":"chief, superior","meaningCN":"首领；居上者","example":"Superanus named the one above the rest.","exampleCN":"superanus 指居于其余之上者。"},{"word":"sovereign","structure":"superanus, through Old French soverain","meaning":"supreme ruler","meaningCN":"最高统治者","example":"The sovereign opened parliament.","exampleCN":"君主为议会开幕。"},{"word":"-ty","structure":"-té (French, from Latin -tas)","meaning":"state or quality","meaningCN":"状态或性质","example":"The suffix also builds royalty.","exampleCN":"这个后缀也构成 royalty。"},{"word":"sovereignty","structure":"sovereign + -ty","meaning":"supreme authority","meaningCN":"最高权力","example":"The state defended its sovereignty.","exampleCN":"这个国家捍卫自己的主权。"},{"word":"sovereignly","structure":"sovereign + -ly (adverb)","meaning":"in a supreme manner","meaningCN":"以最高方式地","example":"The court acted sovereignly.","exampleCN":"该法院以最高权威行事。"},{"word":"suzerain","structure":"Old French suserain, without the intrusive g","meaning":"lord over another state","meaningCN":"凌驾于他国之上的宗主","example":"The suzerain controlled foreign policy.","exampleCN":"宗主控制外交政策。"},{"word":"suzerainty","structure":"suzerain + -ty","meaning":"partial sovereignty","meaningCN":"部分主权","example":"Suzerainty left the province self-governing.","exampleCN":"宗主权让该省保持自治。"},{"word":"superior","structure":"super + -ior (comparative suffix)","meaning":"higher","meaningCN":"更高的","example":"The superior officer signed.","exampleCN":"上级军官签了字。"}],"latinEntries":[{"word":"super","structure":"super (preposition, 'above, over')","meaning":"above, over","meaningCN":"在上；超过"},{"word":"superanus","structure":"superanus, superana, superanum (adjective, first and second declension)","meaning":"chief, superior","meaningCN":"首领的；居上的"},{"word":"superior","structure":"superior, superius (comparative adjective, third declension)","meaning":"higher","meaningCN":"更高的"}]}},{"word":"colonial","ipa_uk":"/kəˈləʊniəl/","ipa_us":"/kəˈloʊniəl/","definition_zh":"殖民地的；殖民统治的；殖民时期风格的；美洲殖民时期的；群居的（生物）；依附的；殖民风格房屋","definition_en":"relating to a colony or to colonial rule; also describing a period style, organisms that live in colonies, and a dependent relationship","core_image":"一排白柱门廊立在红土路旁，门廊后面是刚划出的田界","scene":"小镇的主街上，白柱门廊连成一排，屋后是刚用木桩划出的田界。The colonial houses along the main street were built by settlers in the eighteenth century.","sceneCN":"这里 colonial 指「殖民时期风格的」（第 3 个义项：移民地区流行的建筑式样）；句意为主街两侧的殖民风格房屋由十八世纪的移民所建。可辨识物件：白柱门廊、木桩、田界、红土路、房屋。","pos":[{"tag":"adj.","zh":"殖民地的；殖民统治的；殖民时期风格的；群居的；依附的"},{"tag":"n.","zh":"殖民风格房屋（美式）；殖民地居民（旧称）"}],"collocations":[{"phrase":"colonial rule","zh":"殖民统治"},{"phrase":"colonial architecture","zh":"殖民时期建筑"},{"phrase":"colonial power","zh":"殖民列强"},{"phrase":"colonial era","zh":"殖民时代"},{"phrase":"colonial administration","zh":"殖民行政机构"},{"phrase":"colonial organism","zh":"群居生物"}],"forms":[{"label":"原级","form":"colonial"},{"label":"比较级","form":"more colonial"},{"label":"最高级","form":"most colonial"},{"label":"副词","form":"colonially"},{"label":"名词（殖民地）","form":"colony"},{"label":"名词复数（房屋）","form":"colonials"}],"derivatives":[{"word":"colonially","pos":"adv.","zh":"colonial + -ly（副词后缀）→ 以殖民方式地"},{"word":"colonialism","pos":"n.","zh":"colonial + -ism（体系后缀）→ 殖民主义，语义由属性转为制度与主张"},{"word":"colonialist","pos":"n./adj.","zh":"colonial + -ist（主张者后缀）→ 殖民主义者；支持殖民统治的"},{"word":"colonialistic","pos":"adj.","zh":"colonialist + -ic（形容词后缀）→ 带殖民主义色彩的"},{"word":"post-colonial","pos":"adj.","zh":"post-（之后前缀）+ colonial → 后殖民的，语义指向殖民统治结束后的文化与政治"},{"word":"neo-colonial","pos":"adj.","zh":"neo-（新前缀）+ colonial → 新殖民的，语义由直接占领转为经济支配"},{"word":"colonize","pos":"v.","zh":"colony + -ize（动词后缀）→ 建立殖民地、移居开拓"}],"senses":[{"no":"01","title":"Relating to a colony","titleCN":"与殖民地相关的","definition":"connected with a settlement established in a new territory by people from elsewhere","definitionCN":"与外来者在新领土上建立的定居点相关","example":"Colonial administration depended on a governor and a small garrison.","exampleCN":"殖民地的管理依靠一位总督和一支小规模驻军。","why":"Colonia was the Latin word for a settlement, and the adjective simply marks what belongs to one.","whyCN":"colonia 是拉丁语「定居点」，这个形容词只是标记属于定居点的事物。"},{"no":"02","title":"Relating to rule over subject territories","titleCN":"与对外统治相关的","definition":"connected with the system by which one country governs another people","definitionCN":"与一国统治另一民族的那套制度相关","example":"Colonial borders cut through traditional grazing land.","exampleCN":"殖民边界切断了传统的放牧地。","why":"Once settlements became governments, the adjective extended from the place to the whole apparatus of rule.","whyCN":"定居点一旦成为政府，这个形容词便从地点扩展到整套统治机器。"},{"no":"03","title":"In the style of a colonial period","titleCN":"殖民时期风格的","definition":"describing architecture, furniture or dress modelled on settler building in a colonial era","definitionCN":"描述仿照殖民时期移民建筑与陈设的建筑、家具或服饰","example":"The colonial houses along the main street were built by settlers in the eighteenth century.","exampleCN":"主街两侧的殖民风格房屋由十八世纪的移民所建。","why":"Later generations named a style after the era that produced it, so a white portico became 'colonial'.","whyCN":"后人以产生该风格的年代为其命名，于是白色门廊便成了「殖民风格」。"},{"no":"04","title":"Of the British American colonies","titleCN":"英属美洲殖民地的","definition":"relating to the thirteen British colonies in North America before independence","definitionCN":"与独立前北美十三个英属殖民地相关","example":"Colonial newspapers carried the first reports of the tax.","exampleCN":"殖民地报纸最早报道了这项税。","why":"American history fixed the adjective to one particular set of colonies, and the capitalised phrase survives.","whyCN":"美国历史把这个形容词固定到特定一组殖民地，大写词组沿用至今。"},{"no":"05","title":"Living in a colony as an organism","titleCN":"生物群居的","definition":"describing animals or organisms that live in closely connected groups","definitionCN":"描述紧密相连成群生活的动物或生物","example":"Coral is a colonial animal that shares one skeleton.","exampleCN":"珊瑚是共享一副骨骼的群居动物。","why":"Biology borrowed the settlement image for organisms whose individuals live together like settlers in one town.","whyCN":"生物学借用了定居点意象，指个体像同镇移民那样共同生活的生物。"},{"no":"06","title":"Of settler society","titleCN":"移民社会的","definition":"describing the social order created by settlers, with its land grants and imported customs","definitionCN":"描述移民建立的社会秩序，包括土地授予与输入的风俗","example":"Colonial society was divided by land grants and church seats.","exampleCN":"殖民地社会因土地授予与教会席位而分层。","why":"The adjective describes not only the rulers but the whole society that settlement produced.","whyCN":"这个形容词不只描述统治者，也描述定居所生产的整个社会。"},{"no":"07","title":"Dependent and subordinate","titleCN":"依附而居下的","definition":"describing a relationship in which one party is treated as a subordinate possession","definitionCN":"描述一方被当作附属财产对待的关系","example":"The ministry treated the region as a colonial dependency.","exampleCN":"该部把这个地区当作殖民附属地对待。","why":"Political criticism generalised the adjective: any unequal dependency can be called colonial.","whyCN":"政治批评把这个形容词一般化：任何不平等的依附都可称为殖民式。"},{"no":"08","title":"A house in colonial style","titleCN":"殖民风格房屋（名词）","definition":"in American usage, a house built in the symmetrical style of the colonial period","definitionCN":"美式用法中指按殖民时期对称式样建造的房屋","example":"They bought a colonial with a wide porch and two chimneys.","exampleCN":"他们买下一栋带宽门廊和两个烟囱的殖民风格房屋。","why":"Americans shortened 'colonial house' to the adjective alone, so the style name became the name of the building.","whyCN":"美国人把「殖民风格房屋」简称为形容词本身，于是风格名成了建筑名。"}],"etymology":{"intro":{"en":"Colonial is the Latin adjective colonialis, built on colonia 'settlement' and colonus 'farmer, settler', from colere 'to cultivate'. Dates are approximate.","cn":"colonial 是拉丁形容词 colonialis，由 colonia「定居点」与 colonus「农夫、移民」构成，再上溯 colere「耕种」。年代均为约数。"},"items":[{"era":"LATIN COLERE","en":"Colere meant 'to till, cultivate, inhabit'; it is also the root of culture and agriculture.","cn":"colere 意为「耕种、培育、居住」，也是 culture 与 agriculture 的词根。"},{"era":"LATIN COLONUS","en":"A colonus was a farmer or tenant, literally one who cultivates the land.","cn":"colonus 指农夫或佃户，字面就是耕种土地的人。"},{"era":"LATIN COLONIA","en":"Colonia named a settlement of citizens planted in conquered or new territory, the direct source of colony.","cn":"colonia 指在被征服或新领土上安置公民的定居点，是 colony 的直接来源。"},{"era":"LATIN COLONIALIS","en":"The suffix -alis made colonialis, 'of a settlement', the adjective that English borrowed.","cn":"后缀 -alis 构成 colonialis「定居点的」，即英语借用的形容词。"},{"era":"MODERN STYLE AND BIOLOGY","en":"The architectural sense arose in the nineteenth century from American and British imperial nostalgia, and the biological sense from the image of many individuals sharing one place.","cn":"建筑义在十九世纪由美国与英帝国的怀旧情绪产生，生物义则来自众多个体共享一处的意象。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest use of colonial for the architectural style and for colonial organisms is not precisely recorded, since both grew out of ordinary descriptive writing.","cn":"来源不确定（首见年代）：colonial 用于建筑风格与群居生物的最早记录都不确切，因为两者都从日常描写文字中自然生长出来。"}]},"similar":{"note":{"en":"Group one holds forms from the same colonia stock or accidental look-alikes; group two holds words about settlement and empire.","cn":"第一组是同出 colonia 词干或偶然形近的形式；第二组是有关定居与帝国的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"colony","ipa":"/ˈkɒləni/","tag":"same root, place","definition":"The settlement itself, from colonia; colonial is its adjective.","definitionCN":"定居点本身，出自 colonia；colonial 是其形容词。"},{"word":"colonist","ipa":"/ˈkɒlənɪst/","tag":"same root, person","definition":"A settler in a colony, from colony plus -ist; the person, not the system.","definitionCN":"殖民地的移民，由 colony 加 -ist 构成；指人，而非制度。"},{"word":"colonialism","ipa":"/kəˈləʊniəlɪzəm/","tag":"same root, system","definition":"The practice or ideology of ruling colonies; colonial is the descriptive adjective.","definitionCN":"统治殖民地的实践或意识形态；colonial 是描述性形容词。"},{"word":"colon","ipa":"/ˈkəʊlən/","tag":"different root","definition":"From Greek kolon 'limb', the large intestine or the punctuation mark; it has nothing to do with settlement.","definitionCN":"出自希腊 kolon「肢体」，指大肠或冒号；与定居毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"imperial","ipa":"/ɪmˈpɪəriəl/","tag":"empire-wide","definition":"Relating to an empire or emperor; colonial is narrower, concerning settlements and their rule.","definitionCN":"与帝国或皇帝相关；colonial 更窄，涉及定居点及其统治。"},{"word":"settler","ipa":"/ˈsetlə/","tag":"person","definition":"A person who moves into a new region to live there; colonial describes the society such people build.","definitionCN":"迁入新地区居住的人；colonial 描述这些人建立的社会。"},{"word":"dependent","ipa":"/dɪˈpendənt/","tag":"subordinate","definition":"Relying on another for support or authority; colonial can imply this, but dependent is the general word.","definitionCN":"依靠他方支持或权威；colonial 可含此意，但 dependent 是通用词。"},{"word":"provincial","ipa":"/prəˈvɪnʃl/","tag":"of a province","definition":"Relating to a province, often with a hint of narrowness; it lacks the settlement and empire history of colonial.","definitionCN":"与行省相关，常带狭隘意味；没有 colonial 那种定居与帝国的历史。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"colere 'cultivate' + -ia 'settlement' + -alis 'relating to': what belongs to a planted settlement.","cn":"colere「耕种」+ -ia「定居点」+ -alis「与……相关」：属于拓殖定居点的事物。"},{"en":"The family runs colony, colonist, colonial, colonialism, colonialist, colonize.","cn":"同族词包括 colony、colonist、colonial、colonialism、colonialist、colonize。"},{"en":"Fixed phrases: colonial rule, colonial era, colonial architecture.","cn":"固定搭配：殖民统治、殖民时代、殖民时期建筑。"},{"en":"Culture and agriculture share the root colere, since both involve tending.","cn":"culture 与 agriculture 共享 colere 词根，因为两者都涉及照料培育。"},{"en":"The biological sense keeps the image of many individuals living in one place.","cn":"生物义保留了众多个体共居一处的意象。"}],"abstract":[{"en":"Picture a white porch standing on land whose boundary posts were just driven in.","cn":"想象一座白色门廊立在刚刚打进界桩的土地上。"},{"en":"Picture a garden planted by one family in another family's field.","cn":"想象一家人在另一家的田里开辟花园。"},{"en":"Picture a coral reef where every animal shares one stone house.","cn":"想象一片珊瑚礁，每只动物共享一座石屋。"}]},"examples":[{"en":"Colonial officials mapped the valley before any settler arrived.","cn":"殖民官员在移民到来之前就测绘了这个山谷。"},{"en":"The inn keeps its colonial façade but a modern kitchen.","cn":"这家客栈保留殖民风格的外立面，厨房却是现代的。"},{"en":"Biologists classed the insects as colonial because they nest in one mound.","cn":"生物学家把这些昆虫归为群居，因为它们在同一土丘筑巢。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「colony」殖民地 + 「al」的——殖民地的、殖民时期风格的","word":"colonial"},"root":"拉丁 colonialis「定居点的」= colonia「定居点」+ -alis（关系形容词后缀）；colonia 出自 colonus「耕种者」，再上溯 colere「耕种」。英语 colonial。","sensesIntro":{"en":"Eight senses follow one settlement: a planted town. It becomes an administration, a style, a set of American colonies, a coral group, a stratified society, a dependency and finally a house.","cn":"八个义项沿同一个定居点展开：一座被拓殖的城镇。它依次成为行政机构、风格、美洲殖民地群、珊瑚群体、分层社会、附属地，最后成为一栋房子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of white porticoes beside a dirt road, with fresh boundary posts behind the houses.","cn":"核心意象：红土路旁一排白色门廊，屋后是刚打下的界桩。"},"chain":["COLONY","SETTLEMENT","RULE","PERIOD STYLE","AMERICAN COLONIES","COLONIAL ANIMAL"],"branches":[{"senses":"S1 · S2 · S6","en":"PLACE AND POWER: a settlement becomes an administration and a stratified society.","cn":"地点与权力：定居点变成行政机构与分层社会。"},{"senses":"S3 · S8","en":"STYLE AND HOUSE: later generations name a look after the era, then name the building after the look.","cn":"风格与房屋：后人以年代命名式样，再以式样命名建筑。"},{"senses":"S4","en":"THE THIRTEEN: American history fixes the adjective to one particular set of colonies.","cn":"十三殖民地：美国历史把这个形容词固定到特定一组殖民地。"},{"senses":"S5","en":"THE ORGANISM: biology borrows the town image for animals sharing one home.","cn":"生物：生物学借用城镇意象，指共享一处的动物。"},{"senses":"S7","en":"THE DEPENDENCY: any unequal relationship can be called colonial.","cn":"依附：任何不平等关系都可被称为殖民式。"}]},"affixes":{"intro":{"en":"Colonial is a Latin noun plus a relational suffix, and both parts recur in English, so the family can be read morpheme by morpheme.","cn":"colonial 是拉丁名词加关系后缀，两部分都在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin colere, colonus and colonia give colony, colonist and colonial; the suffix -alis gives the adjective.","cn":"拉丁 colere、colonus 与 colonia 衍生 colony、colonist 与 colonial；后缀 -alis 构成形容词。"},"items":[{"word":"colere","structure":"colere (Latin verb, third conjugation)","meaning":"to till, cultivate, inhabit","meaningCN":"耕种；培育；居住","example":"The root ties settlement to cultivation.","exampleCN":"这个词根把定居与耕作联系起来。"},{"word":"colonus","structure":"colere + -onus (agent noun)","meaning":"farmer, settler","meaningCN":"农夫；移民","example":"A colonus worked the land he held.","exampleCN":"移民耕种自己持有的土地。"},{"word":"colonia","structure":"colonus + -ia (place noun)","meaning":"settlement","meaningCN":"定居点","example":"The colonia grew into a market town.","exampleCN":"定居点发展成了集镇。"},{"word":"-alis","structure":"-alis (Latin relational suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turned the place into an adjective.","exampleCN":"这个后缀把地点转为形容词。"},{"word":"colonial","structure":"colonia + -alis","meaning":"of a settlement","meaningCN":"定居点的","example":"Colonial rule lasted two generations.","exampleCN":"殖民统治延续了两代。"},{"word":"colony","structure":"colonia, through Latin and English","meaning":"a settlement","meaningCN":"定居点；殖民地","example":"The colony exported timber.","exampleCN":"这块殖民地出口木材。"},{"word":"colonist","structure":"colony + -ist (person)","meaning":"a settler","meaningCN":"移民；殖民者","example":"The colonist cleared the field.","exampleCN":"移民清理了田地。"},{"word":"colonialism","structure":"colonial + -ism (system)","meaning":"the practice of ruling colonies","meaningCN":"统治殖民地的实践","example":"Colonialism reshaped the coast.","exampleCN":"殖民主义重塑了海岸。"},{"word":"colonize","structure":"colony + -ize (verb)","meaning":"to establish a colony","meaningCN":"建立殖民地","example":"Settlers colonized the river mouth.","exampleCN":"移民在河口建立了殖民地。"},{"word":"culture","structure":"Latin cultura, from colere 'cultivate'","meaning":"cultivation, refinement","meaningCN":"培育；教养","example":"The word began as a farming term.","exampleCN":"这个词最初是农事用语。"}],"latinEntries":[{"word":"colere","structure":"colere, colui, cultum (verb, third conjugation)","meaning":"to till, cultivate, inhabit","meaningCN":"耕种；培育；居住"},{"word":"colonus","structure":"colonus, coloni (m., second declension)","meaning":"farmer, settler","meaningCN":"农夫；移民"},{"word":"colonia","structure":"colonia, coloniae (f., first declension)","meaning":"settlement, colony","meaningCN":"定居点；殖民地"},{"word":"colonialis","structure":"colonialis, coloniale (adjective, third declension)","meaning":"of a settlement","meaningCN":"定居点的"}]}},{"word":"colonialism","ipa_uk":"/kəˈləʊniəlɪzəm/","ipa_us":"/kəˈloʊniəlɪzəm/","definition_zh":"殖民主义；获取与统治殖民地的制度与实践；欧洲海外扩张的历史进程；经济与文化上的对外支配；后殖民研究中的历史遗产","definition_en":"the system and practice of acquiring, settling and governing colonies, and the ideology or legacy of that rule","core_image":"一只账本压在港口地图上，旁边是一张土地授予书和一面折叠的旗","scene":"旧档案室的桌上摊开港口地图，压着一本账册，旁边是土地授予书和一面折叠的旗。Colonialism turned the harbour into an export point for one distant market.","sceneCN":"这里 colonialism 指「获取与统治殖民地的制度与实践」（第 1 个义项：把远方土地与劳力纳入宗主国体系）；句意为殖民主义把这个港口变成面向远方单一市场的出口点。可辨识物件：档案桌、港口地图、账册、土地授予书、折叠的旗。","pos":[{"tag":"n.","zh":"殖民主义；殖民制度与实践（多作不可数）"}],"collocations":[{"phrase":"European colonialism","zh":"欧洲殖民主义"},{"phrase":"settler colonialism","zh":"移民殖民主义"},{"phrase":"the legacy of colonialism","zh":"殖民主义的遗产"},{"phrase":"end colonialism","zh":"终结殖民主义"},{"phrase":"internal colonialism","zh":"内部殖民主义"},{"phrase":"a critique of colonialism","zh":"对殖民主义的批判"}],"forms":[{"label":"通常形式（不可数）","form":"colonialism"},{"label":"复数（指多种殖民体系，较少用）","form":"colonialisms"},{"label":"形容词（殖民主义的）","form":"colonialist"},{"label":"名词（殖民主义者）","form":"colonialist"},{"label":"形容词（殖民地的）","form":"colonial"},{"label":"名词（非殖民化）","form":"decolonization"}],"derivatives":[{"word":"colonialist","pos":"n./adj.","zh":"colonial + -ist（主张者后缀）→ 殖民主义者；支持殖民统治的，语义由体系转为行动者"},{"word":"colonialistic","pos":"adj.","zh":"colonialist + -ic（形容词后缀）→ 带殖民主义色彩的"},{"word":"decolonization","pos":"n.","zh":"de-（去除前缀）+ colonization → 非殖民化，语义由建立殖民体系转为拆除它"},{"word":"decolonize","pos":"v.","zh":"de- + colonize（动词后缀）→ 使非殖民化、摆脱殖民统治"},{"word":"neocolonialism","pos":"n.","zh":"neo-（新前缀）+ colonialism → 新殖民主义，语义由直接统治转为经济与制度支配"},{"word":"postcolonial","pos":"adj.","zh":"post-（之后前缀）+ colonial → 后殖民的，语义指向殖民统治结束后的文化与政治"}],"senses":[{"no":"01","title":"The practice of acquiring and ruling colonies","titleCN":"获取并统治殖民地的实践","definition":"the activity of seizing territory overseas and governing its people from a distant centre","definitionCN":"在海外夺取领土并由远方中心治理其人民的行为","example":"Colonialism turned the harbour into an export point for one distant market.","exampleCN":"殖民主义把这个港口变成面向远方单一市场的出口点。","why":"colonial plus -ism names a whole practice, not a single colony or a single official.","whyCN":"colonial 加 -ism 命名的是一整套实践，而非单个殖民地或单个官员。"},{"no":"02","title":"The system of colonial government","titleCN":"殖民统治的制度","definition":"the administrative machinery through which a colony is governed, including law, police and taxation","definitionCN":"治理殖民地的行政机器，包括法律、警察与税收","example":"Colonialism built its administration around a governor and a police force.","exampleCN":"殖民主义围绕总督与警力搭建行政机构。","why":"A practice hardens into a system once offices, budgets and codes outlast the first conquerors.","whyCN":"一旦职位、预算与法典比第一批征服者活得更久，实践便固化为制度。"},{"no":"03","title":"The historical era of overseas expansion","titleCN":"海外扩张的历史时期","definition":"the period, especially from the sixteenth to the twentieth century, when European states built overseas empires","definitionCN":"欧洲国家建立海外帝国的时期，尤指十六至二十世纪","example":"The historiography of colonialism begins with the charter companies.","exampleCN":"殖民主义史学从特许公司开始写起。","why":"Historians use the abstract noun as an era label, just as they use imperialism for the same span seen politically.","whyCN":"史家用这个抽象名词作时期标签，正如用 imperialism 指同一段时期的政治面。"},{"no":"04","title":"Economic dependency after formal rule","titleCN":"正式统治之后的经济依附","definition":"the continuing control of a former colony's economy by foreign capital and markets","definitionCN":"外国资本与市场对前殖民地经济的持续控制","example":"Critics argued that colonialism survived independence as debt.","exampleCN":"批评者认为殖民主义以债务的形式在独立后延续下来。","why":"If the export route and the loan survive the flag, then the colonial relation survives too.","whyCN":"如果出口路线与贷款比旗帜活得更久，殖民关系也就活了下来。"},{"no":"05","title":"Cultural domination through schools and missions","titleCN":"通过学校与传教的文化支配","definition":"the imposition of a coloniser's language, religion and school curriculum on a colonised people","definitionCN":"把殖民者的语言、宗教与学校课程加于被殖民民族","example":"Colonialism also worked through schools and missions.","exampleCN":"殖民主义也通过学校与传教发挥作用。","why":"Rule needs consent as well as force, so the word extends to the institutions that reshape how people think.","whyCN":"统治既需武力也需认同，因此这个词扩展到重塑人们思想的机构。"},{"no":"06","title":"Settler colonialism","titleCN":"移民殖民主义","definition":"a form of colonialism in which settlers replace or displace the existing population and take the land","definitionCN":"移民取代或驱逐原有居民并夺取土地的一种殖民形态","example":"Settler colonialism sought land rather than labour.","exampleCN":"移民殖民主义要的是土地，而不是劳力。","why":"The compound separates two motives: extraction of labour and permanent occupation of ground.","whyCN":"这个复合词区分了两种动机：榨取劳力与永久占据土地。"},{"no":"07","title":"Internal colonialism within a state","titleCN":"国家内部的殖民关系","definition":"the domination of one region or people inside a country by its central power","definitionCN":"一国中央权力对境内某一地区或民族的支配","example":"The region complained of internal colonialism by the capital.","exampleCN":"该地区抱怨受到首都的内部殖民。","why":"The colonial pattern can be reproduced inside a border when one province supplies resources to another.","whyCN":"当一个行省向另一个行省供应资源时，殖民模式可在国界之内重演。"},{"no":"08","title":"The ideology and legacy studied after independence","titleCN":"独立后研究的意识形态与遗产","definition":"the body of assumptions and after-effects that postcolonial scholarship examines","definitionCN":"后殖民学术所考察的整套预设与后续影响","example":"Postcolonial writers examine the legacy of colonialism in language.","exampleCN":"后殖民作家考察殖民主义在语言中留下的遗产。","why":"Once the rule ended, the word shifted from events to memory: what remains in speech, schooling and law.","whyCN":"统治结束后，这个词从事件转向记忆：语言、教育与法律中留下了什么。"}],"etymology":{"intro":{"en":"Colonialism is an English formation from colonial plus -ism, which came through Latin -ismus from Greek -ismos. The political sense is modern. Dates are approximate.","cn":"colonialism 是英语由 colonial 加 -ism 构成的新词，-ism 经拉丁 -ismus 来自希腊 -ismos。政治义属近代。年代均为约数。"},"items":[{"era":"LATIN COLONIA","en":"Colonia 'settlement' is the base of the whole family, from colonus 'farmer, settler' and colere 'cultivate'.","cn":"colonia「定居点」是整个词族的基础，出自 colonus「农夫、移民」与 colere「耕种」。"},{"era":"ENGLISH COLONIAL","en":"The adjective colonial, borrowed from Latin colonialis, supplied the direct base of the new noun.","cn":"借自拉丁 colonialis 的形容词 colonial，提供了这个新名词的直接基础。"},{"era":"SUFFIX -ISM","en":"-ism names systems, doctrines and practices, as in realism and socialism.","cn":"-ism 用于命名体系、主张与实践，如 realism 与 socialism。"},{"era":"POLITICAL SENSE","en":"The noun appeared in the nineteenth century, when debates about overseas rule needed a term for the whole arrangement.","cn":"这个名词出现于十九世纪，当时关于海外统治的辩论需要指整套安排的术语。"},{"era":"TWENTIETH-CENTURY VARIANTS","en":"Settler colonialism, internal colonialism and neocolonialism were added as scholars separated different mechanisms of domination.","cn":"移民殖民主义、内部殖民主义与新殖民主义是后来加入的，学者借此区分不同的支配机制。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact first English citation is not established, and the earliest uses overlapped with 'colonization', so no single coinage can be named.","cn":"来源不确定（首见年代）：确切的最早英语书证未有定论，早期用法与「殖民化」重叠，无法指认唯一造词者。"}]},"similar":{"note":{"en":"Group one holds forms from the same colonia stock or accidental neighbours; group two holds rival terms for expansion and dependency.","cn":"第一组是同出 colonia 词干或偶然相邻的形式；第二组是表示扩张与依附的竞争性术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"colonial","ipa":"/kəˈləʊniəl/","tag":"base adjective","definition":"Simply 'of a colony'; it describes, while colonialism names the system and usually carries criticism.","definitionCN":"仅指「殖民地的」；是描述性的，而 colonialism 命名制度，通常带批评。"},{"word":"colonist","ipa":"/ˈkɒlənɪst/","tag":"person","definition":"A settler in a colony; colonialism is the system such settlers may serve or oppose.","definitionCN":"殖民地的移民；colonialism 是这些移民可能服务或反对的制度。"},{"word":"colonization","ipa":"/ˌkɒlənaɪˈzeɪʃn/","tag":"process","definition":"The act or process of founding a colony; colonialism is the wider ideology and structure, and can persist after colonization ends.","definitionCN":"建立殖民地的行为或过程；colonialism 是更广的意识形态与结构，可在殖民化结束后继续存在。"},{"word":"colon","ipa":"/ˈkəʊlən/","tag":"different root","definition":"From Greek kolon 'limb', meaning the large intestine or the punctuation mark; unrelated to settlement.","definitionCN":"出自希腊 kolon「肢体」，指大肠或冒号；与定居无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"imperialism","ipa":"/ɪmˈpɪəriəlɪzəm/","tag":"broader policy","definition":"The policy or ideology of extending power over other countries; colonialism is the specific practice of settling and governing colonies.","definitionCN":"把权力扩及他国的政策或意识形态；colonialism 是定居并治理殖民地的具体实践。"},{"word":"neocolonialism","ipa":"/ˌniːəʊkəˈləʊniəlɪzəm/","tag":"indirect control","definition":"Control of formally independent states through debt, trade and institutions; a later form, not the classic settlement empire.","definitionCN":"通过债务、贸易与制度控制名义上独立的国家；是较晚形态，不是经典定居帝国。"},{"word":"expansionism","ipa":"/ɪkˈspænʃənɪzəm/","tag":"territorial growth","definition":"A policy of enlarging territory; it names growth itself rather than the governing relationship that follows.","definitionCN":"扩大领土的政策；指扩张本身，而非随后的治理关系。"},{"word":"dependency","ipa":"/dɪˈpendənsi/","tag":"economic reliance","definition":"A condition in which one economy relies on another; colonialism can create it, but dependency is the outcome, not the system.","definitionCN":"一种经济依赖他者的状态；殖民主义可造成它，但 dependency 是结果而非制度。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"colonia 'settlement' + -alis 'relating to' + -ism 'system': the system built on settlements.","cn":"colonia「定居点」+ -alis「相关」+ -ism「体系」：建立在定居点上的制度。"},{"en":"The family runs colony, colonist, colonial, colonialism, colonialist, decolonization.","cn":"同族词包括 colony、colonist、colonial、colonialism、colonialist、decolonization。"},{"en":"Fixed phrases: settler colonialism, internal colonialism, the legacy of colonialism.","cn":"固定搭配：移民殖民主义、内部殖民主义、殖民主义的遗产。"},{"en":"imperialism is the policy, colonialism the practice; colonization is the act of founding a colony.","cn":"imperialism 是政策，colonialism 是实践，colonization 是建立殖民地的行为。"},{"en":"Colonialism can outlive the flag as debt, language and school curriculum.","cn":"殖民主义能以债务、语言与学校课程的形式活得比旗帜更久。"}],"abstract":[{"en":"Picture an account book heavier than the flag beside it.","cn":"想象一本账册比旁边的旗帜更重。"},{"en":"Picture a classroom map that shows only one harbour.","cn":"想象一张教室地图只画出一个港口。"},{"en":"Picture a border drawn with a ruler across a pasture.","cn":"想象一条用尺子划过牧场的边界。"}]},"examples":[{"en":"The course traced colonialism from trading posts to mandated territories.","cn":"这门课追溯殖民主义，从贸易站一直讲到委任统治地。"},{"en":"Settler colonialism left a different landscape from plantation rule.","cn":"移民殖民主义留下的景观与种植园统治不同。"},{"en":"The novel reads colonialism through the letters of a colonial clerk.","cn":"这部小说通过一名殖民地文书的信件来解读殖民主义。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「colonial」殖民地的 + 「ism」主义——把殖民地那套做法当成主张 → 殖民主义","word":"colonialism"},"root":"英语 colonial「殖民地的」+ -ism「体系、主张」；colonial 出自拉丁 colonialis，再上溯 colonia「定居点」与 colere「耕种」。英语 colonialism。","sensesIntro":{"en":"Eight senses follow one settlement as it grows into a system: a harbour, an administration, an era, a debt, a school, a settlement type, an internal province and a memory.","cn":"八个义项随一个定居点长成制度而展开：港口、行政机构、时代、债务、学校、定居类型、内部行省与记忆。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger pressing down a harbour map, with a land grant and a folded flag beside it.","cn":"核心意象：一本账册压住港口地图，旁边是土地授予书与折叠的旗。"},"chain":["SETTLEMENT","RULE","EXPANSION","ECONOMIC DEPENDENCY","CULTURAL DOMINATION","POSTCOLONIAL LEGACY"],"branches":[{"senses":"S1 · S2","en":"THE PRACTICE AND THE MACHINE: seizure hardens into offices, budgets and codes.","cn":"实践与机器：夺取固化为职位、预算与法典。"},{"senses":"S3","en":"THE ERA: historians turn the practice into a period label.","cn":"时代：史家把实践转为时期标签。"},{"senses":"S4","en":"THE DEBT: the export route and the loan outlive the flag.","cn":"债务：出口路线与贷款比旗帜活得更久。"},{"senses":"S5","en":"THE SCHOOL: consent is manufactured through language and curriculum.","cn":"学校：通过语言与课程制造认同。"},{"senses":"S6 · S7 · S8","en":"THREE VARIATIONS: settlers take land, a capital takes a province, and memory takes the aftermath.","cn":"三种变体：移民夺地、首都夺省、记忆承担后果。"}]},"affixes":{"intro":{"en":"Colonialism is a Latin-derived adjective plus a Greek-derived suffix, and both parts recur in English, so the family can be read morpheme by morpheme.","cn":"colonialism 是拉丁来源形容词加希腊来源后缀，两部分都在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin colere, colonus and colonia give colony and colonial; Greek -ismos, through Latin -ismus, gives -ism.","cn":"拉丁 colere、colonus 与 colonia 衍生 colony 与 colonial；希腊 -ismos 经拉丁 -ismus 形成 -ism。"},"items":[{"word":"colere","structure":"colere (Latin verb, 'to cultivate')","meaning":"to till, cultivate","meaningCN":"耕种；培育","example":"The root ties settlement to farming.","exampleCN":"这个词根把定居与农耕联系起来。"},{"word":"colonia","structure":"colonia, coloniae (Latin noun, 'settlement')","meaning":"settlement","meaningCN":"定居点","example":"The colonia became a port.","exampleCN":"这个定居点发展成港口。"},{"word":"-alis","structure":"-alis (Latin relational suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix built colonial from colonia.","exampleCN":"这个后缀由 colonia 构成 colonial。"},{"word":"colonial","structure":"colonia + -alis","meaning":"of a colony","meaningCN":"殖民地的","example":"Colonial rule lasted two generations.","exampleCN":"殖民统治延续了两代。"},{"word":"-ism","structure":"-ismus (Latin, from Greek -ismos)","meaning":"system or doctrine","meaningCN":"体系或主张","example":"The suffix also builds realism.","exampleCN":"这个后缀也构成 realism。"},{"word":"colonialism","structure":"colonial + -ism","meaning":"the system of ruling colonies","meaningCN":"统治殖民地的制度","example":"Colonialism reshaped the coast.","exampleCN":"殖民主义重塑了海岸。"},{"word":"colonialist","structure":"colonial + -ist (person)","meaning":"supporter of colonialism","meaningCN":"殖民主义的支持者","example":"The colonialist defended the settlement.","exampleCN":"这位殖民主义者为定居点辩护。"},{"word":"decolonization","structure":"de- (removal) + colonization","meaning":"the ending of colonial rule","meaningCN":"殖民统治的终结","example":"Decolonization redrew the map.","exampleCN":"非殖民化重画了地图。"},{"word":"neocolonialism","structure":"neo- (new) + colonialism","meaning":"indirect domination","meaningCN":"间接支配","example":"Neocolonialism works through loans.","exampleCN":"新殖民主义通过贷款运作。"},{"word":"postcolonial","structure":"post- (after) + colonial","meaning":"after colonial rule","meaningCN":"殖民统治之后的","example":"Postcolonial writing revisits the archive.","exampleCN":"后殖民写作重访档案。"}],"latinEntries":[{"word":"colere","structure":"colere, colui, cultum (verb, third conjugation)","meaning":"to till, cultivate, inhabit","meaningCN":"耕种；培育；居住"},{"word":"colonia","structure":"colonia, coloniae (f., first declension)","meaning":"settlement, colony","meaningCN":"定居点；殖民地"},{"word":"colonialis","structure":"colonialis, coloniale (adjective, third declension)","meaning":"of a settlement","meaningCN":"定居点的"}]}},{"word":"colonist","ipa_uk":"/ˈkɒlənɪst/","ipa_us":"/ˈkɑːlənɪst/","definition_zh":"殖民者；殖民地移民；殖民远征队成员；拓荒者；兵屯移民；（生态）率先定殖的生物","definition_en":"a settler who moves into and occupies a new territory as part of a colony, and by extension a pioneer species that first establishes itself in a habitat","core_image":"一个人背着工具站在刚清出的空地边，身后是木桩与尚未盖顶的屋架","scene":"林边的空地上立着几根木桩，一个人背着斧头与种子袋站在尚未封顶的屋架旁。The first colonists cleared the marsh and planted maize before winter.","sceneCN":"这里 colonist 指「迁入并定居殖民地的移民」（第 1 个义项：在殖民地安家耕种的人）；句意为第一批移民在冬天前清理沼泽并种下玉米。可辨识物件：木桩、空地、斧头、种子袋、屋架。","pos":[{"tag":"n.","zh":"殖民者；殖民地移民；拓荒者；（生态）定殖生物"}],"collocations":[{"phrase":"early colonists","zh":"早期殖民者"},{"phrase":"European colonists","zh":"欧洲殖民者"},{"phrase":"a colonist family","zh":"殖民者家庭"},{"phrase":"colonist settlement","zh":"殖民者定居点"},{"phrase":"the first colonists","zh":"第一批殖民者"},{"phrase":"colonist species","zh":"定殖物种"}],"forms":[{"label":"单数","form":"colonist"},{"label":"复数","form":"colonists"},{"label":"形容词（殖民地的）","form":"colonial"},{"label":"名词（殖民地）","form":"colony"},{"label":"名词（殖民主义）","form":"colonialism"},{"label":"动词（建立殖民地）","form":"colonize"}],"derivatives":[{"word":"colony","pos":"n.","zh":"colonist 去掉 -ist 回溯到拉丁 colonia → 殖民地，语义由人转为地方"},{"word":"colonial","pos":"adj.","zh":"colonia + -alis（关系形容词后缀）→ 殖民地的，语义由人转为属性"},{"word":"colonialism","pos":"n.","zh":"colonial + -ism（体系后缀）→ 殖民主义，语义由属性转为制度"},{"word":"colonize","pos":"v.","zh":"colony + -ize（动词后缀）→ 建立殖民地、移居开拓"},{"word":"colonization","pos":"n.","zh":"colonize + -ation（过程后缀）→ 殖民过程、建立定居点"},{"word":"colonizer","pos":"n.","zh":"colonize + -er（施动者后缀）→ 殖民者，较 colonist 更强调主动建立的动作"}],"senses":[{"no":"01","title":"A settler in a colony","titleCN":"殖民地的移民","definition":"a person who settles in a new territory as part of a colony and works its land","definitionCN":"作为殖民地的一部分在新领土定居并耕种其土地的人","example":"The first colonists cleared the marsh and planted maize before winter.","exampleCN":"第一批移民在冬天前清理沼泽并种下玉米。","why":"Colony plus -ist makes a person noun, so the word names the human unit of a settlement.","whyCN":"colony 加 -ist 构成人称名词，因此这个词指定居点中的人这一单位。"},{"no":"02","title":"An inhabitant of the American colonies","titleCN":"美洲英属殖民地的居民","definition":"historically, a resident of the British colonies in North America before independence","definitionCN":"历史上指独立前北美英属殖民地的居民","example":"Colonists protested the stamp tax in every port town.","exampleCN":"各港口城镇的殖民地居民都抗议印花税。","why":"American history narrowed the general word to one political community, and the capitalised phrase still marks it.","whyCN":"美国历史把这个通用词收窄到一个政治共同体，大写词组仍标记这一用法。"},{"no":"03","title":"A member of a colonising expedition","titleCN":"殖民远征队成员","definition":"a person who travels with an expedition to found a settlement","definitionCN":"随远征队前往建立定居点的人","example":"The expedition carried tools for the colonists who would follow.","exampleCN":"远征队为随后到来的移民携带了工具。","why":"Settlement begins as a journey, so colonist can name the traveller before he is a resident.","whyCN":"定居始于旅程，因此 colonist 可指尚未成为居民的行进者。"},{"no":"04","title":"A pioneer of a new region","titleCN":"新地区的拓荒者","definition":"the first person or family to open land in a district and make it habitable","definitionCN":"在某地区最早开垦土地并使之可居住的个人或家庭","example":"He was a colonist of the upper valley, arriving before the roads.","exampleCN":"他是上游山谷的拓荒者，在道路修通之前就到了。","why":"The word's core is the act of planting oneself somewhere, which makes it a near neighbour of pioneer.","whyCN":"这个词的核心是把自己「栽种」在某处，因此与拓荒者意义相近。"},{"no":"05","title":"A species that first occupies a habitat","titleCN":"率先定殖某生境的物种","definition":"in ecology, an organism that is among the first to establish itself on bare or disturbed ground","definitionCN":"生态学中指最早在裸地或受扰地建立种群的生物之一","example":"Lichens are among the first colonists on bare rock.","exampleCN":"地衣是裸岩上最早的定殖者之一。","why":"Ecology borrowed the settlement image: a species occupies new ground just as a settler occupies new land.","whyCN":"生态学借用了定居意象：物种占据新地，正如移民占据新土。"},{"no":"06","title":"A soldier given land in a frontier colony","titleCN":"在边疆殖民地受田的士兵","definition":"a soldier settled on frontier land in exchange for military service","definitionCN":"以服兵役为条件在边疆受田定居的士兵","example":"The crown gave land to soldier colonists on the frontier.","exampleCN":"王室把边疆土地授予兵屯移民。","why":"Empires sometimes paid soldiers in ground rather than coin, and the compound marks that arrangement.","whyCN":"帝国有时用土地而非钱币支付士兵，这个复合词标记这种安排。"},{"no":"07","title":"A settler in a British settler colony","titleCN":"英国移民殖民地的定居者","definition":"historically, a British settler sent to a colony such as South Africa or Australia","definitionCN":"历史上被派往南非或澳大利亚等殖民地的英国移民","example":"The colonists arrived by ship and named the valley after their home county.","exampleCN":"这些移民乘船抵达，用家乡郡名给山谷命名。","why":"The word is standard in histories of settler colonies, where arrival and naming are the founding acts.","whyCN":"在移民殖民地的史书里，这个词是标准用语，抵达与命名正是奠基行为。"},{"no":"08","title":"One who opens a new field of activity","titleCN":"开辟新领域的人","definition":"figuratively, a person who establishes a presence in an unclaimed area of work or technology","definitionCN":"比喻指在未开垦的工作或技术领域建立据点的人","example":"The first colonists of the network wrote their own rules.","exampleCN":"这片网络最早的开拓者自己写下了规则。","why":"The metaphor keeps the act of claiming unoccupied ground but drops the imperial frame.","whyCN":"这一比喻保留了「占据无主之地」的动作，却去掉了帝国框架。"}],"etymology":{"intro":{"en":"Colonist is an English formation from colony plus -ist, with colony from Latin colonia 'settlement' and colonus 'farmer'. Dates are approximate.","cn":"colonist 是英语由 colony 加 -ist 构成的词，colony 出自拉丁 colonia「定居点」与 colonus「农夫」。年代均为约数。"},"items":[{"era":"LATIN COLERE","en":"Colere 'to cultivate' is the deepest root, linking settlement to farming rather than to conquest.","cn":"colere「耕种」是最深的词根，把定居与农耕而非征服联系起来。"},{"era":"LATIN COLONUS","en":"Colonus named a farmer or tenant, the person who works the land.","cn":"colonus 指农夫或佃户，即耕种土地的人。"},{"era":"LATIN COLONIA","en":"Colonia named the settlement itself, a body of citizens planted abroad.","cn":"colonia 指定居点本身，即被安置到海外的公民群体。"},{"era":"ENGLISH COLONY","en":"English colony appeared in the sixteenth century, and colonist followed as the person noun.","cn":"英语 colony 出现于十六世纪，colonist 随后作为人称名词出现。"},{"era":"AMERICAN AND ECOLOGICAL USES","en":"American history fixed colonist to the pre-independence inhabitants, and ecology later borrowed it for pioneer species.","cn":"美国历史把 colonist 固定到独立前的居民，生态学后来借它指先锋物种。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the exact first English citation is not established, and the ecological sense has no single documented origin.","cn":"来源不确定（首见年代）：确切的最早英语书证未有定论，生态义也没有唯一可考来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same colonia stock or accidental look-alikes; group two holds words for people who move into new land.","cn":"第一组是同出 colonia 词干或偶然形近的形式；第二组是表示迁入新土地者的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"colonial","ipa":"/kəˈləʊniəl/","tag":"same root, adjective","definition":"The adjective 'of a colony'; colonist is the person who lives in one.","definitionCN":"「殖民地的」形容词；colonist 是住在其中的人。"},{"word":"colony","ipa":"/ˈkɒləni/","tag":"same root, place","definition":"The settlement itself, from colonia; the person noun is built on it.","definitionCN":"定居点本身，出自 colonia；人称名词由它构成。"},{"word":"colonialism","ipa":"/kəˈləʊniəlɪzəm/","tag":"same root, system","definition":"The system and ideology of ruling colonies; a colonist may be an agent or a subject of it.","definitionCN":"统治殖民地的制度与意识形态；colonist 可能是其实施者或受治者。"},{"word":"colon","ipa":"/ˈkəʊlən/","tag":"different root","definition":"From Greek kolon 'limb', the intestine or the punctuation mark; unrelated to settlement.","definitionCN":"出自希腊 kolon「肢体」，指肠道或冒号；与定居无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"settler","ipa":"/ˈsetlə/","tag":"general word","definition":"Anyone who settles in a new region; colonist adds the frame of a colony and its government.","definitionCN":"任何在新地区定居的人；colonist 增添了殖民地及其政府的框架。"},{"word":"pioneer","ipa":"/ˌpaɪəˈnɪə/","tag":"first opener","definition":"The first to open a region or a field; it stresses priority rather than colonial status.","definitionCN":"最早开辟某地区或领域的人；强调先行，而非殖民身份。"},{"word":"colonizer","ipa":"/kəˈlənaɪzə/","tag":"active agent","definition":"One who founds a colony; it stresses the act of establishing, while colonist stresses residence.","definitionCN":"建立殖民地的人；强调建立的动作，而 colonist 强调居住。"},{"word":"immigrant","ipa":"/ˈɪmɪɡrənt/","tag":"newcomer","definition":"A person who moves to another country to live; the word carries no claim of governing the place.","definitionCN":"移居另一国生活的人；这个词不含对该地行使统治的主张。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"colony + -ist: the person who lives in a planted settlement.","cn":"colony + -ist：住在拓殖定居点里的人。"},{"en":"The family runs colony, colonist, colonial, colonialism, colonize, colonizer.","cn":"同族词包括 colony、colonist、colonial、colonialism、colonize、colonizer。"},{"en":"Fixed phrases: early colonists, European colonists, colonist family.","cn":"固定搭配：早期殖民者、欧洲殖民者、殖民者家庭。"},{"en":"Ecology says a lichen is a colonist of bare rock.","cn":"生态学说地衣是裸岩的定殖者。"},{"en":"colonist stresses living there; colonizer stresses founding it.","cn":"colonist 强调住在那里，colonizer 强调建立它。"}],"abstract":[{"en":"Picture an axe and a seed bag leaning against an unfinished frame.","cn":"想象斧头与种子袋靠在尚未完工的屋架上。"},{"en":"Picture a name on a map copied from a distant county.","cn":"想象地图上的一个名字抄自远方的郡。"},{"en":"Picture moss arriving on bare stone before anything else.","cn":"想象苔藓在其他一切之前先落到裸石上。"}]},"examples":[{"en":"The colonists dug a ditch that still drains the field.","cn":"殖民者挖的那条沟至今仍在排田里的水。"},{"en":"A colonist's diary records the first frost and the first harvest.","cn":"一位移民的日记记下了初霜与第一次收成。"},{"en":"The ecologist counted each colonist species on the cooled lava.","cn":"生态学家清点了冷却熔岩上的每一种定殖物种。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「colony」殖民地 + 「ist」人——在殖民地安家的人 → 殖民者","word":"colonist"},"root":"英语 colony「殖民地」+ -ist（人称后缀）；colony 出自拉丁 colonia「定居点」，再上溯 colonus「耕种者」与 colere「耕种」。英语 colonist。","sensesIntro":{"en":"Eight senses follow one person planting a life somewhere new: a settler, an American colonial, an expedition member, a pioneer, a lichen, a soldier-farmer, a British emigrant and a founder of a new field.","cn":"八个义项随一个人在新地方扎根而展开：移民、美洲殖民地居民、远征队员、拓荒者、地衣、兵屯移民、英国移民与开辟新领域者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person with an axe and a seed bag standing beside boundary posts and an unfinished roof frame.","cn":"核心意象：一个人背着斧头与种子袋，站在界桩与未完工的屋架旁。"},"chain":["SETTLER","PIONEER","EXPEDITION MEMBER","COLONIAL SUBJECT","SOLDIER-SETTLER","COLONIZING ORGANISM"],"branches":[{"senses":"S1 · S4","en":"THE SETTLER: the first family to make a district habitable.","cn":"移民：最早使某地区可居住的家庭。"},{"senses":"S2","en":"THE POLITICAL COMMUNITY: American history narrows the word to one set of inhabitants.","cn":"政治共同体：美国历史把这词收窄到一组居民。"},{"senses":"S3","en":"THE JOURNEY: a colonist can be a traveller before becoming a resident.","cn":"旅程：移民在成为居民之前可以是行进者。"},{"senses":"S6 · S7","en":"THE IMPERIAL ARRANGEMENT: soldiers paid in land and British settlers sent abroad.","cn":"帝国安排：以土地支付士兵，并把英国移民派往海外。"},{"senses":"S5 · S8","en":"THE METAPHOR: lichens and network builders both occupy empty ground.","cn":"比喻：地衣与网络建设者都在占据空地。"}]},"affixes":{"intro":{"en":"Colonist is a Latin-derived noun plus a person suffix; the parts recur in English, so the family can be read morpheme by morpheme.","cn":"colonist 是拉丁来源名词加人称后缀，各部分在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin colere and colonia give colony; the suffix -ist makes colonist, and -ize makes colonize.","cn":"拉丁 colere 与 colonia 衍生 colony；后缀 -ist 构成 colonist，-ize 构成 colonize。"},"items":[{"word":"colere","structure":"colere (Latin verb, 'to cultivate')","meaning":"to till, cultivate","meaningCN":"耕种；培育","example":"The root ties settlement to farming.","exampleCN":"这个词根把定居与农耕联系起来。"},{"word":"colonus","structure":"colere + -onus (agent noun)","meaning":"farmer, settler","meaningCN":"农夫；移民","example":"A colonus worked the land he held.","exampleCN":"移民耕种自己持有的土地。"},{"word":"colonia","structure":"colonus + -ia (place noun)","meaning":"settlement","meaningCN":"定居点","example":"The colonia grew into a port.","exampleCN":"定居点发展成港口。"},{"word":"colony","structure":"colonia, through Latin and English","meaning":"a settlement","meaningCN":"定居点；殖民地","example":"The colony exported timber.","exampleCN":"这块殖民地出口木材。"},{"word":"-ist","structure":"-ista (Latin, from Greek -istes), person suffix","meaning":"one who does or belongs","meaningCN":"从事或属于……的人","example":"The suffix also builds colonialist and scientist.","exampleCN":"这个后缀也构成 colonialist 与 scientist。"},{"word":"colonist","structure":"colony + -ist","meaning":"a settler","meaningCN":"移民；殖民者","example":"The colonist cleared the field.","exampleCN":"移民清理了田地。"},{"word":"colonial","structure":"colonia + -alis","meaning":"of a colony","meaningCN":"殖民地的","example":"Colonial rule lasted two generations.","exampleCN":"殖民统治延续了两代。"},{"word":"colonize","structure":"colony + -ize (verb)","meaning":"to found a colony","meaningCN":"建立殖民地","example":"Settlers colonized the river mouth.","exampleCN":"移民在河口建立了殖民地。"},{"word":"colonizer","structure":"colonize + -er (agent)","meaning":"one who founds a colony","meaningCN":"建立殖民地的人","example":"The colonizer mapped the coast.","exampleCN":"殖民者测绘了海岸。"},{"word":"colonialism","structure":"colonial + -ism (system)","meaning":"the system of ruling colonies","meaningCN":"统治殖民地的制度","example":"Colonialism reshaped the coast.","exampleCN":"殖民主义重塑了海岸。"}],"latinEntries":[{"word":"colere","structure":"colere, colui, cultum (verb, third conjugation)","meaning":"to till, cultivate, inhabit","meaningCN":"耕种；培育；居住"},{"word":"colonus","structure":"colonus, coloni (m., second declension)","meaning":"farmer, settler","meaningCN":"农夫；移民"},{"word":"colonia","structure":"colonia, coloniae (f., first declension)","meaning":"settlement, colony","meaningCN":"定居点；殖民地"}]}},{"word":"independence","ipa_uk":"/ˌɪndɪˈpendəns/","ipa_us":"/ˌɪndɪˈpendəns/","definition_zh":"独立；不受外部控制的状态；国家独立；个人自立；财务自主；统计与逻辑中的独立性；机构不受政治干预","definition_en":"freedom from the control of another; the state of a self-governing country; personal or financial self-reliance; and in statistics or logic, the absence of a necessary link","core_image":"一根柱子独自立在自己的地基上，四周没有支撑的绳索","scene":"空地上只立着一根石柱，柱脚有自己浇铸的基座，四周没有一根拉索。The region declared independence after a long period of negotiation.","sceneCN":"这里 independence 指「不受外部控制的状态」（第 1 个义项：自行决定自身事务）；句意为这个地区在长期谈判后宣布独立。可辨识物件：石柱、基座、空地、无拉索、公告文本。","pos":[{"tag":"n.","zh":"独立；自主；自立；独立性（多作不可数）"}],"collocations":[{"phrase":"declare independence","zh":"宣布独立"},{"phrase":"gain independence","zh":"获得独立"},{"phrase":"financial independence","zh":"财务独立"},{"phrase":"independence of mind","zh":"思想独立"},{"phrase":"judicial independence","zh":"司法独立"},{"phrase":"statistical independence","zh":"统计独立性"},{"phrase":"Independence Day","zh":"独立日"}],"forms":[{"label":"通常形式（不可数）","form":"independence"},{"label":"复数（指多次独立事件，较少用）","form":"independences"},{"label":"形容词（独立的）","form":"independent"},{"label":"副词（独立地）","form":"independently"},{"label":"名词（独立者、无党派者）","form":"independent"}],"derivatives":[{"word":"independent","pos":"adj./n.","zh":"in-（否定前缀）+ dependent（依赖的）→ 独立的，语义由「不依赖」转为形容词与人称"},{"word":"independently","pos":"adv.","zh":"independent + -ly（副词后缀）→ 独立地"},{"word":"interdependent","pos":"adj.","zh":"inter-（相互前缀）+ dependent → 相互依存的，语义指向与独立相反的关系"},{"word":"dependency","pos":"n.","zh":"depend + -ency（状态后缀）→ 依赖、附属地，语义与 independence 相对"},{"word":"dependence","pos":"n.","zh":"depend + -ence（状态后缀）→ 依赖状态"}],"senses":[{"no":"01","title":"Freedom from another's control","titleCN":"不受他者控制的状态","definition":"the condition of not being ruled, directed or constrained by another party","definitionCN":"不被另一方统治、指挥或约束的状态","example":"The region declared independence after a long period of negotiation.","exampleCN":"这个地区在长期谈判后宣布独立。","why":"In- 'not' plus dependence literally names the absence of hanging from another.","whyCN":"in-「不」加 dependence 字面就是「不悬挂于他者」，即不依附。"},{"no":"02","title":"The status of a self-governing country","titleCN":"自治国家的地位","definition":"the recognised legal status of a state that governs itself and is not subject to another","definitionCN":"一国自我治理、不受他国支配的被承认的法律地位","example":"Recognition of independence followed the peace treaty.","exampleCN":"和平条约之后，独立地位得到承认。","why":"Political history made the abstract condition into a formal status that other states can recognise.","whyCN":"政治史把这一抽象状态变成他国可以承认的正式地位。"},{"no":"03","title":"Personal self-reliance","titleCN":"个人的自立","definition":"the ability to live and decide without relying on others for direction","definitionCN":"无需他人指引即可生活与决策的能力","example":"She valued her independence more than a secure salary.","exampleCN":"她看重独立胜过一份稳定的薪水。","why":"The same image of not hanging from another applies to a person as much as to a state.","whyCN":"「不悬挂于他者」这一意象既适用于国家，也适用于个人。"},{"no":"04","title":"Financial self-sufficiency","titleCN":"财务上的自足","definition":"the state of having enough income or assets not to depend on others for money","definitionCN":"拥有足够收入或资产、无需靠他人供给金钱的状态","example":"The pension gave him financial independence.","exampleCN":"这笔养老金让他获得财务独立。","why":"Money is the commonest rope of dependence, so ending it is the commonest use of the word.","whyCN":"金钱是最常见的依附绳索，因此切断它是这个词最常见的用法。"},{"no":"05","title":"Statistical independence","titleCN":"统计上的独立性","definition":"the condition in which the occurrence of one event does not change the probability of another","definitionCN":"一事件的发生不改变另一事件概率的情形","example":"The two variables show independence in the sample.","exampleCN":"这两个变量在样本中表现出独立性。","why":"Statistics borrowed the word for variables that do not lean on one another, which is dependence in a mathematical sense.","whyCN":"统计学借这个词指不相互倚靠的变量，这里的「依赖」是数学意义上的。"},{"no":"06","title":"Logical independence of axioms","titleCN":"公理的逻辑独立性","definition":"the property of an axiom that cannot be derived from the others in a system","definitionCN":"某一公理无法由系统内其他公理导出的性质","example":"Mathematicians proved the independence of that axiom.","exampleCN":"数学家证明了那条公理的独立性。","why":"Logic needs a word for a statement that stands on its own, and the same metaphor of no support applies.","whyCN":"逻辑学需要一个词指自行成立的命题，同样适用「无支撑」的比喻。"},{"no":"07","title":"Independence Day and the revolutionary anniversary","titleCN":"独立日与革命纪念","definition":"the public holiday marking a nation's declaration of independence, especially in the United States","definitionCN":"纪念一国宣布独立的公共节日，尤指美国","example":"The town holds a parade every Independence Day.","exampleCN":"这个镇每年独立日都举行游行。","why":"A proper name fixed the abstract noun to one historical declaration and its annual memory.","whyCN":"专有名称把这个抽象名词固定到一次历史宣言及其年度纪念。"},{"no":"08","title":"Institutional freedom from political pressure","titleCN":"机构不受政治压力的独立","definition":"the condition in which a court, bank or broadcaster acts without direction from the government","definitionCN":"法院、银行或广播机构不受政府指挥而行事的状态","example":"Judicial independence protects the court from the ministry.","exampleCN":"司法独立使法院不受部委干预。","why":"Modern institutions claim the state's self-rule for themselves, so a court can be independent of the state that funds it.","whyCN":"现代机构把国家的自治套用到自身，因此法院可以独立于资助它的国家。"}],"etymology":{"intro":{"en":"Independence is the negative noun of dependence, from Latin dependere 'to hang from', built on de- 'down' and pendere 'to hang'. Dates are approximate.","cn":"independence 是 dependence 的否定名词，出自拉丁 dependere「悬挂于」，由 de-「向下」与 pendere「悬挂」构成。年代均为约数。"},"items":[{"era":"LATIN PENDERE","en":"Pendere meant 'to hang'; it also gives pendant, pendulum and suspend.","cn":"pendere 意为「悬挂」，也衍生 pendant、pendulum 与 suspend。"},{"era":"LATIN DEPENDERE","en":"De- 'down' plus pendere produced dependere 'to hang down from, to be attached to'.","cn":"de-「向下」加 pendere 构成 dependere「自……垂下、附着于」。"},{"era":"ENGLISH DEPENDENCE","en":"Dependence entered English through French, naming the state of being attached to or supported by another.","cn":"dependence 经法语进入英语，指附着于或受另一者支撑的状态。"},{"era":"NEGATION WITH IN-","en":"The Latin negative in- was added to make independence, literally 'not hanging from'.","cn":"加上拉丁否定前缀 in- 构成 independence，字面即「不悬挂于」。"},{"era":"POLITICAL USE","en":"In the seventeenth century the word was applied to churches and then to states, and the American declaration of 1776 fixed the political sense.","cn":"十七世纪这个词先用于教会，后用于国家；1776 年的美国宣言固定了政治义。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English citation is not established precisely, and the statistical and logical senses developed separately without a single documented source.","cn":"来源不确定（首见年代）：最早的英语书证并不确切，统计义与逻辑义各自发展，没有唯一可考来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same pendere stock or accidental neighbours; group two holds words for freedom and self-rule.","cn":"第一组是同出 pendere 词干或偶然相邻的形式；第二组是表示自由与自治的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","tag":"same root, adjective","definition":"The adjective and person noun; independence is the abstract state.","definitionCN":"形容词与人称名词；independence 是抽象状态。"},{"word":"dependence","ipa":"/dɪˈpendəns/","tag":"same root, opposite","definition":"The state of relying on another, from dependere 'hang from'; independence is its negation.","definitionCN":"依赖他者的状态，出自 dependere「悬挂于」；independence 是它的否定。"},{"word":"dependency","ipa":"/dɪˈpendənsi/","tag":"same root, territory","definition":"A territory governed by another state, or a condition of reliance; it is the noun of subordination.","definitionCN":"受他国治理的领土，或依赖状态；是表示从属的名词。"},{"word":"pendant","ipa":"/ˈpendənt/","tag":"same root, object","definition":"Something that hangs, from pendere; it shares the physical image but not the political sense.","definitionCN":"悬挂之物，出自 pendere；共享物理意象，但无政治义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"autonomy","ipa":"/ɔːˈtɒnəmi/","tag":"self-rule","definition":"The right of a group to govern itself, often within a larger state; independence usually means full separation.","definitionCN":"一个群体自我治理的权利，常在一国之内；independence 通常指完全分离。"},{"word":"sovereignty","ipa":"/ˈsɒvrənti/","tag":"legal authority","definition":"Supreme legal authority; independence names the fact of being free, sovereignty the authority that follows.","definitionCN":"最高法律权威；independence 指自由的事实，sovereignty 指随之而来的权威。"},{"word":"freedom","ipa":"/ˈfriːdəm/","tag":"general word","definition":"The general condition of not being constrained; independence is narrower and often political or financial.","definitionCN":"不受约束的一般状态；independence 更窄，常指政治或财务。"},{"word":"self-reliance","ipa":"/ˌself rɪˈlaɪəns/","tag":"personal","definition":"Trusting one's own powers rather than others'; it is the personal version of independence.","definitionCN":"信赖自身能力而非他人；是 independence 的个人版本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'not' + dependere 'hang from' + -ence 'state': the state of not hanging from anyone.","cn":"in-「不」+ dependere「悬挂于」+ -ence「状态」：不悬挂于任何人的状态。"},{"en":"The family runs depend, dependent, dependence, independent, independence, interdependent.","cn":"同族词包括 depend、dependent、dependence、independent、independence、interdependent。"},{"en":"Fixed phrases: declare independence, financial independence, judicial independence.","cn":"固定搭配：宣布独立、财务独立、司法独立。"},{"en":"pendere 'hang' also gives pendant, pendulum and suspend.","cn":"pendere「悬挂」也衍生 pendant、pendulum 与 suspend。"},{"en":"The American holiday fixed the abstract noun to one declaration and its parade.","cn":"美国的节日把这个抽象名词固定到一次宣言及其游行。"}],"abstract":[{"en":"Picture a column standing on its own footing with no guy ropes.","cn":"想象一根柱子立在自己的基座上，没有一根拉索。"},{"en":"Picture a bank account that no relative can draw from.","cn":"想象一个亲戚都取不出钱的银行账户。"},{"en":"Picture a court whose budget cannot buy its verdicts.","cn":"想象一间法院，其预算买不到它的判决。"}]},"examples":[{"en":"The colony gained independence after a decade of strikes and talks.","cn":"这块殖民地在十年罢工与谈判后获得独立。"},{"en":"He kept his independence by refusing the loan.","cn":"他拒绝那笔贷款，从而保持独立。"},{"en":"The two events show independence only if the first does not alter the second.","cn":"只有当第一个事件不改变第二个时，两者才表现出独立性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in」不 + 「depend」依靠 + 「ence」状态——不依靠别人的状态 → 独立","word":"independence"},"root":"in-（否定前缀）+ dependence「依赖」；dependence 出自拉丁 dependere「悬挂于」= de-「向下」+ pendere「悬挂」。英语 independence。","sensesIntro":{"en":"Eight senses follow one column standing without support: a region, a state, a person, a purse, two variables, an axiom, a holiday and a court.","cn":"八个义项随一根无支撑的柱子展开：一个地区、一个国家、一个人、一个钱包、两个变量、一条公理、一个节日与一间法院。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single column on its own cast footing, with no guy ropes attached.","cn":"核心意象：一根柱子立在自己浇铸的基座上，没有一根拉索。"},"chain":["NO CONTROL","NATIONAL FREEDOM","PERSONAL AUTONOMY","FINANCIAL SELF-SUPPORT","STATISTICAL SEPARATION","INSTITUTIONAL NEUTRALITY"],"branches":[{"senses":"S1 · S2 · S8","en":"NO HIGHER AUTHORITY: a region, a state and a court all refuse direction from above.","cn":"无更高权威：地区、国家与法院都拒绝来自上方的指挥。"},{"senses":"S3 · S4","en":"NO PERSONAL ROPE: a life and a purse can stand without another's support.","cn":"无个人绳索：生活与钱包都能不靠他人支撑而立。"},{"senses":"S5","en":"NO STATISTICAL LEAN: one event leaves another's probability unchanged.","cn":"无统计倚靠：一个事件不改变另一事件的概率。"},{"senses":"S6","en":"NO DERIVATION: an axiom cannot be obtained from its neighbours.","cn":"无推导：一条公理无法从相邻公理得到。"},{"senses":"S7","en":"NO ANNUAL ROPE: a holiday commemorates the moment the rope was cut.","cn":"无年度绳索：节日纪念绳索被剪断的那一刻。"}]},"affixes":{"intro":{"en":"Independence is a negative prefix plus a verb root and a state suffix, and all three parts recur in English, so the family can be read morpheme by morpheme.","cn":"independence 是否定前缀加动词词根再加状态后缀，三部分都在英语中反复出现，因此整个词族可按语素逐个读出。"},"latinIntro":{"en":"Latin pendere and dependere give depend, dependence and independent; in- negates the whole.","cn":"拉丁 pendere 与 dependere 衍生 depend、dependence 与 independent；in- 否定整个词。"},"items":[{"word":"pendere","structure":"pendere, pependi, pensum (Latin verb, 'to hang')","meaning":"to hang","meaningCN":"悬挂","example":"The root also gives pendulum and pendant.","exampleCN":"这个词根也衍生 pendulum 与 pendant。"},{"word":"de-","structure":"de- (Latin prefix, 'down, from')","meaning":"down; away from","meaningCN":"向下；离开","example":"The prefix adds direction to the hanging.","exampleCN":"这个前缀给「悬挂」加上方向。"},{"word":"dependere","structure":"de- + pendere","meaning":"to hang from, rely on","meaningCN":"悬挂于；依赖","example":"The verb pictures one thing resting on another.","exampleCN":"这个动词描绘一物依附于另一物。"},{"word":"-ence","structure":"-entia (Latin state suffix, -ence in English)","meaning":"state or quality","meaningCN":"状态或性质","example":"The suffix turns the verb into a state.","exampleCN":"这个后缀把动词转为状态。"},{"word":"dependence","structure":"depend + -ence","meaning":"the state of relying on another","meaningCN":"依赖他者的状态","example":"Dependence on one buyer weakened the port.","exampleCN":"对单一买家的依赖削弱了这个港口。"},{"word":"in-","structure":"in- (Latin negative prefix, 'not')","meaning":"not","meaningCN":"不","example":"The prefix negates the whole noun.","exampleCN":"这个前缀否定整个名词。"},{"word":"independence","structure":"in- + dependence","meaning":"the state of not relying on another","meaningCN":"不依赖他者的状态","example":"The region declared independence.","exampleCN":"这个地区宣布独立。"},{"word":"independent","structure":"in- + dependent","meaning":"not relying on another","meaningCN":"不依赖他者的","example":"An independent court judged the case.","exampleCN":"一个独立的法院审理了此案。"},{"word":"interdependent","structure":"inter- (between) + dependent","meaning":"relying on each other","meaningCN":"相互依赖的","example":"The two ports were interdependent.","exampleCN":"这两个港口相互依赖。"},{"word":"dependency","structure":"depend + -ency (state)","meaning":"reliance, or a subject territory","meaningCN":"依赖；附属地","example":"The island was a dependency of the crown.","exampleCN":"这座岛曾是王室的附属地。"}],"latinEntries":[{"word":"pendere","structure":"pendere, pependi, pensum (verb, third conjugation)","meaning":"to hang","meaningCN":"悬挂"},{"word":"dependere","structure":"dependere, dependi, dependum (verb, third conjugation)","meaning":"to hang from, rely on","meaningCN":"悬挂于；依赖"},{"word":"dependentia","structure":"dependentia, dependentiae (f., first declension)","meaning":"dependence","meaningCN":"依赖"}]}}]);
